<template>
  <div v-if="isOpen" class="modal-overlay" @click.self="handleCancel">
    <div class="modal-box" @click.stop>
      <div class="modal-header">
        <h3>絞り込み・並び替え</h3>
        <button type="button" class="close-btn" @click="handleCancel">✕</button>
      </div>
      <div class="modal-body">
        <section class="settings-section">
          <div class="settings-section-head">
            <h4>MC</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" @click="selectAll('mcIds', mcOptions)">すべて選択</button>
              <button type="button" class="link-btn" @click="clearSection('mcIds')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in mcOptions" :key="`mc-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.mcIds.includes(option.value)" @change="toggleNumber('mcIds', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section">
          <div class="settings-section-head">
            <h4>年度</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" @click="selectAll('instructionYears', instructionYearOptions)">すべて選択</button>
              <button type="button" class="link-btn" @click="clearSection('instructionYears')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in instructionYearOptions" :key="`iy-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.instructionYears.includes(option.value)" @change="toggleNumber('instructionYears', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section">
          <div class="settings-section-head">
            <h4>状態</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" @click="selectAll('jkkStatusIds', jkkStatusOptions)">すべて選択</button>
              <button type="button" class="link-btn" @click="clearSection('jkkStatusIds')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in jkkStatusOptions" :key="`jk-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.jkkStatusIds.includes(option.value)" @change="toggleNumber('jkkStatusIds', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section">
          <div class="settings-section-head">
            <h4>登録</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" @click="selectAll('registrationYears', registrationYearOptions)">すべて選択</button>
              <button type="button" class="link-btn" @click="clearSection('registrationYears')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in registrationYearOptions" :key="`ry-${option.value}`" class="option-item">
              <input type="checkbox" :checked="draft.registrationYears.includes(option.value)" @change="toggleNumber('registrationYears', option.value)" />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section settings-section--toggles">
          <button
            type="button"
            class="hide-toggle"
            :class="{ 'hide-toggle--on': draft.hideCompletedProgressive }"
            @click="draft.hideCompletedProgressive = !draft.hideCompletedProgressive"
          >
            完了{{ draft.hideCompletedProgressive ? '（非表示）' : '（表示）' }}
          </button>
          <button
            type="button"
            class="hide-toggle"
            :class="{ 'hide-toggle--on': draft.hideKeyReturnProgressive }"
            @click="draft.hideKeyReturnProgressive = !draft.hideKeyReturnProgressive"
          >
            鍵返{{ draft.hideKeyReturnProgressive ? '（非表示）' : '（表示）' }}
          </button>
        </section>

        <section class="settings-section">
          <h4>物件名</h4>
          <input
            v-model="draft.propertyNameQuery"
            type="search"
            class="property-search"
            placeholder="物件名で検索"
          />
        </section>

        <section class="settings-section">
          <div class="settings-section-head">
            <h4>担当</h4>
            <div class="settings-section-actions">
              <button type="button" class="link-btn" @click="selectAllEmployees">すべて選択</button>
              <button type="button" class="link-btn" @click="clearSection('employeeFilterValues')">すべて解除</button>
            </div>
          </div>
          <div class="option-list">
            <label v-for="option in employeeOptions" :key="`emp-${option.value}`" class="option-item">
              <input
                type="checkbox"
                :checked="draft.employeeFilterValues.includes(option.value)"
                @change="toggleEmployee(option.value)"
              />
              <span>{{ option.label }}</span>
            </label>
          </div>
        </section>

        <section class="settings-section settings-section--sort">
          <h4>昇降順</h4>
          <button
            type="button"
            class="sort-direction-btn"
            :class="{ 'sort-direction-btn--desc': !draft.sortAscending }"
            @click="draft.sortAscending = !draft.sortAscending"
          >
            {{ draft.sortAscending ? '昇順' : '降順' }}
          </button>
        </section>

        <section class="settings-section">
          <h4>並び替え</h4>
          <select v-model="draft.sortKey" class="sort-select">
            <option :value="sortKeys.CREATED_AT">作成日順</option>
            <option :value="sortKeys.ORDERED_ON">指示日順</option>
            <option :value="sortKeys.WORK_CODE">指示No順</option>
          </select>
        </section>
      </div>
      <div class="modal-footer">
        <button type="button" class="cancel-btn" @click="handleCancel">キャンセル</button>
        <button type="button" class="apply-btn" @click="handleApply">適用</button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { reactive, watch } from 'vue'
import { SCHEDULE_GRID_SORT_KEYS } from '../utils/scheduleGridFilters.js'

const props = defineProps({
  isOpen: { type: Boolean, default: false },
  filters: { type: Object, required: true },
  mcOptions: { type: Array, default: () => [] },
  registrationYearOptions: { type: Array, default: () => [] },
  instructionYearOptions: { type: Array, default: () => [] },
  jkkStatusOptions: { type: Array, default: () => [] },
  employeeOptions: { type: Array, default: () => [] },
})

const emit = defineEmits(['close', 'apply'])

const sortKeys = SCHEDULE_GRID_SORT_KEYS

const draft = reactive({
  mcIds: [],
  registrationYears: [],
  instructionYears: [],
  jkkStatusIds: [],
  employeeFilterValues: [],
  hideCompletedProgressive: false,
  hideKeyReturnProgressive: false,
  propertyNameQuery: '',
  sortKey: SCHEDULE_GRID_SORT_KEYS.CREATED_AT,
  sortAscending: true,
})

function cloneFilters(source) {
  return {
    mcIds: [...(source.mcIds || [])],
    registrationYears: [...(source.registrationYears || [])],
    instructionYears: [...(source.instructionYears || [])],
    jkkStatusIds: [...(source.jkkStatusIds || [])],
    employeeFilterValues: [...(source.employeeFilterValues || [])],
    hideCompletedProgressive: !!source.hideCompletedProgressive,
    hideKeyReturnProgressive: !!source.hideKeyReturnProgressive,
    propertyNameQuery: source.propertyNameQuery ?? '',
    sortKey: source.sortKey ?? SCHEDULE_GRID_SORT_KEYS.CREATED_AT,
    sortAscending: source.sortAscending !== false,
  }
}

watch(
  () => [props.isOpen, props.filters],
  () => {
    if (!props.isOpen) return
    Object.assign(draft, cloneFilters(props.filters))
  },
  { immediate: true, deep: true },
)

function toggleNumber(key, value) {
  const num = Number(value)
  const list = draft[key]
  const index = list.indexOf(num)
  if (index >= 0) list.splice(index, 1)
  else list.push(num)
}

function toggleEmployee(value) {
  const list = draft.employeeFilterValues
  const index = list.indexOf(value)
  if (index >= 0) list.splice(index, 1)
  else list.push(value)
}

function selectAll(key, options) {
  draft[key] = options.map((option) => Number(option.value)).filter((n) => Number.isInteger(n))
}

function selectAllEmployees() {
  draft.employeeFilterValues = props.employeeOptions.map((option) => option.value)
}

function clearSection(key) {
  draft[key] = []
}

function handleCancel() {
  emit('close')
}

function handleApply() {
  emit('apply', cloneFilters(draft))
  emit('close')
}
</script>

<style scoped>
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  background: rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0;
}

.modal-box {
  width: 100%;
  max-width: 32rem;
  max-height: min(92vh, 720px);
  background: #fff;
  border-radius: 12px 12px 0 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.875rem 1rem;
  border-bottom: 1px solid #e5e7eb;
}

.modal-header h3 {
  margin: 0;
  font-size: 1.0625rem;
  font-weight: 600;
}

.close-btn {
  border: none;
  background: transparent;
  font-size: 1.125rem;
  color: #6b7280;
  cursor: pointer;
}

.modal-body {
  flex: 1;
  overflow-y: auto;
  padding: 0.75rem 1rem 1rem;
}

.settings-section {
  margin-bottom: 1rem;
}

.settings-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.375rem;
}

.settings-section h4 {
  margin: 0;
  font-size: 0.9375rem;
  font-weight: 600;
  color: #374151;
}

.settings-section-actions {
  display: flex;
  gap: 0.5rem;
}

.link-btn {
  border: none;
  background: transparent;
  color: #2563eb;
  font-size: 0.8125rem;
  cursor: pointer;
  padding: 0;
}

.option-list {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  max-height: 9rem;
  overflow-y: auto;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  padding: 0.375rem 0.5rem;
}

.option-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9375rem;
  color: #374151;
}

.settings-section--toggles {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.hide-toggle {
  padding: 0.4375rem 0.75rem;
  border: 1px solid #d1d5db;
  border-radius: 999px;
  background: #fff;
  color: #374151;
  font-size: 0.875rem;
  cursor: pointer;
}

.hide-toggle--on {
  background: #f3f4f6;
  color: #6b7280;
  border-color: #9ca3af;
}

.property-search {
  width: 100%;
  box-sizing: border-box;
  padding: 0.5rem 0.625rem;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 0.9375rem;
}

.settings-section--sort {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.sort-direction-btn {
  padding: 0.4375rem 0.875rem;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  background: #fff;
  font-size: 0.875rem;
  cursor: pointer;
}

.sort-direction-btn--desc {
  background: #eff6ff;
  border-color: #93c5fd;
  color: #1d4ed8;
}

.sort-select {
  width: 100%;
  box-sizing: border-box;
  padding: 0.5rem 0.625rem;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 0.9375rem;
  background: #fff;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-top: 1px solid #e5e7eb;
}

.cancel-btn,
.apply-btn {
  padding: 0.5rem 1rem;
  border-radius: 6px;
  font-size: 0.9375rem;
  cursor: pointer;
}

.cancel-btn {
  border: 1px solid #d1d5db;
  background: #fff;
  color: #374151;
}

.apply-btn {
  border: 1px solid #2563eb;
  background: #2563eb;
  color: #fff;
}
</style>
