<template>
  <div
    class="billing-templates-tab-container"
    @contextmenu="preventContextMenu"
  >
    <BillingTemplateEditor ref="editorRef" />
  </div>
</template>

<script setup>
import { computed, ref } from 'vue'
import BillingTemplateEditor from './BillingTemplateEditor.vue'

const editorRef = ref(null)

function preventContextMenu(event) {
  const target = event.target
  if (!(target instanceof Element)) return
  if (target.closest('input, textarea, select, option, [contenteditable="true"]')) return
  event.preventDefault()
}

function loadTemplates() {
  editorRef.value?.loadTemplates?.()
}

const loading = computed(() => editorRef.value?.loading ?? false)

defineExpose({
  loadTemplates,
  loading
})
</script>

<style scoped>
.billing-templates-tab-container {
  display: flex;
  width: 100%;
  height: 100%;
  background: #f9fafb;
  -webkit-touch-callout: none;
}

.billing-templates-tab-container :where(:not(input):not(textarea):not(select):not(option)) {
  -webkit-user-select: none;
  user-select: none;
}

.billing-templates-tab-container input,
.billing-templates-tab-container textarea,
.billing-templates-tab-container select {
  -webkit-touch-callout: default;
  -webkit-user-select: text;
  user-select: text;
}
</style>
