/**
 * プライスリストの並び・既定選択用: fiscal_year 降順、同年度内は revision_no 降順
 * @param {Record<string, unknown>} a
 * @param {Record<string, unknown>} b
 * @returns {number}
 */
export function comparePriceListsByFiscalThenRevision(a, b) {
  const fyA = Number(a?.fiscal_year)
  const fyB = Number(b?.fiscal_year)
  const nfyA = Number.isFinite(fyA) ? fyA : 0
  const nfyB = Number.isFinite(fyB) ? fyB : 0
  if (nfyB !== nfyA) return nfyB - nfyA
  const revA = Number(a?.revision_no)
  const revB = Number(b?.revision_no)
  const nrevA = Number.isFinite(revA) ? revA : 0
  const nrevB = Number.isFinite(revB) ? revB : 0
  return nrevB - nrevA
}

/**
 * work.ordered_on から優先 fiscal_year を算出する。
 * 7〜12月: その暦年、1〜6月: 前年（例: 2026/5/15→2025、2026/7/15→2026）
 * @param {string|Date|null|undefined} orderedOn
 * @returns {number|null}
 */
export function getPreferredFiscalYearFromOrderedOn(orderedOn) {
  if (orderedOn == null || orderedOn === '') return null

  const d = orderedOn instanceof Date ? orderedOn : new Date(String(orderedOn))
  if (Number.isNaN(d.getTime())) return null

  const year = d.getFullYear()
  const month = d.getMonth() + 1

  if (month >= 7) return year
  if (month >= 1) return year - 1
  return null
}

/**
 * 見積グリッド等の初期選択: 優先 fiscal_year 内で revision 最大、無ければ最新年度
 * @param {Array<Record<string, unknown>>} priceLists
 * @param {string|Date|null|undefined} orderedOn
 * @returns {Record<string, unknown>|null}
 */
export function pickDefaultPriceList(priceLists, orderedOn) {
  if (!Array.isArray(priceLists) || priceLists.length === 0) return null

  const sorted = [...priceLists].sort(comparePriceListsByFiscalThenRevision)
  const targetFy = getPreferredFiscalYearFromOrderedOn(orderedOn)
  if (targetFy == null) return sorted[0]

  const inTargetYear = sorted.filter((pl) => Number(pl.fiscal_year) === targetFy)
  if (inTargetYear.length > 0) return inTargetYear[0]

  return sorted[0]
}
