  }
  if (el.closest('.comparison-item') && !el.closest('.comp-row-bottom')) {
    photoCodeDropDragActive.value = true
  }
}

function parseExclusionDropPayload(raw) {
  let data = null
  try {
    data = JSON.parse(raw)
  } catch {
    return null
  }
  if (!data || typeof data !== 'object') return null
  const type = String(data.type || '')
  const externalCode = String(data.external_code ?? '').trim()
  if (!externalCode) return null
  if (type === 'photo-similar-candidate') {
    return { external_code: externalCode, summary: String(data.description || '').trim() }
  }
  if (type === 'price-item') {
    const desc = String(data.description || '').trim()
    const add = String(data.additional_description || data.note || '').trim()
    return { external_code: externalCode, summary: desc || add }
  }
  if (type === 'comparison-item') {
    return {
      external_code: externalCode,
      summary: String(data.billing_description || data.estimate_instruction || '').trim()
    }
  }
  return null
}

function onExclusionDragOver(ev) {
  if (isMobilePhotoInputsMode.value || !showPhotoCodeDropOverlays.value) return
  ev.dataTransfer.dropEffect = 'copy'
}

async function onExclusionDrop(ev) {
  if (isMobilePhotoInputsMode.value) return
  photoCodeDropDragActive.value = false
  const raw = ev.dataTransfer?.getData('text/plain') || ''
  const payload = parseExclusionDropPayload(raw)
  if (!payload) return

  const { external_code: externalCode, summary: description } = payload
  const summaryLine = description ? `\n（概要: ${description}）` : ''
  const ok = await dialog.confirm(
    `単価コード「${externalCode}」を類似取得の候補から除外しますか？\n\n次回の類似取得から除外されます。${summaryLine}`,
    { title: '確認' }
  )
  if (!ok) return

  try {
    const result = await supabaseService.insertExclusionCode({
      external_code: externalCode,
      summary: description
    })
    if (result?.inserted === false) {
      await dialog.alert(result.message || 'この単価コードは既に除外登録されています')
    }
  } catch (err) {
    await dialog.alert(err?.message || '除外登録に失敗しました', { title: 'エラー' })
  }
}

