}

function parseRoomOrderFromSlotKey(fid) {
  if (fid == null) return null
  const s = String(fid)
  if (!s.startsWith(ROOM_ORDER_PREFIX)) return null
  const n = parseInt(s.slice(ROOM_ORDER_PREFIX.length), 10)
  return Number.isFinite(n) ? n : null
}

