}

/** EstimateGridEditor 等が setData する JSON / 従来のコード文字列の両方に対応 */
function parsePriceItemDragPlainText(raw) {
  const empty = () => ({ code: '', description: '', additional: '', quantity: null })
  const s = String(raw || '').trim()
  if (!s) return empty()
  try {
    const o = JSON.parse(s)
    if (o && typeof o === 'object' && o.type === 'price-item' && o.external_code != null) {
      const add =
        String(o.additional_description || '').trim() ||
        String(o.note || '').trim()
      return {
        code: String(o.external_code).trim(),
        description: String(o.description || ''),
        additional: add,
        quantity: null
      }
    }
    if (o && typeof o === 'object' && o.type === 'comparison-item' && o.external_code != null) {
      const q = o.billing_quantity != null && o.billing_quantity !== '' ? o.billing_quantity : o.quantity
      let quantity = null
      if (q != null && q !== '') {
        const n = Number(q)
        if (Number.isFinite(n)) quantity = n
      }
      return {
        code: String(o.external_code).trim(),
        description: String(o.billing_description || o.estimate_instruction || ''),
        additional: '',
        quantity
      }
    }
    if (o && typeof o === 'object' && o.type === 'photo-similar-candidate' && o.external_code != null) {
      return {
        code: String(o.external_code).trim(),
        description: String(o.description || ''),
        additional: '',
        quantity: 1
      }
    }
  } catch {
    /* 単価コードのみ */
  }
  return { code: s, description: '', additional: '', quantity: null }
}

function splitStoredDescription(stored) {
  const t = String(stored ?? '').trim()
  if (!t) return { main: '', add: '' }
  const ix = t.indexOf(DESC_COMBINE_SEP)
  if (ix >= 0) {
    return {
      main: t.slice(0, ix).trim(),
      add: t.slice(ix + DESC_COMBINE_SEP.length).trim()
    }
  }
  return { main: t, add: '' }
}

/** 類似・履歴候補の概要/備考分割（スマホ2列表示用） */
function similarDescParts(it) {
  return splitStoredDescription(String(it?.description ?? ''))
}

function combineDescForSave(main, additional) {
  const d = String(main ?? '').trim()
  const a = String(additional ?? '').trim()
  if (d && a) return d + DESC_COMBINE_SEP + a
  return d || a
}

const priceByCode = computed(() => {
  const m = new Map()
  for (const it of props.priceListItems || []) {
    const c = String(it.external_code ?? '').trim()
    if (c) m.set(c, it)
  }
  return m
})

const pendingDeleteIdSet = computed(() => new Set(pendingStorageDeleteIds.value.map(String)))

const orderedPhotoList = computed(() => {
  let list = photoList.value.filter((f) => f?.id && !pendingDeleteIdSet.value.has(String(f.id)))
  if (photoListOrderIds.value.length) {
    const ix = new Map(photoListOrderIds.value.map((id, i) => [String(id), i]))
    list = [...list].sort((a, b) => (ix.get(String(a.id)) ?? 999999) - (ix.get(String(b.id)) ?? 999999))
  }
  return list
})

const visiblePhotoList = computed(() => orderedPhotoList.value)

const selectedFile = computed(() => {
