  const targetId = String(selectedFileId.value)
  return visiblePhotoList.value.find((f) => String(f?.id) === targetId) || null
})
const isSupplementSlotSelected = computed(() => isSupplementSlotId(selectedFileId.value))
const selectedHasEmbedding = computed(() => {
  if (!selectedFileId.value || isSupplementSlotId(selectedFileId.value)) return false
  return embeddingFileIds.value.has(String(selectedFileId.value))
})
const isSimilarResultStaleSimilar = computed(() => {
  if (!selectedFileId.value || !similarResultFileId.value) return false
  return String(selectedFileId.value) !== String(similarResultFileId.value)
})
const isSimilarResultStaleHousing = computed(() => {
  if (!selectedFileId.value || !similarResultFileId.value) return false
  return String(selectedFileId.value) !== String(similarResultFileId.value)
})

/** 施工前一覧のうち、DB に特徴ベクトルが未登録の画像数 */
const missingEmbeddingCount = computed(() => {
  const set = embeddingFileIds.value
  return visiblePhotoList.value.filter((f) => f?.id && !set.has(String(f.id))).length
})

const currentDraftRows = computed({
  get() {
    if (!selectedFileId.value) return []
    return draftPhotoWorkLinksByFileId[selectedFileId.value] || []
  },
  set(v) {
    if (selectedFileId.value) draftPhotoWorkLinksByFileId[selectedFileId.value] = v
  }
})
const hasPhotoDirty = computed(() => hasLocalEdits.value || pendingStorageDeleteIds.value.length > 0)
watch(hasPhotoDirty, (v) => emit('dirty-change', v), { immediate: true })

watch(
  () => [
    props.workId,
    missingEmbeddingCount.value,
    featureGenerateLoading.value,
    photoListLoading.value,
    featureGenerateProgress.value.current,
    featureGenerateProgress.value.total
  ],
  () => {
