function hasDbLinks(fid) {
  const rows = existingPhotoWorkLinksByFileId[fid] || []
  return rows.some((r) => !isPhotoUiStateRow(r))
}

function hasEmbedding(fid) {
  return embeddingFileIds.value.has(String(fid))
}

function isPhotoUiStateRow(row) {
  if (!row) return false
  if (String(row.external_code || '').trim() !== '0') return false
  const q = row.quantity
  const qn = q === '' || q == null ? null : Number(q)
  if (qn !== 0 && q !== 0) return false
  try {
    const o = JSON.parse(String(row.content || '{}'))
    return Boolean(o && o._pwPhotoChrome === true)
  } catch {
    return false
  }
}

/** 1行: コード（trim 非空）かつ数量が入っている */
function rowHasCodeAndQuantity(row) {
  if (isPhotoUiStateRow(row)) return false
  if (!String(row?.external_code || '').trim()) return false
  const q = row?.quantity
  if (q === null || q === undefined || q === '') return false
  return true
}

function extractPhotoChromeStateFromLinkRows(rows) {
  const rest = []
  for (const r of rows || []) {
    if (isPhotoUiStateRow(r)) {
      /* UI 状態行は破棄（旧 thumbSort 等は未使用） */
    } else {
      rest.push(r)
    }
  }
  return { rest, state: {} }
}

const visibleSupplementSlotKeys = computed(() => {
  const keys = new Set([NULL_FILE_SLOT_ID])

  const slotHasAnyLinks = (slotKey) => {
    const d = draftPhotoWorkLinksByFileId[slotKey] || []
    const e = existingPhotoWorkLinksByFileId[slotKey] || []
    return d.length > 0 || e.length > 0
  }

  /** ルーム分: 写真タブは sort_order 0～9 のみ。保存済み空白は非表示、それ以外はラベルあり or リンクあり */
  for (const r of roomLabelRecords.value || []) {
    const ord = Number(r?.sort_order)
    if (!Number.isFinite(ord) || !isPhotoTabRoomOrder(ord)) continue
    if (matrixRoomLabelBlocksDrop(ord)) continue
    const kk = roomOrderSlotKey(ord)
    if (!kk) continue
    const lbl = String(r?.label || '').trim()
    if (lbl.length > 0 || slotHasAnyLinks(kk)) {
      keys.add(kk)
    }
  }

  const seenOrds = new Set(
    (roomLabelRecords.value || [])
      .map((x) => Number(x?.sort_order))
      .filter((n) => Number.isFinite(n))
  )
  const extraKeys = new Set([
    ...Object.keys(draftPhotoWorkLinksByFileId),
    ...Object.keys(existingPhotoWorkLinksByFileId)
  ])
  for (const k of extraKeys) {
    if (!String(k).startsWith(ROOM_ORDER_PREFIX)) continue
    const ord = parseRoomOrderFromSlotKey(k)
    if (ord == null || !isPhotoTabRoomOrder(ord) || seenOrds.has(ord)) continue
    if (matrixRoomLabelBlocksDrop(ord)) continue
    if (slotHasAnyLinks(k)) keys.add(String(k))
  }

  const roomKeys = [...keys].filter((x) => x !== NULL_FILE_SLOT_ID)
  roomKeys.sort((a, b) => (parseRoomOrderFromSlotKey(a) || 0) - (parseRoomOrderFromSlotKey(b) || 0))
  return [NULL_FILE_SLOT_ID, ...roomKeys]
})

/** 画像なしサムネ用: プレーンは「補足」、ルーム別はラベル文字のみ */
function supplementCaption(slotKey) {
  if (slotKey === NULL_FILE_SLOT_ID) return '補足'
  const ord = parseRoomOrderFromSlotKey(slotKey)
  if (ord == null) return '補足'
  const hit = (roomLabelRecords.value || []).find((r) => Number(r.sort_order) === ord)
  const lbl = hit ? String(hit.label || '').trim() : ''
  return lbl || `label${ord}`
}

/** 1行: コードあり、数量未入力 */
function rowHasCodeMissingQuantity(row) {
  if (!String(row?.external_code || '').trim()) return false
  const q = row?.quantity
  return q === null || q === undefined || q === ''
}

/** サムネ青枠: 当該ファイルの下書きにコード+数量の行が1行でもある */
function fileHasCodeAndQtyRows(fid) {
  const rows = draftPhotoWorkLinksByFileId[fid]
  if (!rows?.length) return false
  return rows.some((r) => rowHasCodeAndQuantity(r))
}

/** コード+数量の登録が下書き・DB いずれにもない（項目未登録） */
function isPhotoItemUnregistered(fid) {
  if (!fid) return false
  return !fileHasCodeAndQtyRows(fid) && !hasDbLinks(fid)
}

/**
 * 写真タブの部屋ドロップダウン用ラベル一覧を更新する。
 * loadAll（IndexedDB 優先 → Supabase）、見積の部屋テンプレートモーダル保存から呼ぶ。
 */
function setRoomLabelMenuOptions(labels, options = {}) {
  if (!Array.isArray(labels)) {
    roomLabelOptions.value = []
    roomLabelRecords.value = []
    roomLabelsPersisted.value = false
    return
  }
  const sorted = [...labels].sort(
    (a, b) => (Number(a?.sort_order) || 0) - (Number(b?.sort_order) || 0)
  )
  roomLabelRecords.value = sorted.map((r) => ({
    id: r?.id ?? null,
    sort_order: Number(r?.sort_order) || 0,
    label: String(r?.label ?? '')
  }))
  roomLabelOptions.value = roomLabelPwMenuTexts(sorted)
  if (options.persisted !== undefined) {
    roomLabelsPersisted.value = Boolean(options.persisted)
  } else {
    roomLabelsPersisted.value = roomLabelRecords.value.some((r) => r.id != null)
  }
}

function matrixRoomLabelBlocksDrop(roomOrder) {
  return isRoomLabelSavedButBlank(roomOrder, roomLabelRecords.value, {
    persisted: roomLabelsPersisted.value,
  })
}

function isSupplementSlotSavedBlank(slotKey) {
  const ord = parseRoomOrderFromSlotKey(slotKey)
  if (ord == null || slotKey === NULL_FILE_SLOT_ID) return false
  return matrixRoomLabelBlocksDrop(ord)
}

function isSupplementSlotSelectable(slotKey) {
  if (!isSupplementSlotId(slotKey)) return true
  if (slotKey === NULL_FILE_SLOT_ID) return true
  return !isSupplementSlotSavedBlank(slotKey)
}

function resolveDefaultSelectedFileId(preferredId = null) {
  const preferred = preferredId != null ? String(preferredId) : ''
  if (preferred && isSupplementSlotSelectable(preferred)) return preferred
  if (preferred && !isSupplementSlotId(preferred)) {
    const photoHit = visiblePhotoList.value.find((f) => String(f.id) === preferred)
    if (photoHit) return photoHit.id
  }
  for (const sk of visibleSupplementSlotKeys.value) {
    if (isSupplementSlotSelectable(sk)) return sk
  }
  return visiblePhotoList.value[0]?.id ?? (props.workId ? NULL_FILE_SLOT_ID : null)
}

function displayPlDescription(row) {
  const code = String(row.external_code || '').trim()
  const pl = priceByCode.value.get(code)
  if (pl) return pl.description || ''
  return splitStoredDescription(row.description).main
}

function displayPlAdditionalDescription(row) {
  const code = String(row.external_code || '').trim()
  const pl = priceByCode.value.get(code)
  if (pl) return pl.additional_description || pl.note || ''
  return splitStoredDescription(row.description).add
}

function displayUnit(row) {
  const code = String(row.external_code || '').trim()
  const pl = priceByCode.value.get(code)
  if (pl) return pl.unit || ''
  return ''
}

function emptyLinkRow() {
  return {
    external_code: '',
    quantity: null,
    is_quantity: false,
    description: '',
    content: '',
    contractor_id: null,
    _k: Math.random().toString(36).slice(2)
  }
}

/** 未入力に近い行（末尾の余白行削減用） */
function isLinkRowBlank(row) {
  if (!row) return true
  if (String(row.external_code || '').trim()) return false
  if (row.quantity != null && String(row.quantity).trim() !== '') return false
  if (String(row.content || '').trim()) return false
  if (row.contractor_id) return false
  if (String(row.description || '').trim()) return false
  if (row.is_quantity) return false
  return true
}

/** サムネ拡大サマリー用: 何かしら入力がある行 */
function isLinkRowFilled(row) {
  if (isPhotoUiStateRow(row)) return false
  return !isLinkRowBlank(row)
}

function instructionContractorLabelForRow(row) {
  return resolveInstructionContractorLabel(row, props.contractors)
}

function formatThumbsExpandTemplateContent(template, content) {
  const t = String(template || '').trim()
  const c = String(content || '').trim()
  if (t && c) return `${t}-${c}`
  if (t) return t
  if (c) return c
  return '—'
}

/** 最低 linkGridMinRows() まで空行を足す。DB 行は切り詰めない（保存漏れ防止） */
function normalizeLinkGridRows(fid) {
  if (!fid) return
  if (!draftPhotoWorkLinksByFileId[fid]) {
    draftPhotoWorkLinksByFileId[fid] = cloneLinks(existingPhotoWorkLinksByFileId[fid])
  }
  const arr = draftPhotoWorkLinksByFileId[fid]
  const minRows = linkGridMinRows()
  if (!arr.length) {
    arr.push(emptyLinkRow())
  }
  while (arr.length < minRows) {
    arr.push(emptyLinkRow())
  }
  /* スマホ写真: 最小行数より多い末尾の空行だけ落とす（一覧→写真で最小行の下駄が残るのを防ぐ）
   * ただし「全体で空行が1つだけ」のときは末尾を残す（行削除後に入力用の1行を確保） */
  if (props.mobileLayout === 'photo') {
    while (arr.length > minRows && isLinkRowBlank(arr[arr.length - 1])) {
      const totalBlanks = arr.reduce((n, r) => n + (isLinkRowBlank(r) ? 1 : 0), 0)
      if (totalBlanks <= 1) break
      arr.pop()
    }
  }
}

/** 最終行にコード+数量が入ったら、編集用の空行を1行追加（上限まで） */
function ensureTrailingLinkRowAfterComplete(fid) {
  if (!fid) return
  const arr = draftPhotoWorkLinksByFileId[fid]
  if (!arr?.length) return
  const last = arr[arr.length - 1]
  if (!rowHasCodeAndQuantity(last)) return
  if (arr.length >= LINK_GRID_MAX_ROWS) return
  arr.push(emptyLinkRow())
}

function selectFile(fid) {
  if (isSupplementSlotId(fid) && !isSupplementSlotSelectable(fid)) return
  selectedFileId.value = fid
  previewImgTapArmedFileId.value = null
  closeRoomMenu()
  normalizeLinkGridRows(fid)
  ensureTrailingLinkRowAfterComplete(fid)
  ensureThumbVisible(fid)
}

/** サムネ列クリック。一覧タブのときは選択後に詳細タブへ誘導 */
function onThumbsStripClick(fid) {
  if (isSupplementSlotId(fid) && !isSupplementSlotSelectable(fid)) return
  selectFile(fid)
  if (props.mobileLayout === 'list') {
    emit('request-mobile-photo-tab')
  }
}

function onThumbsExpandMoveClick(rowIndex = null) {
  if (!showPreviewColumnSummary.value) return
  const fid = selectedFileId.value
  const parsedIdx = Number(rowIndex)
  const targetRowIdx =
    Number.isFinite(parsedIdx) && parsedIdx >= 0
      ? parsedIdx
      : thumbsExpandFilledRowEntries.value[0]?.idx ?? 0
  if (isMobileDetailMode.value) {
    emit('request-mobile-input-tab')
    nextTick(() => {
      if (currentDraftRows.value.length > 0) {
        scrollPhotoGridRowIntoView(targetRowIdx)
      }
    })
    return
  }
  collapseThumbsExpandMode()
  nextTick(() => {
    ensureThumbVisible(fid)
    if (currentDraftRows.value.length > 0) {
      scrollPhotoGridRowIntoView(targetRowIdx)
    }
  })
}

function onThumbsExpandMoveDblClick(ev, rowIndex = null) {
  ev?.preventDefault?.()
  ev?.stopPropagation?.()
  clearSimilarCandTextSelection()
  onThumbsExpandMoveClick(rowIndex)
}

function isPhotoLinkSummaryMovePayload(raw) {
  try {
    const o = JSON.parse(String(raw || ''))
    return o?.type === 'photo-link-summary-move'
  } catch {
    return false
  }
}

function getDropPlainText(ev) {
  const plain = String(ev?.dataTransfer?.getData('text/plain') || '').trim()
  if (plain) return plain
  const uriList = String(ev?.dataTransfer?.getData('text/uri-list') || '').trim()
  if (!uriList) return ''
  return uriList.split('\n').map((line) => line.trim()).find(Boolean) || ''
}

function isThumbnailOrUrlDropPayload(raw) {
  const s = String(raw || '').trim()
  if (!s) return false
  if (/^https?:\/\//i.test(s)) return true
  if (/^data:image\//i.test(s)) return true
  return false
}

function shouldHandlePhotoCodeDrop(ev) {
  if (!photoCodeDropDragActive.value) return false
  const raw = getDropPlainText(ev)
  if (!raw || isPhotoLinkSummaryMovePayload(raw)) return false
  return !isThumbnailOrUrlDropPayload(raw)
}

function onThumbsExpandCodeDropDragOver(ev) {
  if (isMobilePhotoInputsMode.value || !showThumbsExpandInputSummary.value) return
  if (thumbsExpandSummaryDragActive.value) {
    ev.dataTransfer.dropEffect = 'none'
    return
  }
  if (!showPhotoCodeDropOverlays.value) return
  ev.dataTransfer.dropEffect = 'copy'
}

function onThumbsExpandCodeDrop(ev) {
  if (isMobilePhotoInputsMode.value || !showThumbsExpandInputSummary.value) return
  const raw = getDropPlainText(ev)
  if (thumbsExpandSummaryDragActive.value || isPhotoLinkSummaryMovePayload(raw)) {
    onThumbsExpandSummaryLineDragEnd()
    return
  }
  if (!shouldHandlePhotoCodeDrop(ev)) return
  photoCodeDropDragActive.value = false
  onDropOnRow(ev, 0)
}

function onPreviewColumnThumbsExpandDragOver(ev) {
  if (!showThumbsExpandInputSummary.value || isMobilePhotoInputsMode.value) return
  if (thumbsExpandSummaryDragActive.value) {
    ev.dataTransfer.dropEffect = 'none'
    return
  }
  if (showPhotoCodeDropOverlays.value) {
    ev.dataTransfer.dropEffect = 'copy'
  }
}

function onPreviewColumnThumbsExpandDrop(ev) {
  if (!showThumbsExpandInputSummary.value || isMobilePhotoInputsMode.value) return
  const raw = getDropPlainText(ev)
  if (thumbsExpandSummaryDragActive.value || isPhotoLinkSummaryMovePayload(raw)) {
    onThumbsExpandSummaryLineDragEnd()
    return
  }
  if (!shouldHandlePhotoCodeDrop(ev)) return
  photoCodeDropDragActive.value = false
  onDropOnRow(ev, 0)
}

function onThumbsExpandSummaryLineDragStart(ev, rowIndex) {
  if (!showThumbsExpandInputSummary.value || isMobilePhotoInputsMode.value) return
  const fid = selectedFileId.value
  if (!fid) return
  ev.stopPropagation()
  thumbsExpandSummaryDragActive.value = true
  thumbsExpandSummaryDragSourceFileId.value = String(fid)
  ev.dataTransfer.effectAllowed = 'move'
  ev.dataTransfer.setData(
    'text/plain',
    JSON.stringify({ type: 'photo-link-summary-move', sourceFileId: String(fid), rowIndex })
  )
  document.body.style.cursor = 'grabbing'
}

function onThumbsExpandSummaryLineDragEnd() {
  thumbsExpandSummaryDragActive.value = false
  thumbsExpandSummaryDragSourceFileId.value = null
  thumbsExpandSummaryDropHoverFileId.value = null
  document.body.style.cursor = ''
}

function onThumbDragOver(ev, fid) {
  if (isMobilePhotoInputsMode.value) return
  if (isSupplementSlotId(fid) && !isSupplementSlotSelectable(fid)) return
  const fidStr = String(fid)

  if (thumbsExpandSummaryDragActive.value && showThumbsExpandInputSummary.value) {
    if (thumbsExpandSummaryDragSourceFileId.value === fidStr) {
      ev.dataTransfer.dropEffect = 'none'
      return
    }
    ev.preventDefault()
    ev.stopPropagation()
    ev.dataTransfer.dropEffect = 'move'
    thumbsExpandSummaryDropHoverFileId.value = fidStr
    return
  }

  if (showPhotoCodeDropOverlays.value) {
    ev.preventDefault()
    ev.stopPropagation()
    ev.dataTransfer.dropEffect = 'copy'
    thumbCodeDropHoverFileId.value = fidStr
  }
}

function onThumbDragLeave(ev, fid) {
  const fidStr = String(fid)
  const related = ev.relatedTarget
  const rowEl = ev.currentTarget
  if (related && rowEl?.contains(related)) return

  if (thumbsExpandSummaryDropHoverFileId.value === fidStr) {
    thumbsExpandSummaryDropHoverFileId.value = null
  }
  if (thumbCodeDropHoverFileId.value === fidStr) {
    thumbCodeDropHoverFileId.value = null
  }
}

function onThumbDrop(ev, fid) {
  if (isMobilePhotoInputsMode.value) return
  if (isSupplementSlotId(fid) && !isSupplementSlotSelectable(fid)) return
  ev.preventDefault()
  ev.stopPropagation()
  const targetFileId = String(fid)

  if (thumbsExpandSummaryDragActive.value && showThumbsExpandInputSummary.value) {
    thumbsExpandSummaryDragActive.value = false
    thumbsExpandSummaryDragSourceFileId.value = null
    thumbsExpandSummaryDropHoverFileId.value = null
    document.body.style.cursor = ''
    const raw = ev.dataTransfer?.getData('text/plain') || ''
    try {
      const parsed = JSON.parse(raw)
      if (parsed?.type !== 'photo-link-summary-move') return
      const sourceFileId = String(parsed.sourceFileId || '')
      const rowIndex = Number(parsed.rowIndex)
      if (!sourceFileId || !Number.isFinite(rowIndex)) return
      if (sourceFileId === targetFileId) return
      moveLinkRowToPhoto(sourceFileId, rowIndex, targetFileId)
    } catch {
      /* ignore */
    }
    return
  }

  if (shouldHandlePhotoCodeDrop(ev)) {
    photoCodeDropDragActive.value = false
    thumbCodeDropHoverFileId.value = null
    onDropOnRow(ev, 0, targetFileId)
  }
}

function moveLinkRowToPhoto(sourceFileId, rowIndex, targetFileId) {
  if (!sourceFileId || !targetFileId || sourceFileId === targetFileId) return false
  normalizeLinkGridRows(sourceFileId)
  normalizeLinkGridRows(targetFileId)
  const sourceRows = draftPhotoWorkLinksByFileId[sourceFileId]
  const targetRows = draftPhotoWorkLinksByFileId[targetFileId]
  if (!sourceRows || rowIndex < 0 || rowIndex >= sourceRows.length) return false
  const row = sourceRows[rowIndex]
  if (!isLinkRowFilled(row)) return false
  const code = String(row.external_code || '').trim()
  if (code) {
    const dupIx = findBlockingDuplicateCodeRowIndex(targetRows, code)
    if (dupIx >= 0) {
      flashInputRow(targetFileId, dupIx, 'red')
      return false
    }
  }
  markPhotoDirty({ captureUndo: true })
  const movedRow = cloneLinks([row])[0]
  let targetIx
  const emptyIx = targetRows.findIndex(
    (r) => !String(r.external_code || '').trim() && isLinkRowBlank(r)
  )
  if (emptyIx >= 0) {
    targetIx = emptyIx
    targetRows[targetIx] = movedRow
  } else if (targetRows.length < LINK_GRID_MAX_ROWS) {
    targetRows.push(movedRow)
    targetIx = targetRows.length - 1
  } else {
    targetIx = targetRows.length - 1
    targetRows[targetIx] = movedRow
  }
  sourceRows[rowIndex] = emptyLinkRow()
  ensureTrailingLinkRowAfterComplete(sourceFileId)
  ensureTrailingLinkRowAfterComplete(targetFileId)
  emit('draft-change')
  selectFile(targetFileId)
  return true
}

function collapseThumbsExpandMode() {
  if (props.thumbsExpandActive && isThumbsExpandFeatureEnabled.value) {
    emit('update:thumbsExpandActive', false)
  }
}

/** 写真入力グリッド: 行の下にこの程度の余白が見えるようスクロール（PCは .pw-grid-rows-scroll、スマホは .pw-grid-area 等） */
const PHOTO_GRID_SCROLL_BOTTOM_GUTTER_PX = 140
const PHOTO_GRID_SCROLL_TOP_GUTTER_PX = 36

function findPhotoGridScrollParent(rowEl) {
  const stop = photoGridAreaRef.value
  if (!stop || !rowEl) return null
  let n = rowEl.parentElement
  while (n && n !== stop) {
    const st = window.getComputedStyle(n)
    const oy = st.overflowY
    if (
      (oy === 'auto' || oy === 'scroll' || oy === 'overlay') &&
      n.scrollHeight > n.clientHeight + 2
    ) {
      return n
    }
    n = n.parentElement
  }
  if (stop.scrollHeight > stop.clientHeight + 2) return stop
  return stop
}

/**
 * 指定行が表示領域の下端付近に張り付かないようスクロールする。
 * 原本→反映・指示▶移動・類似/同一団地のダブルタップ等で共通利用。
 */
function scrollPhotoGridRowIntoView(rowIx, options = {}) {
  const bottomGutter = Number(options.bottomGutterPx ?? PHOTO_GRID_SCROLL_BOTTOM_GUTTER_PX)
  const topGutter = Number(options.topGutterPx ?? PHOTO_GRID_SCROLL_TOP_GUTTER_PX)
  const run = () => {
    const root = photoGridAreaRef.value
    if (!root || rowIx < 0) return
    const rows = root.querySelectorAll('.pw-grid-row')
    const el = rows[rowIx]
    if (!el || typeof el.getBoundingClientRect !== 'function') return

    const scrollParent = findPhotoGridScrollParent(el)
    if (!scrollParent) {
      if (typeof el.scrollIntoView === 'function') {
        el.scrollIntoView({ block: 'center', inline: 'nearest' })
      }
      return
    }

    const pr = scrollParent.getBoundingClientRect()
    const er = el.getBoundingClientRect()
    const desiredRowBottom = pr.bottom - bottomGutter
    let delta = 0
    if (er.bottom > desiredRowBottom) {
      delta = er.bottom - desiredRowBottom
    } else if (er.top < pr.top + topGutter) {
      delta = -((pr.top + topGutter) - er.top)
    }
    if (delta !== 0) {
      scrollParent.scrollTop += delta
    }
  }
  nextTick(() => {
    requestAnimationFrame(run)
  })
}

function flashInputRow(fid, rowIx, type = 'orange') {
  const keyFid = String(fid || '')
  const ix = Number(rowIx)
  if (!keyFid || !Number.isFinite(ix) || ix < 0) return
  const key = `${keyFid}:${ix}`
  inputFlashRowKey.value = key
  inputFlashRowType.value = type === 'blue' || type === 'red' ? type : 'orange'
  if (inputFlashTimer) clearTimeout(inputFlashTimer)
  inputFlashTimer = setTimeout(() => {
    if (inputFlashRowKey.value === key) {
      inputFlashRowKey.value = ''
      inputFlashRowType.value = 'orange'
    }
    inputFlashTimer = null
  }, 1200)
}

function isCurrentInputFlashRow(rowIx) {
  const fid = String(selectedFileId.value || '')
  if (!fid) return false
  return inputFlashRowKey.value === `${fid}:${Number(rowIx)}`
}

function isCurrentInputFlashRowBlue(rowIx) {
  return isCurrentInputFlashRow(rowIx) && inputFlashRowType.value === 'blue'
}

function isCurrentInputFlashRowRed(rowIx) {
  return isCurrentInputFlashRow(rowIx) && inputFlashRowType.value === 'red'
}

/**
 * 写真タブのグリッドを走査して、external_code 一致する画像を選択する
 *（比較タブのダブルクリック時用）
 */
function selectPhotoByExternalCode(externalCode, options = {}) {
  const code = String(externalCode ?? '').trim()
  if (!code) return false
  const candidates = []
  for (const f of visiblePhotoList.value) {
    const fid = String(f.id)
    const rows = draftPhotoWorkLinksByFileId[fid] || existingPhotoWorkLinksByFileId[fid] || []
    for (let i = 0; i < rows.length; i++) {
      if (isPhotoUiStateRow(rows[i])) continue
      if (String(rows[i]?.external_code ?? '').trim() === code) {
        candidates.push({ fileId: fid, rowIndex: i })
      }
    }
  }
  for (const sk of visibleSupplementSlotKeys.value) {
    const rows = draftPhotoWorkLinksByFileId[sk] || existingPhotoWorkLinksByFileId[sk] || []
    for (let i = 0; i < rows.length; i++) {
      if (isPhotoUiStateRow(rows[i])) continue
      if (String(rows[i]?.external_code ?? '').trim() === code) {
        candidates.push({ fileId: sk, rowIndex: i })
      }
    }
  }
  if (!candidates.length) return false

  const startAfter = options?.startAfter
  const startFileId = String(startAfter?.fileId ?? '')
  const startRowIndex = Number(startAfter?.rowIndex)
  let pick = candidates[0]
  if (startFileId && Number.isFinite(startRowIndex)) {
    const currentIx = candidates.findIndex((c) => c.fileId === startFileId && c.rowIndex === startRowIndex)
    if (currentIx >= 0) {
      pick = candidates[(currentIx + 1) % candidates.length]
    }
  }

  selectFile(pick.fileId)
  scrollPhotoGridRowIntoView(pick.rowIndex)
  flashInputRow(pick.fileId, pick.rowIndex, 'blue')
  return pick
}

/** 指示タブなどから: 指定画像のリンク行（0-based）へ移動（フォーカスは移動しない） */
function selectPhotoLinkAtRow(fileId, rowIndex) {
  const fid = fileId != null ? String(fileId) : ''
  if (!fid) return false
  const ix = Number(rowIndex)
  if (!Number.isFinite(ix) || ix < 0) return false
  selectFile(fid)
  scrollPhotoGridRowIntoView(ix)
  flashInputRow(fid, ix, 'blue')
  return true
}

function snapshotDraftStateForUndo() {
  const draftByFileId = {}
  for (const fid of Object.keys(draftPhotoWorkLinksByFileId)) {
    draftByFileId[fid] = cloneLinks(draftPhotoWorkLinksByFileId[fid])
  }
  return {
    selectedFileId: selectedFileId.value != null ? String(selectedFileId.value) : null,
    mobilePhotoViewMode: mobilePhotoViewMode.value,
    draftByFileId
  }
}

function pushPhotoUndoSnapshot() {
  if (suppressPhotoUndoCapture.value) return
  photoUndoHistory.value.push(snapshotDraftStateForUndo())
  if (photoUndoHistory.value.length > PHOTO_UNDO_MAX) {
    photoUndoHistory.value.shift()
  }
}

function pushPhotoUndoSnapshotValue(snapshot) {
  if (suppressPhotoUndoCapture.value || !snapshot) return
  photoUndoHistory.value.push(snapshot)
  if (photoUndoHistory.value.length > PHOTO_UNDO_MAX) {
    photoUndoHistory.value.shift()
  }
}

function canUndoLastAction() {
  return photoUndoHistory.value.length > 0
}

function undoLastAction() {
  if (!photoUndoHistory.value.length) return false
  const snap = photoUndoHistory.value.pop()
  if (!snap) return false
  suppressPhotoUndoCapture.value = true
  try {
    Object.keys(draftPhotoWorkLinksByFileId).forEach((k) => delete draftPhotoWorkLinksByFileId[k])
    for (const [fid, rows] of Object.entries(snap.draftByFileId || {})) {
      draftPhotoWorkLinksByFileId[fid] = cloneLinks(rows)
    }
    selectedFileId.value = snap.selectedFileId ?? selectedFileId.value
    if (props.mobileLayout === 'photo') {
      mobilePhotoViewMode.value = snap.mobilePhotoViewMode || 'input'
    }
    hasLocalEdits.value = true
    emit('draft-change')
  } finally {
    suppressPhotoUndoCapture.value = false
  }
  return true
}

function markPhotoDirty({ captureUndo = false } = {}) {
  if (captureUndo) pushPhotoUndoSnapshot()
  if (!suppressDraftDirtyWatch.value) hasLocalEdits.value = true
  emit('draft-change')
  nextTick(() => {
    if (selectedFileId.value) ensureTrailingLinkRowAfterComplete(selectedFileId.value)
  })
}

function fieldEditKey(row, field) {
  return `${String(row?._k || '')}:${String(field || '')}`
}

function startFieldEdit(row, field) {
  fieldEditStartMap.value.set(fieldEditKey(row, field), {
    value: row?.[field] ?? null,
    snapshot: snapshotDraftStateForUndo()
  })
}

function commitFieldEditIfChanged(row, field) {
  const key = fieldEditKey(row, field)
  if (!fieldEditStartMap.value.has(key)) return
  const entry = fieldEditStartMap.value.get(key)
  const before = entry?.value ?? null
  const beforeSnapshot = entry?.snapshot ?? null
  const after = row?.[field] ?? null
  fieldEditStartMap.value.delete(key)
  if (before !== after) {
    pushPhotoUndoSnapshotValue(beforeSnapshot)
    markPhotoDirty()
  }
}

function ensureThumbVisible(fid) {
  if (!fid) return
  nextTick(() => {
    const container = thumbListRef.value
    if (!container) return
    const target = container.querySelector(`.pw-thumb-wrap[data-file-id="${String(fid)}"]`)
    if (!target || typeof target.getBoundingClientRect !== 'function') return
    const cRect = container.getBoundingClientRect()
    const tRect = target.getBoundingClientRect()
    if (props.thumbsExpandActive && isThumbsExpandFeatureEnabled.value) {
      const fullyVisible =
        tRect.top >= cRect.top &&
        tRect.bottom <= cRect.bottom &&
        tRect.left >= cRect.left &&
        tRect.right <= cRect.right
      if (fullyVisible) return
      target.scrollIntoView({ block: 'nearest', inline: 'nearest' })
      return
    }
    if (tRect.top >= cRect.top && tRect.bottom <= cRect.bottom) return
    target.scrollIntoView({ block: 'nearest', inline: 'nearest' })
  })
}

