function triggerBeforeUpload() {
  if (!props.workId || !beforeFolderId.value || beforeUploadBusy.value) return
  if (!beforeUploadInputRef.value) return
  beforeUploadInputRef.value.value = ''
  beforeUploadInputRef.value.click()
}

function onCreateBeforeFolderClick() {
  if (!props.workId || beforeFolderId.value || beforeFolderCreating.value || beforeUploadBusy.value) return
  void (async () => {
    const ok = await dialog.confirm('施工前のフォルダを作成しますか？', {
      title: '確認',
      confirmText: 'はい',
      cancelText: 'いいえ'
    })
    if (ok) await createBeforeFolder()
  })()
}

async function createBeforeFolder() {
  if (!props.workId || beforeFolderId.value || beforeFolderCreating.value) return
  beforeFolderCreating.value = true
  panelError.value = ''
  try {
    const res = await supabaseService.manageCloudStorage({
      action: 'create_folder',
      scope: 'work',
      work_id: props.workId,
      parent_id: null,
      name: '施工前'
    })
    const folderId = res?.folder?.id
    if (folderId) {
      await supabaseService.manageCloudStorage({
        action: 'commit',
        scope: 'work',
        work_id: props.workId,
        ids: [folderId]
      })
    }
    if (!folderId) {
      throw new Error('フォルダIDを取得できませんでした')
    }
    beforeFolderId.value = String(folderId)
    await loadAll({ preserveSelectedFileId: selectedFileId.value })
  } catch (e) {
    panelError.value = e?.message || '施工前フォルダの作成に失敗しました'
  } finally {
    beforeFolderCreating.value = false
  }
}

async function onBeforeUploadInputChange(ev) {
  const files = Array.from(ev?.target?.files || []).filter((f) => f?.type?.startsWith('image/') || isHeicLikeFile(f))
  if (!files.length || !props.workId || !beforeFolderId.value || beforeUploadBusy.value) return
  const preserveThumbScrollTop = thumbListRef.value?.scrollTop ?? null
  const preserveSelectedFileId = selectedFileId.value
  beforeUploadBusy.value = true
  beforeUploadProgress.value = { phase: 'preparing', current: 0, total: files.length }
  panelError.value = ''
  try {
    const batchItems = []
    for (let i = 0; i < files.length; i++) {
      const file = files[i]
      const p = await processImageForUpload(file)
      batchItems.push({
        processedFile: p.mainImage,
        originalFileName: resolveCameraPlaceholderUploadName(file.name, { outputExt: 'jpg' }),
        thumbnail: p.thumbnail,
        sthumb: p.sthumb,
        width: p.width ?? null,
        height: p.height ?? null,
        rotation: p.rotation ?? 0,
        exifDateTime: p.exifDateTime ?? null,
        isStandardAspectRatio: p.isStandardAspectRatio ?? false
      })
      beforeUploadProgress.value = { phase: 'preparing', current: i + 1, total: files.length }
    }
    beforeUploadProgress.value = { phase: 'uploading', current: 0, total: files.length }
    const uploaded = await supabaseService.uploadBatchFiles(props.workId, batchItems, {
      work_category_id: beforeFolderId.value
    }, ({ current, total }) => {
      beforeUploadProgress.value = {
        phase: 'uploading',
        current: Number(current) || 0,
        total: Number(total) || files.length
      }
    })
    const uploadedIds = Array.isArray(uploaded) ? uploaded.map((u) => u?.id).filter(Boolean) : []
    if (uploadedIds.length !== files.length) {
      throw new Error(`アップロード完了件数が一致しません (${uploadedIds.length}/${files.length})`)
    }
    if (uploadedIds.length) {
      // 全件成功後に一括コミット
      beforeUploadProgress.value = { phase: 'committing', current: uploadedIds.length, total: files.length }
      await supabaseService.commitUploadedFiles(props.workId, uploadedIds)
      // このアップロード経路ではモバイルでも特徴値生成を実行
      try {
        const work = await indexedDBService.getWorkById(props.workId)
        const localThumbByFileId = new Map()
        for (const row of uploaded || []) {
          const b = row?.embed_thumbnail_blob
          if (row?.id && b instanceof Blob && b.size > 0) {
            localThumbByFileId.set(row.id, b)
          }
        }
        beforeUploadProgress.value = { phase: 'embedding', current: 0, total: uploadedIds.length }
        await supabaseService.runBatchPhotoEmbeddingsAfterCommit(props.workId, uploadedIds, {
          work_kind: work?.kind ?? null,
          forceRun: true,
          housing_detail_id: work?.housing_detail_id ?? null,
          localThumbByFileId,
          onProgress: ({ current, total }) => {
            beforeUploadProgress.value = {
              phase: 'embedding',
              current: Number(current) || 0,
              total: Number(total) || uploadedIds.length
            }
          }
        })
      } catch (embedErr) {
        console.warn('[PhotoWorkLinksPanel] batch photo embeddings after upload', embedErr)
      }
    }
    const firstUploadedId = uploadedIds.length ? String(uploadedIds[0]) : preserveSelectedFileId
    await loadAll({
      preserveSelectedFileId: firstUploadedId,
      preserveThumbScrollTop
    })
  } catch (e) {
    panelError.value = e?.message || '施工前画像のアップロードに失敗しました'
  } finally {
    beforeUploadBusy.value = false
    beforeUploadProgress.value = { phase: 'idle', current: 0, total: 0 }
    if (beforeUploadInputRef.value) beforeUploadInputRef.value.value = ''
  }
}

/** 半角・全角数字と半角・全角ドットのみ残し全角を半角へ。小数点は先頭の1つのみ */
function normalizeQtyOnBlur(raw) {
  let s = ''
  for (const ch of String(raw ?? '')) {
    const c = ch.charCodeAt(0)
    if (c >= 0x30 && c <= 0x39) {
      s += ch
      continue
    }
    if (c >= 0xff10 && c <= 0xff19) {
      s += String.fromCharCode(c - 0xff10 + 0x30)
      continue
    }
    if (ch === '.') {
      s += '.'
      continue
    }
    if (c === 0xff0e) {
      s += '.'
      continue
    }
  }
  let out = ''
  let seenDot = false
  for (let i = 0; i < s.length; i++) {
    const ch = s[i]
    if (ch === '.') {
      if (!seenDot) {
        out += '.'
        seenDot = true
      }
    } else {
      out += ch
    }
  }
  return out
}

/** x オン時の表示用「x 」を剥がして数値部分だけ取り出す（半角 x / 全角 x どちらも） */
function stripLeadingXQtyPrefix(raw) {
  return String(raw ?? '')
    .replace(/^\s*[x×Ｘｘ]\s*/, '')
    .trim()
}

function qtyFieldDisplay(row) {
  const q = row.quantity
  if (q == null || q === '') return ''
  const s = String(q)
  // 写真タブ: x オンでも数値のみ表示（指示タブでは x 付き）
  return s
}

function onQtyInput(row, e) {
  const v = e.target?.value
  const stripped = stripLeadingXQtyPrefix(v)
  row.quantity = stripped === '' || stripped == null ? null : stripped
}

function onQtyFocusToEnd(e) {
  const el = e?.target
  if (!el || typeof el.setSelectionRange !== 'function') return
  const len = String(el.value ?? '').length
  requestAnimationFrame(() => {
    try {
      el.setSelectionRange(len, len)
    } catch {
      /* no-op */
    }
  })
}

function onQtyBlur(row, e) {
  const beforeSnapshot = snapshotDraftStateForUndo()
  const before = row.quantity
  const normalized = normalizeQtyOnBlur(stripLeadingXQtyPrefix(e.target?.value ?? ''))
  if (normalized === '' || normalized === '.') {
    const next = null
    row.quantity = next
    if (before !== next) {
      pushPhotoUndoSnapshotValue(beforeSnapshot)
      markPhotoDirty()
    }
    return
  }
  const n = parseFloat(normalized)
  const next = Number.isFinite(n) ? n : null
  row.quantity = next
  if (before !== next) {
    pushPhotoUndoSnapshotValue(beforeSnapshot)
    markPhotoDirty()
  }
}

function incQty(row) {
  markPhotoDirty({ captureUndo: true })
  const q = row.quantity == null || row.quantity === '' ? 0 : Number(row.quantity)
  row.quantity = Number.isFinite(q) ? q + 1 : 1
}

function decQty(row) {
  markPhotoDirty({ captureUndo: true })
  const q = row.quantity == null || row.quantity === '' ? 0 : Number(row.quantity)
  const n = Number.isFinite(q) ? q - 1 : 0
  row.quantity = n <= 0 ? null : n
}

let qtyClearLongPressTimer = null
let qtyClearLongPressTriggered = false
let qtyClearLongPressAt = 0
const QTY_CLEAR_LONG_PRESS_MS = 500

function startQtyClearLongPress(row) {
  cancelQtyClearLongPress()
  qtyClearLongPressTriggered = false
  qtyClearLongPressTimer = setTimeout(() => {
    qtyClearLongPressTriggered = true
    qtyClearLongPressAt = Date.now()
    markPhotoDirty({ captureUndo: true })
    row.quantity = null
  }, QTY_CLEAR_LONG_PRESS_MS)
}

function cancelQtyClearLongPress() {
  if (qtyClearLongPressTimer) {
    clearTimeout(qtyClearLongPressTimer)
    qtyClearLongPressTimer = null
  }
}

function handleQtyPlusClick(row) {
