function getDraftRowByFileAndIndex(fileId, rowIndex) {
  const fid = String(fileId ?? '')
  const ix = Number(rowIndex)
  if (!fid || !Number.isInteger(ix) || ix < 0) return { fid: '', row: null }
  normalizeLinkGridRows(fid)
  const rows = draftPhotoWorkLinksByFileId[fid]
  return { fid, row: rows?.[ix] || null }
}

function markSpecificPhotoRowDirty(fid) {
  if (!suppressDraftDirtyWatch.value) hasLocalEdits.value = true
  emit('draft-change')
  nextTick(() => {
    if (fid) ensureTrailingLinkRowAfterComplete(fid)
  })
}

function updatePhotoLinkRowField(payload) {
  const field = String(payload?.field || '')
  if (field !== 'content' && field !== 'quantity' && field !== 'contractor_id') return false
  const { fid, row } = getDraftRowByFileAndIndex(payload?.fileId, payload?.rowIndex)
  if (!row || isPhotoUiStateRow(row)) return false

  let nextValue
  if (field === 'content') {
    nextValue = String(payload?.value ?? '')
  } else if (field === 'contractor_id') {
    const v = String(payload?.value ?? '').trim()
    nextValue = v || null
  } else {
    const normalized = normalizeQtyOnBlur(stripLeadingXQtyPrefix(payload?.value ?? ''))
    if (normalized === '' || normalized === '.') {
      nextValue = null
    } else {
      const n = parseFloat(normalized)
      nextValue = Number.isFinite(n) ? n : null
    }
  }

  const before = row[field] ?? null
  if (before === nextValue) return false
  pushPhotoUndoSnapshot()
  row[field] = nextValue
  markSpecificPhotoRowDirty(fid)
  return true
}

function togglePhotoLinkRowQuantityFlag(payload) {
  const { fid, row } = getDraftRowByFileAndIndex(payload?.fileId, payload?.rowIndex)
  if (!row || isPhotoUiStateRow(row)) return false
  pushPhotoUndoSnapshot()
  row.is_quantity = !row.is_quantity
  markSpecificPhotoRowDirty(fid)
  return true
}

function incrementPhotoLinkRowQuantity(payload) {
  const { fid, row } = getDraftRowByFileAndIndex(payload?.fileId, payload?.rowIndex)
  if (!row || isPhotoUiStateRow(row)) return false
  pushPhotoUndoSnapshot()
  const q = row.quantity == null || row.quantity === '' ? 0 : Number(row.quantity)
  row.quantity = Number.isFinite(q) ? q + 1 : 1
  markSpecificPhotoRowDirty(fid)
  return true
}

function clearPhotoLinkRowQuantity(payload) {
  const { fid, row } = getDraftRowByFileAndIndex(payload?.fileId, payload?.rowIndex)
  if (!row || isPhotoUiStateRow(row)) return false
  if (row.quantity == null || row.quantity === '') return false
  pushPhotoUndoSnapshot()
  row.quantity = null
  markSpecificPhotoRowDirty(fid)
  return true
}

/** ✕: 行を削除し、最低行数を満たしたうえで空行が無ければ1行追加 */
function removeLinkRow(row) {
  const fid = selectedFileId.value
  if (!fid || !row) return
  if (isPhotoUiStateRow(row)) return
  markPhotoDirty({ captureUndo: true })
  normalizeLinkGridRows(fid)
  const arr = draftPhotoWorkLinksByFileId[fid]
  const ix = arr.indexOf(row)
  if (ix < 0) return
  arr.splice(ix, 1)
  if (roomMenuRowIndex.value === ix) closeRoomMenu()
  else if (roomMenuRowIndex.value != null && roomMenuRowIndex.value > ix) {
    roomMenuRowIndex.value -= 1
  }
  normalizeLinkGridRows(fid)
  const arr2 = draftPhotoWorkLinksByFileId[fid]
  if (!arr2.some(isLinkRowBlank) && arr2.length < LINK_GRID_MAX_ROWS) {
    arr2.push(emptyLinkRow())
  }
  ensureTrailingLinkRowAfterComplete(fid)
  emit('draft-change')
  flashGridAreaAfterRowDelete()
}

/** 行削除後に .pw-grid-area 全体を赤く発光（CSS アニメ 1 周） */
function flashGridAreaAfterRowDelete() {
  if (gridDeleteFlashTimer) clearTimeout(gridDeleteFlashTimer)
  gridDeleteFlashActive.value = false
  requestAnimationFrame(() => {
    gridDeleteFlashActive.value = true
    gridDeleteFlashTimer = setTimeout(() => {
      gridDeleteFlashActive.value = false
      gridDeleteFlashTimer = null
    }, 1300)
  })
}

function collectUsedTemporaryCodes() {
  const used = new Set()
  for (const rows of Object.values(draftPhotoWorkLinksByFileId)) {
    for (const row of rows || []) {
      const code = String(row?.external_code || '').trim()
      if (!/^\d+$/.test(code)) continue
      const n = Number(code)
      if (Number.isInteger(n) && n >= TEMP_CODE_MIN && n <= TEMP_CODE_MAX) used.add(n)
    }
  }
  return used
}

function getNextTemporaryCode() {
  const used = collectUsedTemporaryCodes()
  for (let n = TEMP_CODE_MIN; n <= TEMP_CODE_MAX; n++) {
    if (!used.has(n)) return String(n)
  }
  return null
}

function assignTemporaryCode(row) {
  const nextCode = getNextTemporaryCode()
  if (!nextCode) {
    void dialog.alert('仮コードは 1〜99 を使い切っています', { title: 'エラー' })
    return
  }
  markPhotoDirty({ captureUndo: true })
  row.external_code = nextCode
  if (row.quantity == null || String(row.quantity).trim() === '') {
    row.quantity = 1
  }
  row.is_quantity = false
}

function rowHasContractorSelected(row) {
  const id = row?.contractor_id
  return id != null && String(id).trim() !== ''
}

/** コードあり・依頼先未選択の行（依頼先セレクトを強調） */
function rowNeedsContractorHighlight(row) {
  if (!row || isPhotoUiStateRow(row)) return false
  if (!String(row.external_code || '').trim()) return false
  return !rowHasContractorSelected(row)
}

function originalContractorIdForCode(code) {
  const nk = normalizeExternalCode(code)
  if (!nk || !props.originalContractorByNormCode) return null
  const raw =
    props.originalContractorByNormCode instanceof Map
      ? props.originalContractorByNormCode.get(nk)
      : props.originalContractorByNormCode[nk]
  if (raw == null || raw === '') return null
  const s = String(raw).trim()
  return s || null
}

function isSpecialInstructionContractor(contractorId) {
  if (contractorId == null || String(contractorId).trim() === '') return false
  const hit = (props.contractors || []).find((c) => String(c.id) === String(contractorId))
  return Boolean(hit?.is_special)
}

function contractorLabelById(contractorId) {
  if (contractorId == null || String(contractorId).trim() === '') return '（未設定）'
  const hit = (props.contractors || []).find((c) => String(c.id) === String(contractorId))
  return String(hit?.label || hit?.description || contractorId).trim() || String(contractorId)
}

function findColKeyForContractor(map, contractorId) {
  if (!map?.columns || contractorId == null) return null
  for (const key of SPECIAL_COLUMN_KEYS) {
    if (String(map.columns[key]) === String(contractorId)) return key
  }
  return null
}

function isOriginalContractorMutedForCode(code) {
  const cid = originalContractorIdForCode(code)
  if (!cid) return false
  return !isSpecialInstructionContractor(cid)
}

async function resolveOriginalDropContractorPlacement(code, targetColKey, targetContractorId) {
  const origCid = originalContractorIdForCode(code)
  if (!origCid || isSpecialInstructionContractor(origCid)) {
    return { colKey: targetColKey, contractorId: targetContractorId }
  }

  const result = await dialog.confirm(
    '表示先を選んでください',
    {
      title: '依頼先が入力済みです',
      choiceOptions: [
        {
          value: 'original',
          label: `「${contractorLabelById(origCid)}」`,
          labelPrimary: true,
          note: '※入力が行われますが\n　現在の入力欄では表示されません',
        },
        {
          value: 'target',
          label: `「${contractorLabelById(targetContractorId)}」`,
        },
      ],
      defaultChoice: 'original',
      confirmText: '決定',
      cancelText: 'キャンセル',
    }
  )
  if (!result || result === false) return null

  const choice = result?.choice || 'original'
  if (choice !== 'original') {
    return { colKey: targetColKey, contractorId: targetContractorId }
  }

  const map = getSpecialContractorColumnMap()
  const origColKey = findColKeyForContractor(map, origCid)
  if (origColKey) {
    return { colKey: origColKey, contractorId: origCid }
  }
  return { colKey: targetColKey, contractorId: origCid }
}

/**
 * 同一コードの重複挿入を拒否すべき既存行か。
 * 依頼先空、または（原本と同じ依頼先かつ特殊指示依頼先でない）のとき拒否。
 */
function rowShouldBlockDuplicateCode(row, code) {
  if (!rowHasContractorSelected(row)) return true
  const origCid = originalContractorIdForCode(code)
  if (!origCid) return false
  const rowCid = String(row.contractor_id).trim()
  if (rowCid !== String(origCid).trim()) return false
  return !isSpecialInstructionContractor(rowCid)
}

function findBlockingDuplicateCodeRowIndex(rows, code, excludeIndex = -1) {
  const c = String(code || '').trim()
  if (!c) return -1
  for (let i = 0; i < (rows || []).length; i++) {
    if (i === excludeIndex) continue
    const row = rows[i]
    if (isPhotoUiStateRow(row)) continue
    if (String(row?.external_code || '').trim() !== c) continue
    if (rowShouldBlockDuplicateCode(row, c)) return i
  }
  return -1
}

/** 原本グリッドに同一コードがあれば依頼先セレクトをセット */
function applyContractorFromOriginalGrid(row, code) {
  if (!row) return
  const c = String(code || '').trim()
  if (!c) return
  const nk = normalizeExternalCode(c)
  if (!nk || !props.originalContractorByNormCode) return
  const raw =
    props.originalContractorByNormCode instanceof Map
      ? props.originalContractorByNormCode.get(nk)
      : props.originalContractorByNormCode[nk]
  if (raw == null || raw === '') return
  const cid = String(raw).trim()
  if (!cid) return
  row.contractor_id = cid
}

