function applyComparisonCandidateToTop(item, flashKey, fid = selectedFileId.value) {
  const code = String(item?.external_code || '').trim()
  if (!code || !fid) return
  markPhotoDirty({ captureUndo: true })
  normalizeLinkGridRows(fid)
  const rows = draftPhotoWorkLinksByFileId[fid]
  const rowIdx = rows.findIndex((r) => {
    const rowCode = String(r?.external_code || '').trim()
    const q = r?.quantity
    const qtyText = q == null ? '' : String(q).trim()
    return rowCode === '' && qtyText === ''
  })
  const targetRowIdx = rowIdx >= 0 ? rowIdx : 0
  const dupIx = findBlockingDuplicateCodeRowIndex(rows, code, targetRowIdx)
  if (dupIx >= 0) {
    flashInputRow(fid, dupIx, 'red')
    scrollPhotoGridRowIntoView(dupIx)
    return
  }
  const pl = priceByCode.value.get(code)
  const row = rows[targetRowIdx]
  if (!row) return
  row.external_code = code
  row.description = pl
    ? combineDescForSave(pl.description || '', pl.additional_description || pl.note || '')
    : getComparisonDescription(item)
  row.quantity = 1
  row.is_quantity = false
  row.content = ''
  applyContractorFromOriginalGrid(row, code)
  touchSimilarityHistoryAndRefresh(code, String(row?.description || ''))
  similarFlashKey.value = flashKey
  if (similarFlashTimer) clearTimeout(similarFlashTimer)
  similarFlashTimer = setTimeout(() => {
    similarFlashKey.value = null
    similarFlashTimer = null
  }, 900)
  flashInputRow(fid, targetRowIdx)
  if (fid !== selectedFileId.value) {
    selectFile(fid)
  }
  nextTick(() => {
    if (fid) ensureTrailingLinkRowAfterComplete(fid)
    nextTick(() => scrollPhotoGridRowIntoView(targetRowIdx))
  })
}

