async function onPreviewDeleteClick() {
  const f = selectedFile.value
  if (!f?.id || !props.workId || photoSaving.value) return
  const ok = await dialog.confirm(
    'この画像を削除しますか？\n保存時にストレージからも削除されます。',
    { title: '確認' }
  )
  if (!ok) return
  const deleteId = String(f.id)
  const list = visiblePhotoList.value
  const ix = list.findIndex((x) => String(x.id) === deleteId)
  const nextPick = list[ix + 1]?.id ?? list[ix - 1]?.id ?? null
  if (!pendingStorageDeleteIds.value.includes(deleteId)) {
    pendingStorageDeleteIds.value = [...pendingStorageDeleteIds.value, deleteId]
  }
  delete draftPhotoWorkLinksByFileId[deleteId]
  delete existingPhotoWorkLinksByFileId[deleteId]
  const nextEmb = new Set(embeddingFileIds.value)
  nextEmb.delete(deleteId)
  embeddingFileIds.value = nextEmb
  selectedFileId.value = nextPick
  if (nextPick) normalizeLinkGridRows(nextPick)
  ensureThumbVisible(nextPick)
}

/** 指示書反映用: 施工前画像の下書き・DB を file_id ごとにまとめる（削除予定は除外） */
/** 特殊指示依頼先の Excel 出力用（room_label_order 付きスロットのみ） */
function buildSpecialContractorExportEntries() {
  const entries = []
  const counterByGroup = new Map()
  for (const sk of visibleSupplementSlotKeys.value) {
    if (sk === NULL_FILE_SLOT_ID) continue
    const ord = parseRoomOrderFromSlotKey(sk)
    if (ord == null || isSupplementRoomLabelOrder(ord)) continue
    const rows = sortRoomBucketLinksForSave(
      (draftPhotoWorkLinksByFileId[sk] || []).filter((r) => !isPhotoUiStateRow(r)),
      getSpecialContractorColumnMap()
    )
    for (const row of rows) {
      const cid = row.contractor_id
      if (cid == null || String(cid).trim() === '') continue
      const contractor = (props.contractors || []).find((c) => String(c.id) === String(cid))
      if (!contractor?.is_special) continue
      const code = String(row.external_code || '').trim()
      if (!code) continue
      const qty = row.quantity
      if (qty === null || qty === undefined || qty === '') continue
      const descKey = String(contractor.description || '').trim()
      if (!descKey) continue
      const groupKey = `${cid}\u0000${ord}`
      const idx = (counterByGroup.get(groupKey) || 0) + 1
      counterByGroup.set(groupKey, idx)
      let content = String(row.content || '').trim()
      entries.push({
        payloadKey: `${descKey}${ord}-${idx}`,
        external_code: code,
        contractor_id: String(cid),
        room_label_order: ord,
        content,
        quantity: qty,
        is_quantity: Boolean(row.is_quantity),
        is_highlight: Boolean(contractor.is_highlight),
        contractor
      })
    }
  }
  return entries
}

function buildPhotoWorkLinksByFileIdForApply() {
  const pending = pendingDeleteIdSet.value
  const ids = new Set()
  for (const f of photoList.value) {
    if (f?.id && !pending.has(String(f.id))) ids.add(String(f.id))
  }
  for (const k of Object.keys(draftPhotoWorkLinksByFileId)) {
    if (!pending.has(String(k))) ids.add(String(k))
  }
  for (const k of visibleSupplementSlotKeys.value) {
    if (!pending.has(String(k))) ids.add(String(k))
  }
  const out = {}
  for (const id of ids) {
    const rows = draftPhotoWorkLinksByFileId[id] || existingPhotoWorkLinksByFileId[id]
    if (rows && rows.length) out[id] = rows
  }
  return out
}

async function loadAll(options = {}) {
  const { preserveSelectedFileId = null, preserveThumbScrollTop = null } = options
  panelError.value = ''
  if (!props.workId) {
    photoList.value = []
    beforeFolderId.value = ''
    pendingStorageDeleteIds.value = []
    photoUndoHistory.value = []
    hasLocalEdits.value = false
    setRoomLabelMenuOptions([])
    return
  }
  photoListLoading.value = true
  suppressDraftDirtyWatch.value = true
  let loadSucceeded = false
  try {
    const { folders, files } = await supabaseService.getWorkFileFolderList(props.workId)
    const sekkou = (folders || []).find((fo) => String(fo.name || '').trim() === '施工前')
    beforeFolderId.value = sekkou?.id ? String(sekkou.id) : ''
    if (!sekkou) {
      photoList.value = []
    } else {
      const sid = sekkou.id
      photoList.value = (files || []).filter((f) => f.work_category_id === sid || f.folder_id === sid).filter(isImageFile)
    }
    photoListOrderIds.value = photoList.value.map((f) => String(f.id))
    const availableFileIds = new Set(photoList.value.map((f) => String(f.id)))

    const bundleRes = await supabaseService.getPhotoEmbeddingsWithVectorsByWork(props.workId)
    const idList =
      (Array.isArray(bundleRes?.embedded_file_ids) && bundleRes.embedded_file_ids.length > 0
        ? bundleRes.embedded_file_ids
        : (bundleRes?.embeddings || []).map((r) => r?.file_id).filter(Boolean)) || []
    embeddingFileIds.value = new Set(idList.map((x) => String(x)).filter((id) => availableFileIds.has(id)))
    try {
      const w = await indexedDBService.getWorkById(props.workId)
      currentWorkHousingId.value =
        w?.housing_detail_id != null && w.housing_detail_id !== ''
          ? String(w.housing_detail_id)
          : null
    } catch {
      currentWorkHousingId.value = null
    }
    try {
      const cachedRoomLabels = await indexedDBService.getRoomLabels(props.workId)
      setRoomLabelMenuOptions(Array.isArray(cachedRoomLabels) ? cachedRoomLabels : [])
    } catch {
      setRoomLabelMenuOptions([])
    }

    const rawByF = bundleRes?.links_by_file_id || {}
    const byF = {}
    for (const [fid, rows] of Object.entries(rawByF)) {
      if (fid === NULL_FILE_SLOT_ID || String(fid).startsWith(ROOM_ORDER_PREFIX)) {
        byF[fid] = rows
      } else if (availableFileIds.has(String(fid))) {
        byF[fid] = rows
      }
    }
    const plainRaw = Array.isArray(rawByF[NULL_FILE_SLOT_ID]) ? rawByF[NULL_FILE_SLOT_ID] : []
    const { rest: plainRest } = extractPhotoChromeStateFromLinkRows(plainRaw)
    const nullSlotRows = plainRest
    Object.keys(existingPhotoWorkLinksByFileId).forEach((k) => delete existingPhotoWorkLinksByFileId[k])
    Object.keys(draftPhotoWorkLinksByFileId).forEach((k) => delete draftPhotoWorkLinksByFileId[k])
    for (const fid of Object.keys(byF)) {
      if (fid === NULL_FILE_SLOT_ID) continue
      existingPhotoWorkLinksByFileId[fid] = byF[fid]
      draftPhotoWorkLinksByFileId[fid] = cloneLinks(byF[fid])
    }
    existingPhotoWorkLinksByFileId[NULL_FILE_SLOT_ID] = nullSlotRows
    draftPhotoWorkLinksByFileId[NULL_FILE_SLOT_ID] = cloneLinks(nullSlotRows)
    similarByColumn.history = await indexedDBService.listPhotoSimilarityHistory()
    similarByColumn.similarImage = []
    similarByColumn.sameHousing = []
    photoUndoHistory.value = []
    similarResultFileId.value = null
    const prevSelected = preserveSelectedFileId != null ? String(preserveSelectedFileId) : null
    selectedFileId.value = resolveDefaultSelectedFileId(prevSelected)
    for (const fid of Object.keys(draftPhotoWorkLinksByFileId)) {
      normalizeLinkGridRows(fid)
      ensureTrailingLinkRowAfterComplete(fid)
    }
    if (selectedFileId.value) {
      normalizeLinkGridRows(selectedFileId.value)
      ensureTrailingLinkRowAfterComplete(selectedFileId.value)
    }
    await nextTick()
    if (thumbListRef.value && Number.isFinite(preserveThumbScrollTop)) {
      thumbListRef.value.scrollTop = preserveThumbScrollTop
    }
    ensureThumbVisible(selectedFileId.value)
    loadSucceeded = true
  } catch (e) {
    console.error(e)
    panelError.value = e?.message || '読み込みに失敗しました'
  } finally {
    // 再読込成功時は下書きが DB と一致するのでダーティを落とす（見積タブ離脱の破棄・更新ボタン等）
    if (loadSucceeded) {
      hasLocalEdits.value = false
      pendingStorageDeleteIds.value = []
    }
    suppressDraftDirtyWatch.value = false
    photoListLoading.value = false
  }
}

