/** プライスリスト・比較のダブルクリック / ドロップから呼ぶ（履歴更新＋行ハイライト） */
function applyExternalCodeFromPricelist(code, description, _unit, options = {}) {
  const { markDirty = true } = options || {}
  if (markDirty) markPhotoDirty({ captureUndo: true })
  const c = String(code || '').trim()
  if (!c || !selectedFileId.value) return
  normalizeLinkGridRows(selectedFileId.value)
  const rows = draftPhotoWorkLinksByFileId[selectedFileId.value]
  const dupIx = findBlockingDuplicateCodeRowIndex(rows, c)
  if (dupIx >= 0) {
    flashInputRow(selectedFileId.value, dupIx, 'red')
    scrollPhotoGridRowIntoView(dupIx)
    return
  }
  const emptyIx = rows.findIndex((r) => !String(r.external_code || '').trim())
  const pl = priceByCode.value.get(c)
  const sp = splitStoredDescription(description || '')
  const combined = pl
    ? combineDescForSave(pl.description || '', pl.additional_description || pl.note || '')
    : combineDescForSave(sp.main, sp.add)
  let appliedIx
  if (emptyIx >= 0) {
    appliedIx = emptyIx
    rows[emptyIx].external_code = c
    rows[emptyIx].description = combined || description || ''
    rows[emptyIx].quantity = 1
    rows[emptyIx].is_quantity = false
    rows[emptyIx].content = ''
  } else if (rows.length < LINK_GRID_MAX_ROWS) {
    rows.push(emptyLinkRow())
    appliedIx = rows.length - 1
    rows[appliedIx].external_code = c
    rows[appliedIx].description = combined || description || ''
    rows[appliedIx].quantity = 1
    rows[appliedIx].is_quantity = false
    rows[appliedIx].content = ''
  } else {
    appliedIx = rows.length - 1
    rows[appliedIx].external_code = c
    rows[appliedIx].description = combined || description || ''
    rows[appliedIx].quantity = 1
    rows[appliedIx].is_quantity = false
    rows[appliedIx].content = ''
  }
  applyContractorFromOriginalGrid(rows[appliedIx], c)
  touchSimilarityHistoryAndRefresh(c, rows[appliedIx]?.description || combined || description || '')
  flashInputRow(selectedFileId.value, appliedIx)
  nextTick(() => {
    if (selectedFileId.value) ensureTrailingLinkRowAfterComplete(selectedFileId.value)
    nextTick(() => scrollPhotoGridRowIntoView(appliedIx))
  })
}

