function getPhotoLinkGridScrollEl() {
  const root = photoGridAreaRef.value
  if (!root) return null
  return root.querySelector('.pw-grid-rows-scroll--desktop') || root.querySelector('.pw-grid-rows-scroll')
}

function stopLinkRowReorderAutoScroll() {
  if (linkRowReorderAutoScrollTimer) {
    clearInterval(linkRowReorderAutoScrollTimer)
    linkRowReorderAutoScrollTimer = null
  }
  linkRowReorderAutoScrollDir = null
}

function startLinkRowReorderAutoScroll(direction) {
  const scrollEl = getPhotoLinkGridScrollEl()
  if (!scrollEl) return
  linkRowReorderAutoScrollDir = direction
  if (linkRowReorderAutoScrollTimer) return
  linkRowReorderAutoScrollTimer = setInterval(() => {
    const el = getPhotoLinkGridScrollEl()
    if (!el) return
    if (linkRowReorderAutoScrollDir === 'up') {
      el.scrollTop -= LINK_ROW_REORDER_SCROLL_SPEED_PX
    } else if (linkRowReorderAutoScrollDir === 'down') {
      el.scrollTop += LINK_ROW_REORDER_SCROLL_SPEED_PX
    }
  }, 16)
}

function updateLinkRowReorderAutoScroll(clientY) {
  const scrollEl = getPhotoLinkGridScrollEl()
  if (!scrollEl) {
    stopLinkRowReorderAutoScroll()
    return
  }
  const rect = scrollEl.getBoundingClientRect()
  if (clientY < rect.top || clientY > rect.bottom) {
    stopLinkRowReorderAutoScroll()
    return
  }
  if (clientY < rect.top + LINK_ROW_REORDER_SCROLL_ZONE_PX) {
    startLinkRowReorderAutoScroll('up')
  } else if (clientY > rect.bottom - LINK_ROW_REORDER_SCROLL_ZONE_PX) {
    startLinkRowReorderAutoScroll('down')
  } else {
    stopLinkRowReorderAutoScroll()
  }
}

function resetLinkRowReorderDragState() {
  linkRowReorderDragActive.value = false
  linkRowReorderSourceIdx.value = null
  linkRowReorderHoverIdx.value = null
  linkRowReorderInsertAbove.value = true
  stopLinkRowReorderAutoScroll()
  document.body.style.cursor = ''
}

function onPhotoGridRowsScrollDragOver(ev) {
  if (!linkRowReorderDragActive.value) return
  ev.preventDefault()
  updateLinkRowReorderAutoScroll(ev.clientY)
}

function onLinkRowUnitDragStart(ev, idx) {
  if (isMobilePhotoInputsMode.value) return
  ev.stopPropagation()
  linkRowReorderDragActive.value = true
  linkRowReorderSourceIdx.value = idx
  linkRowReorderHoverIdx.value = idx
  linkRowReorderInsertAbove.value = true
