  ev.dataTransfer.setData(
    'text/plain',
    JSON.stringify({ type: 'photo-link-row-reorder', sourceIndex: idx })
  )
  document.body.style.cursor = 'grabbing'
}

function onLinkRowReorderDragEnd() {
  resetLinkRowReorderDragState()
}

function onRowDragLeave(ev, idx) {
  if (!linkRowReorderDragActive.value) return
  const related = ev.relatedTarget
  const rowEl = ev.currentTarget
  if (related && rowEl?.contains(related)) return
  if (linkRowReorderHoverIdx.value === idx) {
    linkRowReorderHoverIdx.value = null
  }
}

function handleLinkRowReorderDrop(sourceIdx, targetIdx) {
  const fid = selectedFileId.value
  if (!fid || sourceIdx == null || targetIdx == null) return
  if (sourceIdx === targetIdx) return

  normalizeLinkGridRows(fid)
  const rows = draftPhotoWorkLinksByFileId[fid]
  if (!rows?.length) return
  if (sourceIdx < 0 || targetIdx < 0 || sourceIdx >= rows.length || targetIdx >= rows.length) return

  markPhotoDirty({ captureUndo: true })
  const [moved] = rows.splice(sourceIdx, 1)
  rows.splice(targetIdx, 0, moved)

  if (roomMenuRowIndex.value != null) {
    const menuIdx = roomMenuRowIndex.value
    if (menuIdx === sourceIdx) {
      roomMenuRowIndex.value = targetIdx
    } else if (sourceIdx < menuIdx && targetIdx >= menuIdx) {
      roomMenuRowIndex.value = menuIdx - 1
    } else if (sourceIdx > menuIdx && targetIdx <= menuIdx) {
      roomMenuRowIndex.value = menuIdx + 1
    }
  }

  emit('draft-change')
}

function onRowDragOver(ev, rowIdx) {
  if (isMobilePhotoInputsMode.value) return
  ev.preventDefault()

  if (linkRowReorderDragActive.value) {
    const sourceIdx = linkRowReorderSourceIdx.value
    if (sourceIdx != null && rowIdx != null && sourceIdx !== rowIdx) {
      linkRowReorderHoverIdx.value = rowIdx
      linkRowReorderInsertAbove.value = sourceIdx > rowIdx
    }
    updateLinkRowReorderAutoScroll(ev.clientY)
    ev.dataTransfer.dropEffect = 'move'
    return
  }

  ev.dataTransfer.dropEffect = 'copy'
}

function onDropOnRow(ev, _rowIdx, targetFileIdOverride = null) {
  if (isMobilePhotoInputsMode.value) return
  ev.preventDefault()
  resetLinkRowReorderDragState()
  const targetFid = targetFileIdOverride || selectedFileId.value
  const raw = getDropPlainText(ev)
  if (isThumbnailOrUrlDropPayload(raw)) return
  try {
    const parsedReorder = JSON.parse(raw)
    if (parsedReorder?.type === 'photo-link-row-reorder') {
      const sourceIdx = Number(parsedReorder.sourceIndex)
      if (Number.isFinite(sourceIdx)) {
        handleLinkRowReorderDrop(sourceIdx, _rowIdx)
      }
      return
    }
    if (parsedReorder?.type === 'photo-link-summary-move') {
      return
    }
  } catch {
    /* プレーンコード等は従来処理へ */
  }
  /** プライスリスト・比較・類似候補のいずれかからのドロップなら履歴に残す */
  let recordHistoryForDrop = false
  let dragSourceType = ''
  let tabletComparisonDropItem = null
  let tabletComparisonDropFlashKey = ''
  try {
    const o = JSON.parse(raw)
    const t = o?.type
    dragSourceType = String(t || '')
    if (t === 'photo-similar-candidate' || t === 'price-item' || t === 'comparison-item') {
      recordHistoryForDrop = true
    }
    if (t === 'comparison-item' && o?.source === 'tablet-comparison-panel') {
      tabletComparisonDropItem = {
        external_code: o.external_code,
        billing_quantity: o.billing_quantity,
        billing_description: o.billing_description || '',
        estimate_instruction: o.estimate_instruction || '',
        unit: o.unit || ''
      }
      tabletComparisonDropFlashKey = String(o.flash_key || '')
    }
  } catch {
    /* プレーンコードのみのドロップは履歴対象外 */
  }
  if (tabletComparisonDropItem) {
    applyComparisonCandidateToTop(tabletComparisonDropItem, tabletComparisonDropFlashKey, targetFid)
    return
  }
  markPhotoDirty({ captureUndo: true })
  const parsed = parsePriceItemDragPlainText(raw)
  const { code, description: fromDrag, additional: fromAdd } = parsed
  let qty = parsed.quantity
  // 比較タブからのドロップは数量を固定で 1 にする
  if (dragSourceType === 'comparison-item') {
    qty = 1
  } else if (qty == null || qty === '') {
    qty = 1
  } else if (typeof qty !== 'number') {
    const n = Number(qty)
    qty = Number.isFinite(n) ? n : 1
  }
  if (!code || !targetFid) return
  normalizeLinkGridRows(targetFid)
  const rows = draftPhotoWorkLinksByFileId[targetFid]
  const dupIx = findBlockingDuplicateCodeRowIndex(rows, code)
  if (dupIx >= 0) {
    flashInputRow(targetFid, dupIx, 'red')
    scrollPhotoGridRowIntoView(dupIx)
    return
  }
  const pl = priceByCode.value.get(code)
  const emptyIx = rows.findIndex((r) => !String(r.external_code || '').trim())
  let appliedIx
  if (emptyIx >= 0) {
    appliedIx = emptyIx
  } else if (rows.length < LINK_GRID_MAX_ROWS) {
    rows.push(emptyLinkRow())
    appliedIx = rows.length - 1
  } else {
    appliedIx = rows.length - 1
  }
  const row = rows[appliedIx]
  if (!row) return
  row.external_code = code
  row.description = pl
    ? combineDescForSave(pl.description || '', pl.additional_description || pl.note || '')
    : combineDescForSave(fromDrag, fromAdd) || row.description || ''
  row.quantity = qty
  row.is_quantity = false
  row.content = ''
  applyContractorFromOriginalGrid(rows[appliedIx], code)
  if (recordHistoryForDrop) {
    touchSimilarityHistoryAndRefresh(code, String(rows[appliedIx]?.description || fromDrag || ''))
  }
  flashInputRow(targetFid, appliedIx)
  if (targetFileIdOverride && targetFid !== selectedFileId.value) {
    selectFile(targetFid)
  }
  nextTick(() => {
    if (targetFid) ensureTrailingLinkRowAfterComplete(targetFid)
    nextTick(() => scrollPhotoGridRowIntoView(appliedIx))
  })
}

