function normalizeSimilarRow(r) {
  return {
    file_id: String(r?.file_id || ''),
    work_id: String(r?.work_id || ''),
    similarity: Number(r?.similarity ?? 0),
    dist: Number(r?.dist ?? 1),
    housing_detail_id: r?.housing_detail_id != null ? String(r.housing_detail_id) : null,
    updated_at: r?.updated_at != null ? String(r.updated_at) : null,
    external_code: String(r?.external_code || '').trim(),
    description: String(r?.description || '')
  }
}

function isExcludedSimilarCode(code) {
  const c = String(code ?? '').trim()
  if (!/^\d+$/.test(c)) return false
  const n = Number(c)
  return Number.isInteger(n) && ((n >= 0 && n <= 1000) || n >= 90000000)
}

/**
 * 類似度順に、ユニークコードが 20 個そろうまでのレコード範囲だけで code_duplicate_count を数える。
 * （API 全体ではなく「20 種類が出揃うまでの先頭区間」内の出現回数）
 */
function makeTop20DedupByCode(rows) {
  const src = (rows || [])
    .map(normalizeSimilarRow)
    .filter((r) => r.external_code && !isExcludedSimilarCode(r.external_code))
  src.sort((a, b) => b.similarity - a.similarity)
  const distinctInPrefix = new Set()
  const prefixRows = []
  for (const r of src) {
    prefixRows.push(r)
    distinctInPrefix.add(r.external_code)
    if (distinctInPrefix.size >= 20) break
  }
  const codeCount = new Map()
  for (const r of prefixRows) {
    codeCount.set(r.external_code, (codeCount.get(r.external_code) || 0) + 1)
  }
  const seen = new Set()
  const out = []
  for (const r of src) {
    if (seen.has(r.external_code)) continue
    seen.add(r.external_code)
    out.push({
      ...r,
      code_duplicate_count: codeCount.get(r.external_code) || 1
    })
    if (out.length >= 20) break
  }
  return out
}

