/** 特徴ベクトル未登録の画像のみサムネから生成し一括 upsert */
async function handleGenerateMissingFeatures() {
  if (!props.workId || featureGenerateLoading.value || photoListLoading.value) return
  const targets = visiblePhotoList.value.filter((f) => f?.id && !embeddingFileIds.value.has(String(f.id)))
  if (targets.length === 0) return
  const ok = await dialog.confirm(`特徴値が未登録の画像 ${targets.length} 件のみ生成して登録します。続行しますか？`, { title: '確認' })
  if (!ok) return

  featureGenerateLoading.value = true
  featureGenerateProgress.value = { current: 0, total: targets.length }
  try {
    const { extractPhotoEmbeddingFloat32, getPhotoEmbeddingModelVersion } = await import('../utils/photoEmbedding.js')
    const modelVersion = getPhotoEmbeddingModelVersion()
    let housingDetailId = null
    try {
      const w = await indexedDBService.getWorkById(props.workId)
      if (w?.housing_detail_id != null && w.housing_detail_id !== '') {
        housingDetailId = w.housing_detail_id
      }
    } catch {
      /* Edge 側で補完可 */
    }

    const items = []
    const failed = []
    for (const file of targets) {
      featureGenerateProgress.value.current += 1
      try {
        const src = file.thumbnail_url || file.sthumb_url || ''
        if (!src) {
          failed.push(`${file.original_name || file.name || file.id}: サムネイルURLなし`)
          continue
        }
        const r = await fetch(src)
        if (!r.ok) {
          failed.push(`${file.original_name || file.name || file.id}: サムネ取得失敗 (${r.status})`)
          continue
        }
        const blob = await r.blob()
        if (!blob?.size) {
          failed.push(`${file.original_name || file.name || file.id}: サムネが空`)
          continue
        }
        const vec = await extractPhotoEmbeddingFloat32(blob)
        items.push({ file_id: file.id, embedding: Array.from(vec) })
      } catch (err) {
        failed.push(`${file.original_name || file.name || file.id}: ${err?.message || err}`)
      }
    }

    if (items.length === 0) {
      await dialog.alert(`特徴値の生成に失敗しました。\n${failed.slice(0, 8).join('\n')}`, { title: 'エラー' })
      return
    }

    const payload = {
      work_id: props.workId,
      items,
      model_name_version: modelVersion
    }
    if (housingDetailId != null && housingDetailId !== '') payload.housing_detail_id = housingDetailId
    await supabaseService.savePhotoEmbeddingsBatch(payload)

    const next = new Set(embeddingFileIds.value)
    for (const it of items) next.add(String(it.file_id))
    embeddingFileIds.value = next

    if (failed.length > 0) {
      await dialog.alert(`特徴値登録完了: ${items.length}件\n失敗: ${failed.length}件\n${failed.slice(0, 5).join('\n')}`, { title: '成功' })
    } else {
      await dialog.alert(`特徴値登録完了: ${items.length}件`, { title: '成功' })
    }
  } catch (err) {
    await dialog.alert(err?.message || '特徴値生成に失敗しました', { title: 'エラー' })
  } finally {
    featureGenerateLoading.value = false
    featureGenerateProgress.value = { current: 0, total: 0 }
  }
}

async function onFetchSimilar() {
  similarError.value = ''
  if (!props.workId || !selectedFileId.value) return
  if (isSupplementSlotId(selectedFileId.value) || !selectedFile.value) {
    return
  }
  const requestedFileId = selectedFileId.value
  similarLoading.value = true
  try {
    if (!selectedHasEmbedding.value) {
      const url =
        selectedFile.value?.thumbnail_url ||
        selectedFile.value?.sthumb_url ||
        selectedFile.value?.public_url
      if (!url) {
        similarError.value = '画像URLを取得できません'
        return
      }
      const r = await fetch(url)
      if (!r.ok) {
        similarError.value = 'サムネイルの取得に失敗しました'
        return
      }
      const blob = await r.blob()
      const { extractPhotoEmbeddingFloat32, getPhotoEmbeddingModelVersion } = await import('../utils/photoEmbedding.js')
      const vec = await extractPhotoEmbeddingFloat32(blob)
      await supabaseService.savePhotoEmbedding({
        file_id: requestedFileId,
        work_id: props.workId,
        embedding: Array.from(vec),
        model_name_version: getPhotoEmbeddingModelVersion()
      })
      const next = new Set(embeddingFileIds.value)
      next.add(String(requestedFileId))
      embeddingFileIds.value = next
    }
    const search = await supabaseService.searchSimilarPhotos({
      file_id: requestedFileId,
      work_id: props.workId,
      scope: includeAllHousing.value ? 'all' : 'filtered'
    })
    const pack = search?.result || search
    const records = Array.isArray(pack?.records) ? pack.records : []
    const hid = currentWorkHousingId.value
    similarByColumn.similarImage = makeTop20DedupByCode(records)
    similarByColumn.sameHousing = makeTop20DedupByCode(
      records.filter((r) => hid && String(r?.housing_detail_id || '') === hid)
    )
    similarResultFileId.value = requestedFileId
    await nextTick()
    scrollSimilarListsToTop()
  } catch (e) {
    console.error(e)
    similarError.value = e?.message || '類似取得に失敗しました'
  } finally {
    similarLoading.value = false
  }
}

async function onFetchSimilarFiltered() {
  collapseThumbsExpandMode()
