}

function templateLineForRow(row) {
  const k = normalizeExternalCode(row?.external_code)
  if (!k) return ''
  const o = props.templateInstructionByNormCode || {}
  return String(o[k] ?? '')
}

/** 原本に同一コードが無い行（概要ダブルクリックの対象） */
function rowDescDblClickEnabled(row) {
  const code = String(row?.external_code ?? '').trim()
  if (!code) return false
  return !String(templateLineForRow(row) || '').trim()
}

function rowHasDescText(row) {
  return Boolean(descTextForPart(row, 'main'))
}

/** 概要があり、原本に無いコード行のみ薄青枠 */
function rowDescStackShowBlueBorder(row) {
  return rowDescDblClickEnabled(row) && rowHasDescText(row)
}

/** コードあり・原本テキストなし（薄赤枠の対象） */
function rowOriginalTemplateEmpty(row) {
  const code = String(row?.external_code ?? '').trim()
  if (!code) return false
  return !String(templateLineForRow(row) || '').trim()
}

function descTextForPart(row, part) {
  if (part === 'add') return String(displayPlAdditionalDescription(row) || '').trim()
  return String(displayPlDescription(row) || '').trim()
}

function descLineTitle(row, part = 'main') {
  const desc = descTextForPart(row, part)
  if (part === 'add') return desc || undefined
  if (rowDescDblClickEnabled(row)) {
    const hint = isTabletTapToApplyMode.value
      ? 'ダブルタップで内容欄へ入力'
      : 'ダブルクリックで内容欄へ入力'
    return desc ? `${desc}\n（${hint}）` : hint
  }
  return desc || undefined
}

function descStackTapKey(rowIx) {
  return `${String(selectedFileId.value || '')}:${Number(rowIx)}:main`
}

function applyDescPartToContent(row, rowIx) {
  if (isMobilePhotoInputsMode.value) return
  if (!rowDescDblClickEnabled(row)) return
  const text = descTextForPart(row, 'main')
  if (!text) return
  markPhotoDirty({ captureUndo: true })
  row.content = text
  flashInputRow(selectedFileId.value, rowIx, 'blue')
}

/** PC: 概要のダブルクリックで内容欄へ上書き */
function onDescStackDblClick(row, rowIx, ev) {
  ev?.preventDefault?.()
  applyDescPartToContent(row, rowIx)
}

/** タブレット: 概要の2回タップで内容欄へ上書き */
function onDescStackClick(row, rowIx, ev) {
  if (!isTabletTapToApplyMode.value) return
  if (ev?.type === 'click' && Number(ev?.detail) >= 2) return
  if (!rowDescDblClickEnabled(row)) return
  const text = descTextForPart(row, 'main')
  if (!text) return
  ev?.preventDefault?.()
  const key = descStackTapKey(rowIx)
  if (descStackTapPendingKey.value === key) {
    descStackTapPendingKey.value = ''
    if (descStackTapTimer) clearTimeout(descStackTapTimer)
    descStackTapTimer = null
    applyDescPartToContent(row, rowIx)
    return
  }
  descStackTapPendingKey.value = key
  if (descStackTapTimer) clearTimeout(descStackTapTimer)
  descStackTapTimer = setTimeout(() => {
    descStackTapPendingKey.value = ''
    descStackTapTimer = null
  }, DESC_STACK_DOUBLE_TAP_MS)
}

async function onSaveAll() {
  saveError.value = ''
  if (!props.workId) return
  photoSaving.value = true
  try {
    const preserveSelectedFileId = selectedFileId.value
    const preserveThumbScrollTop = thumbListRef.value?.scrollTop ?? 0
    const toDelete = [...pendingStorageDeleteIds.value]
    if (toDelete.length > 0) {
      const delItems = toDelete.map((id) => {
        const file = photoList.value.find((f) => String(f.id) === String(id))
        return {
          id,
          name: file?.original_name || file?.name || '',
          is_folder: false
        }
      })
      const checkBody = {
        action: 'check_delete_batch',
        scope: 'work',
        work_id: props.workId,
        items: delItems
      }
      const checkRes = await supabaseService.manageCloudStorage(checkBody)
      if (!checkRes?.all_ok && checkRes?.errors?.length > 0) {
        const msg = checkRes.errors.map((e) => `${e.name || e.id}: ${e.error}`).join('\n')
        throw new Error(`削除できません:\n${msg}`)
      }
      const subfolders = checkRes?.items_with_subfolders ?? []
      if (checkRes?.all_ok && subfolders.length > 0) {
        const names = subfolders.map((f) => f.name || f.id).join('\n')
        const ok = await dialog.confirm(`以下のフォルダにはサブフォルダが含まれています。全て削除しますか？\n\n${names}`, { title: '確認' })
        if (!ok) {
          throw new Error('キャンセルされました')
        }
      }
      await supabaseService.manageCloudStorage({
        action: 'delete_batch',
        scope: 'work',
        work_id: props.workId,
        items: delItems
      })
      const deletedIdSet = new Set(toDelete.map(String))
      photoList.value = photoList.value.filter((f) => !deletedIdSet.has(String(f.id)))
      Object.keys(draftPhotoWorkLinksByFileId).forEach((fid) => {
        if (deletedIdSet.has(String(fid))) delete draftPhotoWorkLinksByFileId[fid]
      })
      Object.keys(existingPhotoWorkLinksByFileId).forEach((fid) => {
        if (deletedIdSet.has(String(fid))) delete existingPhotoWorkLinksByFileId[fid]
      })
      const nextEmb = new Set(embeddingFileIds.value)
      deletedIdSet.forEach((fid) => nextEmb.delete(fid))
      embeddingFileIds.value = nextEmb
    }

    const mapRowToSaveLink = (r) => {
      const code = String(r.external_code || '').trim()
      if (!code) return null
      const pl = priceByCode.value.get(code)
      const desc = pl
        ? combineDescForSave(pl.description || '', pl.additional_description || pl.note || '')
        : (() => {
            const sp = splitStoredDescription(r.description)
            return combineDescForSave(sp.main, sp.add)
          })()
      let qty = r.quantity
      if (qty === '' || qty === undefined || qty === null) {
        qty = null
      } else if (typeof qty === 'string') {
        const norm = normalizeQtyOnBlur(qty)
        if (norm === '' || norm === '.') qty = null
        else {
          const n = parseFloat(norm)
          qty = Number.isFinite(n) ? n : null
        }
      }
      const cid =
        r.contractor_id != null && String(r.contractor_id).trim() !== '' ? String(r.contractor_id).trim() : null
      return {
        external_code: code,
        quantity: qty,
        is_quantity: Boolean(r.is_quantity),
        description: desc,
        content: String(r.content ?? '').trim(),
        contractor_id: cid
      }
    }

    const linksForPayload = (fid) =>
      roomBucketLinksForSave(fid)
        .map(mapRowToSaveLink)
        .filter((link) => link != null && link.quantity != null)

    for (const sk of visibleSupplementSlotKeys.value) {
      if (sk === NULL_FILE_SLOT_ID) continue
      const ord = parseRoomOrderFromSlotKey(sk)
      if (ord == null || isSupplementRoomLabelOrder(ord)) continue
      draftPhotoWorkLinksByFileId[sk] = sortRoomBucketLinksForSave(
        (draftPhotoWorkLinksByFileId[sk] || []).filter((r) => !isPhotoUiStateRow(r)),
        getSpecialContractorColumnMap()
      )
      normalizeLinkGridRows(sk)
    }

    const plainLinks = [...linksForPayload(NULL_FILE_SLOT_ID)]

    const items = [{ file_id: null, room_label_order: SUPPLEMENT_ROOM_LABEL_ORDER, links: plainLinks }]
    for (const sk of visibleSupplementSlotKeys.value) {
      if (sk === NULL_FILE_SLOT_ID) continue
      const ord = parseRoomOrderFromSlotKey(sk)
      if (ord == null) continue
      items.push({ file_id: null, room_label_order: ord, links: linksForPayload(sk) })
    }
    for (const f of visiblePhotoList.value) {
      items.push({ file_id: f.id, room_label_order: null, links: linksForPayload(f.id) })
    }
    await supabaseService.savePhotoWorkLinksBatch(props.workId, items)

    await loadAll({ preserveSelectedFileId, preserveThumbScrollTop })
    pendingStorageDeleteIds.value = []
    hasLocalEdits.value = false
  } catch (e) {
    console.error(e)
    saveError.value = e?.message || '保存に失敗しました'
  } finally {
    photoSaving.value = false
  }
}

/** 部屋タブマトリクス: 選択セル（RoomMatrixPanel 連携） */
const roomMatrixSelectedCell = ref(null)
const roomMatrixFlash = ref(null)
let roomMatrixFlashTimer = null
let roomMatrixScrollIntoView = null

const ROOM_MATRIX_SCROLL_BOTTOM_GUTTER_PX = 140
const ROOM_MATRIX_SCROLL_TOP_GUTTER_PX = 36
const ROOM_MATRIX_FLASH_MS = 1200

function registerRoomMatrixScroll(fn) {
  roomMatrixScrollIntoView = typeof fn === 'function' ? fn : null
}

function unregisterRoomMatrixScroll() {
  roomMatrixScrollIntoView = null
}

function scrollRoomMatrixCell(roomOrder, colKey, rowIndex, scrollOptions = {}) {
  if (!roomMatrixScrollIntoView || rowIndex == null) return
  nextTick(() => {
    roomMatrixScrollIntoView(Number(roomOrder), String(colKey || ''), Number(rowIndex), {
      bottomGutterPx: ROOM_MATRIX_SCROLL_BOTTOM_GUTTER_PX,
      topGutterPx: ROOM_MATRIX_SCROLL_TOP_GUTTER_PX,
      ...scrollOptions,
    })
  })
}

function flashRoomMatrixCell(roomOrder, colKey, rowIndex, type = 'orange', scrollOptions = {}) {
  const normalizedType = type === 'blue' || type === 'red' ? type : 'orange'
  roomMatrixFlash.value = {
    roomOrder: Number(roomOrder),
    colKey: String(colKey || ''),
    rowIndex: rowIndex != null ? Number(rowIndex) : null,
    type: normalizedType,
  }
  if (roomMatrixFlashTimer) clearTimeout(roomMatrixFlashTimer)
  roomMatrixFlashTimer = setTimeout(() => {
    roomMatrixFlash.value = null
    roomMatrixFlashTimer = null
  }, ROOM_MATRIX_FLASH_MS)
  if (rowIndex != null) {
    scrollRoomMatrixCell(roomOrder, colKey, rowIndex, scrollOptions)
  }
}

function resolveUserProfileIdForContractors() {
  for (const c of props.contractors || []) {
    if (c?.user_profile_id != null) return Number(c.user_profile_id)
  }
  return null
}

function getSpecialContractorColumnMap() {
  return buildSpecialContractorColumnMap(props.contractors, resolveUserProfileIdForContractors())
}

function ensureRoomBucketDraft(roomOrder) {
  const sk = roomOrderSlotKey(roomOrder)
  if (!sk) return null
  if (!draftPhotoWorkLinksByFileId[sk]) {
    draftPhotoWorkLinksByFileId[sk] = stripLegacyMatrixDummyRows(
      cloneLinks(existingPhotoWorkLinksByFileId[sk])
    )
  }
  normalizeLinkGridRows(sk)
  return sk
}

const matrixLinkMutationOptions = () => ({
  createEmptyRow: emptyLinkRow,
  maxRows: LINK_GRID_MAX_ROWS,
})

function getRoomBucketLinks(roomOrder) {
  const sk = roomOrderSlotKey(roomOrder)
  if (!sk) return []
  ensureRoomBucketDraft(roomOrder)
  return draftPhotoWorkLinksByFileId[sk] || []
}

function roomBucketLinksForSave(fid) {
  let rows = (draftPhotoWorkLinksByFileId[fid] || []).filter((r) => !isPhotoUiStateRow(r))
  const ord = parseRoomOrderFromSlotKey(fid)
  if (ord != null && !isSupplementRoomLabelOrder(ord)) {
    rows = sortRoomBucketLinksForSave(rows, getSpecialContractorColumnMap())
  }
  return rows
}

function commitRoomBucketLinks(roomOrder, links) {
  const sk = ensureRoomBucketDraft(roomOrder)
  if (!sk) return false
  pushPhotoUndoSnapshot()
  draftPhotoWorkLinksByFileId[sk] = stripLegacyMatrixDummyRows(links)
  normalizeLinkGridRows(sk)
  markSpecificPhotoRowDirty(sk)
  emit('draft-change')
  return true
}

function templateInstructionMapForMatrix() {
  const raw = props.templateInstructionByNormCode
  if (raw instanceof Map) return raw
  const map = new Map()
  if (raw && typeof raw === 'object') {
    for (const [k, v] of Object.entries(raw)) {
      map.set(k, v)
    }
  }
  return map
}

function buildRoomMatrixViewForRoom(roomOrder) {
  return buildRoomMatrixView({
    roomOrder,
    links: getRoomBucketLinks(roomOrder),
    columnMap: getSpecialContractorColumnMap(),
    templateByCode: templateInstructionMapForMatrix(),
  })
}

function setSelectedRoomBucket(roomOrder) {
