watch(isRoomLabelOrderSlotSelected, (active) => {
  emit('mobile-room-view-active-change', Boolean(active))
  if (!active || props.mobileLayout !== 'photo') return
  if (mobilePhotoViewMode.value !== 'photo') {
    mobilePhotoViewMode.value = 'photo'
    emit('mobile-photo-view-mode-change', 'photo')
  }
}, { immediate: true })

watch(selectedFileId, (fid, prevFid) => {
