})

function upsertRoomMatrixCell({ roomOrder, colKey, rowIndex, patch, contractorIdOverride = null }) {
  const map = getSpecialContractorColumnMap()
  const columnContractorId = map.columns[colKey]
  const contractorId = contractorIdOverride || columnContractorId
  if (!contractorId) return false
  const result = upsertRoomMatrixCellInBucket(
    getRoomBucketLinks(roomOrder),
    { contractorId, rowIndex, patch },
    matrixLinkMutationOptions()
  )
  if (!result.changed) return false
  const ok = commitRoomBucketLinks(roomOrder, result.links)
  if (ok) {
    const sk = roomOrderSlotKey(roomOrder)
    if (sk) ensureTrailingLinkRowAfterComplete(sk)
  }
  return ok
}

function clearRoomMatrixCell({ roomOrder, colKey, rowIndex }) {
  const map = getSpecialContractorColumnMap()
  const contractorId = map.columns[colKey]
  if (!contractorId) return false
  const result = clearRoomMatrixCellInBucket(
    getRoomBucketLinks(roomOrder),
    { contractorId, rowIndex },
    matrixLinkMutationOptions()
  )
  if (!result.changed) return false
  return commitRoomBucketLinks(roomOrder, result.links)
}

function updateRoomMatrixCellContent({ roomOrder, colKey, rowIndex, content }) {
  return upsertRoomMatrixCell({
    roomOrder,
    colKey,
    rowIndex,
    patch: { content: String(content ?? '') },
  })
}

function flashRoomMatrixColumn(roomOrder, colKey, type = 'red', rowIndex = null, scrollOptions = {}) {
  flashRoomMatrixCell(roomOrder, colKey, rowIndex, type, scrollOptions)
}

function resolveRoomMatrixTarget(target = null) {
  if (target?.roomOrder != null && target?.colKey) {
    return {
      roomOrder: Number(target.roomOrder),
      colKey: String(target.colKey || ''),
    }
  }
  const sel = roomMatrixSelectedCell.value
  if (!sel) return null
  return {
    roomOrder: Number(sel.roomOrder),
    colKey: String(sel.colKey || ''),
  }
}

function findMatrixDuplicateRowInColumn(links, contractorId, code, excludeRowIndex = -1) {
  const nk = normalizeExternalCode(code)
  if (!nk) return null
  const { slots } = buildMatrixSlotsForContractor(links, contractorId)
  for (let i = 0; i < slots.length; i++) {
    const rowNum = i + 1
    if (excludeRowIndex >= 0 && rowNum === excludeRowIndex) continue
    const row = slots[i]
    if (isMatrixDummyRow(row)) continue
    if (normalizeExternalCode(row?.external_code) === nk) return rowNum
  }
  return null
}

async function applyDropToRoomMatrixTail(payload = {}, target = null) {
  const coords = resolveRoomMatrixTarget(target)
  if (!coords) return { ok: false, reason: 'no-selection' }

  const code = String(payload.external_code ?? '').trim()
  if (!code) return { ok: false, reason: 'no-code', ...coords }

  const map = getSpecialContractorColumnMap()
  let colKey = coords.colKey
  let contractorId = map.columns[colKey]
  if (!contractorId) return { ok: false, reason: 'no-contractor', ...coords }

  if (payload.source === 'original-instruction') {
    const placement = await resolveOriginalDropContractorPlacement(code, colKey, contractorId)
    if (!placement) return { ok: false, reason: 'cancelled', ...coords }
    colKey = placement.colKey
    contractorId = placement.contractorId
    coords.colKey = colKey
  }

  if (matrixRoomLabelBlocksDrop(coords.roomOrder)) {
    const linksForBlock = getRoomBucketLinks(coords.roomOrder)
    const blockTailRow =
      findNextMatrixTailRowIndex(linksForBlock, contractorId) || 1
    flashRoomMatrixCell(coords.roomOrder, colKey, blockTailRow, 'red')
    return { ok: false, reason: 'blank-room-label', ...coords, rowIndex: blockTailRow }
  }

  const links = getRoomBucketLinks(coords.roomOrder)
  const visibleBefore = getMatrixVisibleRowCountForRoom(links, map)
  const tailRow = findNextMatrixTailRowIndex(links, contractorId)
  if (!tailRow) {
    flashRoomMatrixCell(coords.roomOrder, colKey, ROOM_MATRIX_ROW_COUNT, 'red', {
      showRowBelow: false,
    })
    return { ok: false, reason: 'full', ...coords }
  }

  const dupRow = findMatrixDuplicateRowInColumn(links, contractorId, code)
  if (dupRow != null) {
    flashRoomMatrixCell(coords.roomOrder, colKey, dupRow, 'red')
    return { ok: false, reason: 'duplicate', ...coords, rowIndex: dupRow }
  }

  const patch = {
    external_code: code,
    quantity: 1,
    is_quantity: false,
  }
  if (payload.description != null) patch.description = String(payload.description)

  const ok = upsertRoomMatrixCell({
    roomOrder: coords.roomOrder,
    colKey,
    rowIndex: tailRow,
    patch,
    contractorIdOverride: contractorId,
  })
  if (ok) {
    selectRoomMatrixCell({ roomOrder: coords.roomOrder, colKey, rowIndex: tailRow })
    const linksAfter = getRoomBucketLinks(coords.roomOrder)
    const visibleAfter = getMatrixVisibleRowCountForRoom(linksAfter, map)
    const scrollOptions = { showRowBelow: true }
    if (visibleAfter > visibleBefore) {
      scrollOptions.ensureRowVisible = visibleAfter
    }
    flashRoomMatrixCell(coords.roomOrder, colKey, tailRow, 'orange', scrollOptions)
  }
  return { ok, reason: ok ? null : 'upsert-failed', ...coords, rowIndex: tailRow }
}

function moveRoomMatrixCell({ from, to }) {
  if (!from || !to) return { ok: false, reason: 'invalid' }

  const fromRoom = Number(from.roomOrder)
  const toRoom = Number(to.roomOrder)
  if (!Number.isFinite(fromRoom) || !Number.isFinite(toRoom)) {
    return { ok: false, reason: 'invalid-room' }
  }

  const map = getSpecialContractorColumnMap()
  const fromContractorId = map.columns[from.colKey]
  const toContractorId = map.columns[to.colKey]
  if (!fromContractorId || !toContractorId) return { ok: false, reason: 'no-contractor' }

  const sameRoom = fromRoom === toRoom
  const sameCol = String(from.colKey) === String(to.colKey)

  if (sameRoom && sameCol) {
    const links = getRoomBucketLinks(fromRoom)
    const result = reorderMatrixColumnInBucket(
      links,
      fromContractorId,
      from.rowIndex,
      to.rowIndex,
      matrixLinkMutationOptions()
    )
    if (!result.changed) {
      return {
        ok: false,
        reason: result.reason || 'reorder-failed',
        roomOrder: fromRoom,
        colKey: from.colKey,
      }
    }
    const ok = commitRoomBucketLinks(fromRoom, result.links)
    const effectiveToRow = result.toRowIndex ?? Number(to.rowIndex)
    if (ok) {
      selectRoomMatrixCell({
        roomOrder: fromRoom,
        colKey: from.colKey,
        rowIndex: effectiveToRow,
      })
      flashRoomMatrixCell(fromRoom, from.colKey, effectiveToRow, 'orange')
    }
    return {
      ok,
      reason: ok ? null : 'commit-failed',
      roomOrder: fromRoom,
      colKey: from.colKey,
      rowIndex: effectiveToRow,
    }
  }

  // 別ルーム or 別列: 最終尾へコピー（元セルはそのまま）
  const fromLinks = getRoomBucketLinks(fromRoom)
  const { slots: fromSlots } = buildMatrixSlotsForContractor(fromLinks, fromContractorId)
  const patch = extractMatrixCellPatchFromRow(fromSlots[Number(from.rowIndex) - 1])
  if (!patch) return { ok: false, reason: 'empty-source', roomOrder: toRoom, colKey: to.colKey }

  const toLinks = getRoomBucketLinks(toRoom)
  if (matrixRoomLabelBlocksDrop(toRoom)) {
    const blockTailRow =
      findNextMatrixTailRowIndex(toLinks, toContractorId) || 1
    flashRoomMatrixCell(toRoom, to.colKey, blockTailRow, 'red')
    return {
      ok: false,
      reason: 'blank-room-label',
      roomOrder: toRoom,
      colKey: to.colKey,
      rowIndex: blockTailRow,
    }
  }

  const visibleBefore = getMatrixVisibleRowCountForRoom(toLinks, map)
  const tailRow = findNextMatrixTailRowIndex(toLinks, toContractorId)
  if (!tailRow) {
    flashRoomMatrixCell(toRoom, to.colKey, ROOM_MATRIX_ROW_COUNT, 'red', { showRowBelow: false })
    return { ok: false, reason: 'full', roomOrder: toRoom, colKey: to.colKey }
  }

  const code = String(patch.external_code || '').trim()
  if (code) {
    const dupRow = findMatrixDuplicateRowInColumn(toLinks, toContractorId, code)
    if (dupRow != null) {
      flashRoomMatrixCell(toRoom, to.colKey, dupRow, 'red')
      return { ok: false, reason: 'duplicate', roomOrder: toRoom, colKey: to.colKey, rowIndex: dupRow }
    }
  }

  const upserted = upsertRoomMatrixCellInBucket(
    toLinks,
    { contractorId: toContractorId, rowIndex: tailRow, patch: { ...patch } },
    matrixLinkMutationOptions()
  )
  if (!upserted.changed) {
    return { ok: false, reason: 'copy-failed', roomOrder: toRoom, colKey: to.colKey }
  }

  pushPhotoUndoSnapshot()
  const sk = ensureRoomBucketDraft(toRoom)
  if (!sk) return { ok: false, reason: 'no-bucket', roomOrder: toRoom, colKey: to.colKey }
  draftPhotoWorkLinksByFileId[sk] = stripLegacyMatrixDummyRows(upserted.links)
  normalizeLinkGridRows(sk)
  ensureTrailingLinkRowAfterComplete(sk)
  markSpecificPhotoRowDirty(sk)
  emit('draft-change')

  selectRoomMatrixCell({ roomOrder: toRoom, colKey: to.colKey, rowIndex: tailRow })
  const linksAfter = getRoomBucketLinks(toRoom)
  const visibleAfter = getMatrixVisibleRowCountForRoom(linksAfter, map)
  const scrollOptions = { showRowBelow: true }
  if (visibleAfter > visibleBefore) {
    scrollOptions.ensureRowVisible = visibleAfter
  }
  flashRoomMatrixCell(toRoom, to.colKey, tailRow, 'orange', scrollOptions)
  return { ok: true, reason: null, roomOrder: toRoom, colKey: to.colKey, rowIndex: tailRow }
}

async function applyDropToSelectedRoomMatrixCell(payload = {}) {
  const result = await applyDropToRoomMatrixTail(payload)
  return result?.ok
