/**
 * 見積 PDF / xl_get_estimate_field 共通の word_count 設定（旧 excel_templates 相当）
 * 本番で使っていた値に合わせて更新すること
 */
export const ESTIMATE_EXPORT_WORD_COUNT = 50
export const ESTIMATE_EXPORT_HIGHLIGHTED_WORD_COUNT = 40
export const ESTIMATE_EXPORT_HIGHLIGHTED_FONT_SIZE = 15

export function getEstimateExportTemplateSettings() {
  return {
    word_count: ESTIMATE_EXPORT_WORD_COUNT,
    highlighted_word_count: ESTIMATE_EXPORT_HIGHLIGHTED_WORD_COUNT,
    highlighted_font_size: ESTIMATE_EXPORT_HIGHLIGHTED_FONT_SIZE,
  }
}
