/**
 * 生成済み PDF の開き方（端末別）
 * - PC（幅 > 1500px）: a[download] でファイル名付き保存（従来どおり）
 * - スマホ・タブレット（幅 <= 1500px）: 別タブで blob 表示（iOS Safari 向け）
 */

/** useViewport の tabletMax と揃える */
const TABLET_MAX_WIDTH = 1500

export function shouldOpenPdfInNewTab() {
  if (typeof window === 'undefined') return false
  return window.matchMedia(`(max-width: ${TABLET_MAX_WIDTH}px)`).matches
}

/**
 * 非同期 PDF 生成の前に、ユーザ操作コンテキスト内で空タブを開く（モバイル/タブレットのみ）
 * noopener 付き open は戻り値が null になり、後から location を設定できない
 */
export function openPdfBlankTabForAsyncGenerate() {
  if (!shouldOpenPdfInNewTab()) return null
  try {
    return window.open('about:blank', '_blank')
  } catch {
    return null
  }
}

export function closePdfTab(pdfWindow) {
  try {
    if (pdfWindow && !pdfWindow.closed) {
      pdfWindow.close()
    }
  } catch {
    // ignore
  }
}

function downloadPdfBlob(blob, fileName) {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = fileName
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)
  return true
}

/**
 * @param {Blob | Uint8Array | ArrayBuffer} pdfData
 * @param {{ fileName?: string, pdfWindow?: Window | null }} [opts]
 * @returns {boolean}
 */
export function openGeneratedPdf(pdfData, opts = {}) {
  const { fileName = 'document.pdf', pdfWindow = null } = opts
  const blob =
    pdfData instanceof Blob ? pdfData : new Blob([pdfData], { type: 'application/pdf' })

  if (!shouldOpenPdfInNewTab()) {
    return downloadPdfBlob(blob, fileName)
  }

  return openPdfBlobInNewTab(blob, { pdfWindow })
}

/**
 * @param {Blob} blob
 * @param {{ pdfWindow?: Window | null }} [opts]
 * @returns {boolean}
 */
export function openPdfBlobInNewTab(blob, opts = {}) {
  const url = URL.createObjectURL(blob)
  const revokeLater = () => {
    window.setTimeout(() => URL.revokeObjectURL(url), 60_000)
  }

  const { pdfWindow = null } = opts
  if (pdfWindow && !pdfWindow.closed) {
    try {
      pdfWindow.location.href = url
      revokeLater()
      return true
    } catch {
      closePdfTab(pdfWindow)
    }
  }

  // 空タブへ遷移できなかったときだけ 1 回 open（noopener だと null 返却→a クリックで二重オープン）
  window.open(url, '_blank')
  revokeLater()
  return true
}
