/** 部屋タブ D&D: JSON はこちらのみ。text/plain は単価コード等の表示用（Safari の Google 検索誤爆防止） */
export const ROOM_MATRIX_DND_MIME = 'application/x-supabasu-room-matrix-dnd+json'

export function writeRoomMatrixDragData(dataTransfer, payload) {
  if (!dataTransfer || !payload) return
  const json = JSON.stringify(payload)
  try {
    dataTransfer.setData(ROOM_MATRIX_DND_MIME, json)
  } catch {
    // ignore
  }
  try {
    dataTransfer.setData('application/json', json)
  } catch {
    // ignore
  }
  const code = String(payload.external_code ?? '').trim()
  dataTransfer.setData('text/plain', code || '\u200b')
}

export function readRoomMatrixDragRaw(dataTransfer) {
  if (!dataTransfer) return ''
  for (const type of [ROOM_MATRIX_DND_MIME, 'application/json']) {
    try {
      const raw = String(dataTransfer.getData(type) ?? '').trim()
      if (raw.startsWith('{')) return raw
    } catch {
      // ignore
    }
  }
  return String(dataTransfer.getData('text/plain') ?? '').trim()
}

export function parseRoomMatrixDropPayload(raw) {
  const trimmed = String(raw ?? '').trim()
  if (!trimmed || trimmed === '\u200b') return null

  if (trimmed.startsWith('{')) {
    try {
      const o = JSON.parse(trimmed)
      if (!o || typeof o !== 'object') return null
      const code = String(o.external_code ?? '').trim()
      if (!code) return null
      if (o.type === 'original-instruction') {
        return {
          external_code: code,
          instruction: String(o.instruction ?? '').trim(),
          source: 'original-instruction',
        }
      }
      if (o.type === 'comparison-item') {
        return {
          external_code: code,
          description: String(o.billing_description ?? '').trim(),
        }
      }
      if (o.type === 'price-item') {
        return {
          external_code: code,
          description: String(o.description ?? '').trim(),
        }
      }
    } catch {
      return null
    }
    return null
  }

  return { external_code: trimmed }
}

export function parseRoomMatrixCellMovePayload(raw) {
  const trimmed = String(raw ?? '').trim()
  if (!trimmed.startsWith('{')) return null
  try {
    const o = JSON.parse(trimmed)
    if (o?.type !== 'room-matrix-cell') return null
    const roomOrder = Number(o.roomOrder)
    const rowIndex = Number(o.rowIndex)
    const colKey = String(o.colKey || '')
    if (!Number.isFinite(roomOrder) || !colKey || !Number.isFinite(rowIndex)) return null
    return { roomOrder, colKey, rowIndex }
  } catch {
    return null
  }
}
