<script setup>
import { ref, watch } from 'vue'
import { useViewport } from '../composables/useViewport.js'
import { useDialog } from '../composables/useDialog.js'
import {
  padWorkLargeScheduleRows,
  validateScheduleRowsForSave,
  findScheduleColumnIndexDuplicates,
} from '../constants/workLargeSchedule.js'

const { isMobile, isTablet } = useViewport({ mobileMax: 900, tabletMax: 1500 })
const dialog = useDialog()

const props = defineProps({
  isOpen: {
    type: Boolean,
    default: false,
  },
  rows: {
    type: Array,
    default: () => [],
  },
  statusOptions: {
    type: Array,
    default: () => [],
  },
  labelTemplateOptions: {
    type: Array,
    default: () => [],
  },
  saving: {
    type: Boolean,
    default: false,
  },
  canDelete: {
    type: Boolean,
    default: false,
  },
  deleting: {
    type: Boolean,
    default: false,
  },
})

const emit = defineEmits(['close', 'save', 'delete'])

const localRows = ref([])
const expandedMobileRows = ref(new Set())
const columnIndexConflictSortOrders = ref([])

function clearColumnIndexConflicts() {
  columnIndexConflictSortOrders.value = []
}

function isColumnIndexConflict(sortOrder) {
  return columnIndexConflictSortOrders.value.includes(Number(sortOrder))
}

function syncLocalFromProps(newRows) {
  localRows.value = padWorkLargeScheduleRows(newRows).map((row) => ({
    sort_order: row.sort_order,
    label: row.label ?? '',
    schedule_label_template_id: row.schedule_label_template_id ?? null,
    schedule_status_id: row.schedule_status_id ?? null,
    schedule_secondary_status_id: row.schedule_secondary_status_id ?? null,
    start_on: row.start_on ?? '',
    end_on: row.end_on ?? '',
    note: row.note ?? '',
  }))
}

function templateOptionLabel(tpl) {
  const category = String(tpl?.category ?? '').trim()
  return category || '　'
}

watch(() => props.rows, syncLocalFromProps, { immediate: true, deep: true })

watch(() => props.isOpen, (open) => {
  if (open) {
    expandedMobileRows.value = new Set()
    clearColumnIndexConflicts()
  }
})

function isMobileRowExpanded(sortOrder) {
  return expandedMobileRows.value.has(sortOrder)
}

function toggleMobileRow(sortOrder) {
  const next = new Set(expandedMobileRows.value)
  if (next.has(sortOrder)) {
    next.delete(sortOrder)
  } else {
    next.add(sortOrder)
  }
  expandedMobileRows.value = next
}

function getStatusKey(statusId) {
  if (statusId == null || statusId === '') return null
  const st = props.statusOptions.find((s) => Number(s.id) === Number(statusId))
  return st?.key ?? null
}

function rowHasStatusKey(row, key) {
  return (
    getStatusKey(row.schedule_status_id) === key ||
    getStatusKey(row.schedule_secondary_status_id) === key
  )
}

/** 1→4 の順で最初に該当した条件のみ返す */
function getRowHighlightStyle(row) {
  if (rowHasStatusKey(row, 'none')) return 'none'
  if (rowHasStatusKey(row, 'completed')) return 'completed'
  if (rowHasStatusKey(row, 'removed')) return 'removed'
  if (rowHasStatusKey(row, 'requested')) return 'requested'
  return null
}

function getRowHighlightClass(row) {
  const style = getRowHighlightStyle(row)
  return style ? `schedule-row--${style}` : null
}

function handleClose() {
  emit('close')
}

function handleDelete() {
  if (!props.canDelete || props.saving || props.deleting) return
  emit('delete')
}

async function handleSave() {
  const payload = localRows.value.map((row) => ({
    sort_order: row.sort_order,
    label: row.label ?? '',
    schedule_label_template_id: row.schedule_label_template_id ?? null,
    schedule_status_id: row.schedule_status_id ?? null,
    schedule_secondary_status_id: row.schedule_secondary_status_id ?? null,
    start_on: row.start_on || null,
    end_on: row.end_on || null,
    note: row.note || null,
  }))
  const err = validateScheduleRowsForSave(payload)
  if (err) {
    await dialog.alert(err, { title: '入力エラー' })
    return
  }
  const duplicate = findScheduleColumnIndexDuplicates(payload, props.labelTemplateOptions)
  if (duplicate) {
    columnIndexConflictSortOrders.value = duplicate.conflictSortOrders
    await dialog.alert(duplicate.message, { title: '入力エラー' })
    return
  }
  clearColumnIndexConflicts()
  emit('save', payload)
}
</script>

