function countVisualLines(el) {
  const style = window.getComputedStyle(el)
  const lineHeight = Number.parseFloat(style.lineHeight)
  if (!Number.isFinite(lineHeight) || lineHeight <= 0) return 1
  return Math.max(1, Math.round(el.scrollHeight / lineHeight))
}

function updateScheduleCellAlign(el) {
  const workLines = el.querySelectorAll('.schedule-grid-work-name-line')
  if (workLines.length > 0) {
    const isMultiLine =
      workLines.length >= 2 ||
      (workLines.length === 1 && countVisualLines(workLines[0]) > 1)
    el.classList.toggle('schedule-grid-cell-align--single', !isMultiLine)
    el.classList.toggle('schedule-grid-cell-align--multi', isMultiLine)
    return
  }

  const measureTarget =
    el.querySelector('.schedule-grid-cell-text-body') ??
    el.querySelector('.schedule-grid-work-name-line') ??
    el
  const namedLineCount = el.querySelectorAll('.schedule-grid-work-name-line').length
  const text = el.textContent?.trim() ?? ''
  const isMultiLine =
    namedLineCount >= 2 || (text.length > 0 && countVisualLines(measureTarget) > 1)

  el.classList.toggle('schedule-grid-cell-align--single', !isMultiLine)
  el.classList.toggle('schedule-grid-cell-align--multi', isMultiLine)
}

function bindScheduleCellAlign(el) {
  const update = () => {
    window.requestAnimationFrame(() => updateScheduleCellAlign(el))
  }
  el.__scheduleCellAlignUpdate = update
  update()
  const observer = new ResizeObserver(update)
  observer.observe(el)
  el.__scheduleCellAlignObserver = observer
}

const vScheduleCellAlign = {
  mounted(el) {
    bindScheduleCellAlign(el)
  },
  updated(el) {
    el.__scheduleCellAlignUpdate?.()
  },
  unmounted(el) {
    el.__scheduleCellAlignObserver?.disconnect()
    delete el.__scheduleCellAlignUpdate
    delete el.__scheduleCellAlignObserver
  },
}

