function pulseExpandPanelFlash() {
  const titleEl = expandPanelTitleRef.value
  const barEl = editorBarRef.value
  if (!titleEl || !barEl) return

  expandPanelTitleGlowAnimation?.cancel()
  expandPanelBarGlowAnimation?.cancel()

  const baseBg = '#f8fafc'
  const peakBg = '#dbeafe'
  const titlePeakShadow =
    '0 0 8px 2px rgba(147, 197, 253, 0.38), 0 0 18px 5px rgba(147, 197, 253, 0.28), 0 0 32px 9px rgba(147, 197, 253, 0.18), inset 0 0 0 1px rgba(96, 165, 250, 0.55)'
  const barPeakShadow =
    '0 0 10px 3px rgba(147, 197, 253, 0.36), 0 0 24px 8px rgba(147, 197, 253, 0.24), 0 0 42px 14px rgba(147, 197, 253, 0.14)'

  const glowTiming = {
    duration: EXPAND_PANEL_GLOW_DURATION_MS,
    easing: EXPAND_PANEL_GLOW_EASING,
    fill: 'none',
  }

  expandPanelTitleGlowAnimation = titleEl.animate(
    [
      { backgroundColor: baseBg, boxShadow: 'none' },
      { backgroundColor: peakBg, boxShadow: titlePeakShadow, offset: 0.22 },
      {
        backgroundColor: baseBg,
        boxShadow:
          '0 0 6px 2px rgba(147, 197, 253, 0.22), 0 0 14px 4px rgba(147, 197, 253, 0.14), inset 0 0 0 1px rgba(96, 165, 250, 0.32)',
        offset: 0.58,
      },
      { backgroundColor: baseBg, boxShadow: 'none' },
    ],
    glowTiming,
  )
