const MOBILE_DOUBLE_TAP_MS = 320
const mobileRowTapState = { workId: null, kind: null, at: 0 }
/** PC/タブレット: 1回目で行選択＋武装、同セル再クリックで起動 */
const rowActionArmed = ref(null)

function isRowActionArmed(workId, kind) {
  const armed = rowActionArmed.value
  return armed?.workId === String(workId) && armed?.kind === kind
}

function clearRowActionArmed() {
  rowActionArmed.value = null
}

function onWorkRowNameClick(event, workId) {
  if (props.isMobile) onMobileWorkNameTap(workId)
  else onRowNameTwoStepClick(workId, 'work', event)
}

function onEmployeeRowClick(event, workId) {
  if (props.isMobile) onMobileEmployeeTap(workId)
  else onRowNameTwoStepClick(workId, 'employee', event)
}

function onRowNameTwoStepClick(workId, kind, event) {
  const wid = String(workId)
  if (isRowActionArmed(wid, kind)) {
    clearRowActionArmed()
    if (kind === 'work') handleWorkNameDoubleClick(workId)
    else handleEmployeeDoubleClick(workId)
    return
  }
  rowActionArmed.value = { workId: wid, kind }
  selectWorkRowScheduleColumns(workId, { extend: Boolean(event?.shiftKey) })
}

function onMobileWorkNameTap(workId) {
  handleMobileRowTap(workId, 'work', () => selectWorkRowScheduleColumns(workId), () =>
    handleWorkNameDoubleClick(workId),
  )
}

function onMobileEmployeeTap(workId) {
  handleMobileRowTap(workId, 'employee', () => selectWorkRowScheduleColumns(workId), () =>
    handleEmployeeDoubleClick(workId),
  )
}

function handleMobileRowTap(workId, kind, onSingleTap, onDoubleTap) {
  const wid = String(workId)
  const now = Date.now()
  if (
    mobileRowTapState.workId === wid &&
    mobileRowTapState.kind === kind &&
    now - mobileRowTapState.at <= MOBILE_DOUBLE_TAP_MS
  ) {
    mobileRowTapState.workId = null
    mobileRowTapState.kind = null
    mobileRowTapState.at = 0
    onDoubleTap()
    return
  }
  mobileRowTapState.workId = wid
  mobileRowTapState.kind = kind
  mobileRowTapState.at = now
  window.setTimeout(() => {
    if (
      mobileRowTapState.workId !== wid ||
      mobileRowTapState.kind !== kind ||
      Date.now() - mobileRowTapState.at < MOBILE_DOUBLE_TAP_MS
    ) {
      return
    }
    mobileRowTapState.workId = null
    mobileRowTapState.kind = null
    mobileRowTapState.at = 0
    onSingleTap()
  }, MOBILE_DOUBLE_TAP_MS + 20)
}

