}

function syncDirtyWorkIdForWork(workId) {
  const wid = String(workId)
  const baseline = savedBaselineByWorkId.value.get(wid)
  if (!baseline) return
  if (
    columnCellsDifferFromBaseline(
      getColumnCellsForWork(wid),
      getColumnCellsForWork(wid, baseline),
    )
  ) {
    dirtyWorkIds.value.add(wid)
  } else {
    dirtyWorkIds.value.delete(wid)
  }
}

function isCellDirty(workId, columnIndex) {
  const wid = String(workId)
  const baseline = savedBaselineByWorkId.value.get(wid)
  if (!baseline) return false
  return isCellDirtyAtColumn(
    columnIndex,
    getColumnCellsForWork(wid),
    getColumnCellsForWork(wid, baseline),
  )
}

function pushCellChangesUndo(changes) {
  if (!changes.length) return
  if (changes.length === 1) {
    pushUndo({ type: 'cell', ...changes[0] })
    return
  }
  pushUndo({
    type: 'batch-cells',
    changes: changes.map((change) => ({
      workId: String(change.workId),
      columnIndex: change.columnIndex,
      previousRow: cloneScheduleRowForUndo(change.previousRow),
    })),
  })
}

function applyCellUndo({ workId, columnIndex, previousRow }) {
  const wid = String(workId)
  const col = Number(columnIndex)
  const rows = cloneRows(getRowsForWork(wid))
  const currentCell = getColumnCellsForWork(wid, rows)[col]
  const targetIndex = resolveRowIndexForColumnCell(wid, rows, col, currentCell, previousRow)
  if (targetIndex < 0) return

  const cleared = {
    schedule_status_id: null,
    schedule_secondary_status_id: null,
    label: '',
    start_on: null,
    end_on: null,
    note: '',
  }
  rows[targetIndex] = previousRow
    ? {
        ...rows[targetIndex],
        ...cloneScheduleRowForUndo(previousRow),
        sort_order: rows[targetIndex].sort_order,
        id: previousRow.id ?? rows[targetIndex].id ?? null,
      }
    : {
        ...rows[targetIndex],
        ...cleared,
      }
  setRowsForWork(wid, rows)
}

function applyWorkChanges(workChanges) {
  const cellChanges = []
  for (const [wid, nextRows] of workChanges) {
    cellChanges.push(...collectCellChangesForWork(wid, getRowsForWork(wid), nextRows))
    setRowsForWork(wid, nextRows)
    syncDirtyWorkIdForWork(wid)
  }
  if (cellChanges.length) {
    pushCellChangesUndo(cellChanges)
    if (activeCell.value) refreshExpandedEditorFromRows(activeCell.value.workId)
  }
}

function cellClass(workId, columnIndex) {
  const row = getCellsForWork(workId)[columnIndex]
  const classes = []
  if (!row) {
    classes.push('schedule-grid-cell--empty')
  } else {
    const highlight = getScheduleRowHighlightKey(row, statusOptions.value)
    if (highlight) classes.push(`schedule-grid-cell--${highlight}`)
  }
  if (isCellInSelection(workId, columnIndex)) {
    classes.push('schedule-grid-cell--in-selection')
  }
  if (isActiveCell(workId, columnIndex)) {
    classes.push('schedule-grid-cell--active')
  }
  if (isCellDirty(workId, columnIndex)) {
    classes.push('schedule-grid-cell--dirty')
  }
  return classes
}

