async function loadMasterData() {
  const [statuses, templates, employeeRows, mcRows, jkkRows, progressiveRows, stepRows] = await Promise.all([
    supabaseService.getWorkScheduleStatuses(),
    supabaseService.getScheduleLabelTemplates(),
    indexedDBService.getMasterData('master_employees'),
    indexedDBService.getMasterData('master_mc'),
    indexedDBService.getMasterData('master_large_jkk_statuses'),
    indexedDBService.getMasterData('master_large_progressive_statuses'),
    indexedDBService.getMasterData('master_large_steps'),
  ])
  statusOptions.value = statuses || []
  labelTemplates.value = templates || []
  employees.value = (employeeRows || []).filter((row) => row.is_active !== false)
  mcs.value = (mcRows || []).filter((row) => row.is_active !== false)
  largeJkkStatuses.value = (jkkRows || []).filter((row) => row.is_active !== false)
  completedProgressiveStatusIds.value = resolveCompletedProgressiveStatusIds(progressiveRows || [])
  constructionCompletedStatusIds.value = resolveProgressiveStatusIdsByLabels(progressiveRows || [], ['工事完了'])
  keyReturnStatusIds.value = resolveProgressiveStatusIdsByLabels(progressiveRows || [], ['鍵返却'])
  largeSteps.value = stepRows || []
}

async function reloadScheduleLabelTemplates() {
  labelTemplates.value = await supabaseService.getScheduleLabelTemplates()
}

function mergeRowsFromServerItems(items) {
  const nextMap = new Map(rowsByWorkId.value)
  const validIds = new Set((items || []).map((item) => String(item.work_id)))
  for (const item of items || []) {
    const wid = String(item.work_id)
    if (!dirtyWorkIds.value.has(wid)) {
      const rows = cloneRows(padWorkLargeScheduleRows(item.rows || []))
      nextMap.set(wid, rows)
      setBaselineForWork(wid, rows)
    } else if (!nextMap.has(wid)) {
      const rows = cloneRows(padWorkLargeScheduleRows(item.rows || []))
      nextMap.set(wid, rows)
      setBaselineForWork(wid, rows)
    }
  }
  for (const key of nextMap.keys()) {
    if (!validIds.has(key) && !dirtyWorkIds.value.has(key)) {
      nextMap.delete(key)
      const nextBaseline = new Map(savedBaselineByWorkId.value)
      nextBaseline.delete(key)
      savedBaselineByWorkId.value = nextBaseline
    }
  }
  rowsByWorkId.value = nextMap
}

function updateAllGridItemRows(workId, rows) {
  const wid = String(workId)
  const index = allGridItems.value.findIndex((item) => String(item.work_id) === wid)
  if (index < 0) return
  allGridItems.value[index] = {
    ...allGridItems.value[index],
    rows: rows || [],
  }
}

async function reloadList() {
  if (loading.value) return
  loading.value = true
  error.value = null
  try {
    await loadMasterData()
    const result = await supabaseService.fetchWorkLargeScheduleList({})
    allGridItems.value = result.items || []
    mergeRowsFromServerItems(allGridItems.value)
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] reload failed:', err)
    error.value = err.message || '読み込みに失敗しました'
  } finally {
    loading.value = false
  }
}

