function openFilterModal(kind) {
  filterModalKind.value = kind
  if (kind === 'mc') filterModalSelected.value = [...filters.value.mcIds]
  else if (kind === 'registrationYear') filterModalSelected.value = [...filters.value.registrationYears]
  else if (kind === 'instructionYear') filterModalSelected.value = [...filters.value.instructionYears]
  else if (kind === 'employee') filterModalSelected.value = [...filters.value.employeeFilterValues]
  else filterModalSelected.value = [...filters.value.jkkStatusIds]
  filterModalOpen.value = true
}

function applyFilterModal(values) {
  if (filterModalKind.value === 'employee') {
    filters.value.employeeFilterValues = (values || []).map((value) => {
      if (value === SCHEDULE_GRID_EMPLOYEE_UNASSIGNED) return SCHEDULE_GRID_EMPLOYEE_UNASSIGNED
      const n = Number(value)
      return Number.isInteger(n) ? n : null
    }).filter((value) => value != null)
  } else {
    const normalized = values.map(Number).filter((n) => Number.isInteger(n))
    if (filterModalKind.value === 'mc') filters.value.mcIds = normalized
    else if (filterModalKind.value === 'registrationYear') filters.value.registrationYears = normalized
    else if (filterModalKind.value === 'instructionYear') filters.value.instructionYears = normalized
    else filters.value.jkkStatusIds = normalized
  }
  persistFilters()
}

function applyMobileSettings(nextFilters) {
  filters.value = {
    ...filters.value,
    ...nextFilters,
