async function openWorkLargeScheduleModalForWork(workId) {
  if (saving.value || workLargeScheduleSaving.value) return
  const wid = String(workId)
  modalWorkId.value = wid
  const mcId = gridItemMcId(workId)
  const mcTemplates = await supabaseService.getScheduleLabelTemplatesForMc(mcId)
  if (mcTemplates.length > 0) {
    const rest = labelTemplates.value.filter((row) => Number(row.mc_id) !== Number(mcId))
    labelTemplates.value = [...rest, ...mcTemplates].sort((a, b) => {
      const mcDiff = Number(a.mc_id) - Number(b.mc_id)
      if (mcDiff !== 0) return mcDiff
      return Number(a.sort_order) - Number(b.sort_order)
    })
  }
  let rows = cloneRows(getRowsForWork(wid))
  workLargeScheduleCanDelete.value = rows.some((row) => row.id != null && row.id !== '')
  if (!workLargeScheduleCanDelete.value) {
    const result = await supabaseService.getWorkLargeSchedules(wid).catch(() => ({ rows: [] }))
    const savedRows = result.rows || []
    workLargeScheduleCanDelete.value = savedRows.length > 0
    if (savedRows.length > 0) {
      rows = padWorkLargeScheduleRows(savedRows)
    } else if (!rows.some((row) => row.schedule_label_template_id)) {
      rows = buildWorkLargeScheduleRowsFromTemplate(mcTemplates)
    }
  }
  workLargeScheduleRows.value = rows
  isWorkLargeScheduleModalOpen.value = true
}

function closeWorkLargeScheduleModal() {
  isWorkLargeScheduleModalOpen.value = false
  modalWorkId.value = null
}

async function saveWorkLargeScheduleFromModal(rows) {
  if (!modalWorkId.value) return
  const wid = String(modalWorkId.value)
  workLargeScheduleSaving.value = true
  try {
    const result = await supabaseService.upsertWorkLargeSchedules(wid, rows)
    const savedRows = padWorkLargeScheduleRows(result.rows || [])
    setRowsForWork(wid, savedRows)
    updateAllGridItemRows(wid, result.rows || [])
    await supabaseService.cacheWorkLargeSchedulesForWork(wid, savedRows)
    workLargeScheduleCanDelete.value = savedRows.length > 0
    dirtyWorkIds.value.delete(wid)
    setBaselineForWork(wid, savedRows)
    undoHistory.value = undoHistory.value.filter((entry) => !entryAffectsWorkId(entry, wid))
    refreshExpandedEditorFromRows(wid)
    closeWorkLargeScheduleModal()
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] modal save failed:', err)
    await dialog.alert(`工程スケジュールの保存に失敗しました: ${err.message}`, { title: 'エラー' })
  } finally {
    workLargeScheduleSaving.value = false
  }
}

async function deleteWorkLargeScheduleFromModal() {
  if (!modalWorkId.value || !workLargeScheduleCanDelete.value) return
  const ok = await dialog.confirm(
    'この案件の進捗状況をすべて削除します。\nこの操作は取り消せません。よろしいですか？',
    { title: '確認' },
  )
  if (!ok) return
  const wid = String(modalWorkId.value)
  workLargeScheduleDeleting.value = true
  try {
    await supabaseService.deleteWorkLargeSchedules(wid)
    allGridItems.value = allGridItems.value.filter((item) => String(item.work_id) !== wid)
    const rows = buildWorkLargeScheduleRowsFromTemplate(labelTemplatesForWorkId(wid))
    setRowsForWork(wid, rows)
    await supabaseService.cacheWorkLargeSchedulesForWork(wid, [])
    workLargeScheduleCanDelete.value = false
    dirtyWorkIds.value.delete(wid)
    setBaselineForWork(wid, rows)
    undoHistory.value = undoHistory.value.filter((entry) => !entryAffectsWorkId(entry, wid))
    refreshExpandedEditorFromRows(wid)
    closeWorkLargeScheduleModal()
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] modal delete failed:', err)
    await dialog.alert(`工程スケジュールの削除に失敗しました: ${err.message}`, { title: 'エラー' })
  } finally {
    workLargeScheduleDeleting.value = false
  }
}

async function handleSave() {
  if (!hasUnsavedChanges.value || saving.value) return
  saving.value = true
  error.value = null
  try {
    const items = Array.from(dirtyWorkIds.value).map((workId) => ({
      work_id: workId,
      rows: getRowsForWork(workId).map((row) => ({
        sort_order: row.sort_order,
        label: row.label ?? '',
        schedule_label_template_id: row.schedule_label_template_id ?? null,
        schedule_status_id: row.schedule_status_id ?? null,
        schedule_secondary_status_id: row.schedule_secondary_status_id ?? null,
        start_on: row.start_on || null,
        end_on: row.end_on || null,
        note: row.note || null,
      })),
    }))
    const saved = await supabaseService.batchUpsertWorkLargeSchedules(items)
    for (const item of saved.items || []) {
      const savedRows = padWorkLargeScheduleRows(item.rows || [])
      setRowsForWork(item.work_id, savedRows)
      updateAllGridItemRows(item.work_id, item.rows || [])
      await supabaseService.cacheWorkLargeSchedulesForWork(item.work_id, item.rows || [])
      setBaselineForWork(item.work_id, savedRows)
    }
    dirtyWorkIds.value = new Set()
    undoHistory.value = []
  } catch (err) {
    console.error('[WorkLargeScheduleGrid] save failed:', err)
    error.value = err.message || '保存に失敗しました'
  } finally {
    saving.value = false
  }
}

function handleUndo() {
  const entry = undoHistory.value.pop()
  if (!entry) return

  if (entry.type === 'batch-cells') {
    const affected = new Set()
    for (const change of entry.changes) {
      applyCellUndo(change)
      affected.add(String(change.workId))
    }
    for (const wid of affected) {
      refreshExpandedEditorFromRows(wid)
      syncDirtyWorkIdForWork(wid)
    }
    return
  }

  if (entry.type === 'cell') {
    applyCellUndo(entry)
    refreshExpandedEditorFromRows(entry.workId)
    syncDirtyWorkIdForWork(entry.workId)
  }
}

watch(expandCellPreviewText, () => {
  if (!expandFieldPreview.value.visible) return
  nextTick(onExpandFieldPreviewReposition)
})

watch(
  () => props.isTabActive,
  (active) => {
    if (active && allGridItems.value.length === 0 && !loading.value) {
      reloadList()
    }
  },
)

onMounted(async () => {
  filters.value = loadScheduleGridFilters()
  document.addEventListener('keydown', onDocumentKeyDown)
  document.addEventListener('mouseup', onDocumentMouseUp)
  window.addEventListener('scroll', onExpandFieldPreviewReposition, true)
  window.addEventListener('resize', onExpandFieldPreviewReposition)
  if (props.isTabActive) {
    await reloadList()
  }
})

onUnmounted(() => {
  expandPanelTitleGlowAnimation?.cancel()
  expandPanelBarGlowAnimation?.cancel()
  clearTimeout(propertySearchSaveTimer)
  document.removeEventListener('keydown', onDocumentKeyDown)
  document.removeEventListener('mouseup', onDocumentMouseUp)
  window.removeEventListener('scroll', onExpandFieldPreviewReposition, true)
  window.removeEventListener('resize', onExpandFieldPreviewReposition)
})

defineExpose({
  hasUnsavedChanges: () => hasUnsavedChanges.value,
  reloadList,
  reloadScheduleLabelTemplates,
  discardUnsavedChanges: async () => {
    const nextMap = new Map()
    for (const item of allGridItems.value) {
      const wid = String(item.work_id)
      const baseline = savedBaselineByWorkId.value.get(wid)
      nextMap.set(
        wid,
        cloneRows(baseline ?? padWorkLargeScheduleRows(item.rows || [])),
      )
    }
    rowsByWorkId.value = nextMap
    dirtyWorkIds.value = new Set()
    undoHistory.value = []
    clearExpandedEditor()
  },
})
