<template>
  <div v-if="isOpen" class="modal-overlay" @mousedown.stop @mouseup.stop>
    <div class="modal-content" @click.stop @mousedown.stop @mouseup.stop>
      <div class="modal-header">
        <h3>部屋テンプレート入力</h3>
        <button class="close-btn" @click="handleClose">✕</button>
      </div>
      
      <div class="modal-body">
        <div v-for="i in ROOM_LABEL_COUNT" :key="i" class="label-row">
          <span class="label-number">{{ i - 1 }}:</span>
          <input 
            type="text" 
            class="label-input"
            :class="{ 'label-input--extended': i - 1 >= 10 }"
            v-model="localLabels[i - 1]"
            :placeholder="`ラベル ${i - 1}`"
            @click.stop
            @mousedown.stop
            @mouseup.stop
          />
        </div>
      </div>
      
      <div class="modal-footer">
        <button class="cancel-btn" @click="handleClose">キャンセル</button>
        <button class="save-btn" @click="handleSave">保存</button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue'
import { ROOM_LABEL_COUNT, padRoomLabelSlots } from '../constants/roomLabelSlots.js'

const props = defineProps({
  isOpen: {
    type: Boolean,
    default: false
  },
  labels: {
    type: Array,
    default: () => []
  }
})

const emit = defineEmits(['close', 'save'])

const localLabels = ref(Array(ROOM_LABEL_COUNT).fill(''))

function syncLocalFromProps(newLabels) {
  const padded = padRoomLabelSlots(newLabels)
  localLabels.value = padded.map((l) => l.label || '')
}

watch(() => props.labels, syncLocalFromProps, { immediate: true, deep: true })

function handleClose() {
  emit('close')
}

function handleSave() {
  const labels = localLabels.value.map((label, index) => ({
    sort_order: index,
    label: label || ''
  }))
  emit('save', labels)
}
</script>

<style scoped>
.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
}

.modal-content {
  background: white;
  border-radius: 8px;
  width: 90%;
  max-width: 400px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  border-bottom: 1px solid #e5e7eb;
}

.modal-header h3 {
  margin: 0;
  font-size: 18px;
  color: #1f2937;
}

.close-btn {
  background: none;
  border: none;
  font-size: 20px;
  color: #6b7280;
  cursor: pointer;
  padding: 4px 8px;
}

.close-btn:hover {
  color: #374151;
}

.modal-body {
  padding: 16px 20px;
  overflow-y: auto;
  flex: 1;
}

.label-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.label-number {
  width: 28px;
  font-size: 14px;
  color: #6b7280;
  text-align: right;
  flex-shrink: 0;
}

.label-input {
  flex: 1;
  padding: 8px 12px;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  font-size: 14px;
}

.label-input:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.label-input--extended {
  background: #eff6ff;
}

.label-input--extended:focus {
  background: #eff6ff;
}

@media (max-width: 900px) {
  .label-input {
    font-size: 16px;
  }
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding: 16px 20px;
  border-top: 1px solid #e5e7eb;
}

.cancel-btn {
  padding: 8px 16px;
  background: #f3f4f6;
  color: #374151;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
}

.cancel-btn:hover {
  background: #e5e7eb;
}

.save-btn {
  padding: 8px 16px;
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
}

.save-btn:hover {
  background: #2563eb;
}
</style>
