<template>
  <div v-if="isOpen" class="modal-overlay" @click.self="handleCancel">
    <div class="modal-box" @click.stop>
      <div class="modal-header">
        <h3>{{ title }}</h3>
        <button type="button" class="close-btn" @click="handleCancel">✕</button>
      </div>
      <div class="modal-body">
        <div class="modal-actions">
          <button type="button" class="link-btn" @click="selectAll">すべて選択</button>
          <button type="button" class="link-btn" @click="clearAll">すべて解除</button>
        </div>
        <div class="option-list">
          <label
            v-for="option in options"
            :key="String(option.value)"
            class="option-item"
          >
            <input
              type="checkbox"
              :checked="draftSelected.has(option.value)"
              @change="toggle(option.value)"
            />
            <span>{{ option.label }}</span>
          </label>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="cancel-btn" @click="handleCancel">キャンセル</button>
        <button type="button" class="apply-btn" @click="handleApply">適用</button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue'

const props = defineProps({
  isOpen: { type: Boolean, default: false },
  title: { type: String, default: '選択' },
  options: { type: Array, default: () => [] },
  selectedValues: { type: Array, default: () => [] },
})

const emit = defineEmits(['close', 'apply'])

const draftSelected = ref(new Set())

watch(
  () => [props.isOpen, props.selectedValues],
  () => {
    if (!props.isOpen) return
    draftSelected.value = new Set(props.selectedValues ?? [])
  },
  { immediate: true, deep: true },
)

function toggle(value) {
  const next = new Set(draftSelected.value)
  if (next.has(value)) next.delete(value)
  else next.add(value)
  draftSelected.value = next
}

function selectAll() {
  draftSelected.value = new Set(props.options.map((option) => option.value))
}

function clearAll() {
  draftSelected.value = new Set()
}

function handleCancel() {
  emit('close')
}

function handleApply() {
  emit('apply', Array.from(draftSelected.value))
  emit('close')
}
</script>

<style scoped>
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 5000;
}

.modal-box {
  width: min(546px, calc(100vw - 2rem));
  max-height: min(72vh, 728px);
  background: #fff;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.975rem 1.3rem;
  border-bottom: 1px solid #e5e7eb;
}

.modal-header h3 {
  margin: 0;
  font-size: 1.3rem;
}

.close-btn {
  border: none;
  background: transparent;
  cursor: pointer;
  color: #6b7280;
  font-size: 1.3rem;
  line-height: 1;
}

.modal-body {
  padding: 0.975rem 1.3rem;
  overflow: auto;
}

.modal-actions {
  display: flex;
  gap: 0.975rem;
  margin-bottom: 0.975rem;
}

.link-btn {
  border: none;
  background: transparent;
  color: #2563eb;
  cursor: pointer;
  font-size: 1.0625rem;
  padding: 0;
}

.option-list {
  display: flex;
  flex-direction: column;
  gap: 0.4875rem;
}

.option-item {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  font-size: 1.1375rem;
}

.option-item input[type='checkbox'] {
  width: 1.1375rem;
  height: 1.1375rem;
  flex-shrink: 0;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.65rem;
  padding: 0.975rem 1.3rem;
  border-top: 1px solid #e5e7eb;
}

.cancel-btn,
.apply-btn {
  padding: 0.4875rem 1.1375rem;
  border-radius: 6px;
  cursor: pointer;
  font-size: 1.1375rem;
}

.cancel-btn {
  border: 1px solid #d1d5db;
  background: #fff;
}

.apply-btn {
  border: 1px solid #3b82f6;
  background: #3b82f6;
  color: #fff;
}
</style>
