export const SNIPPET_MAX_LINES = 10

/** 改行コードを \n に統一 */
export function unifySnippetLineBreaks(text) {
  return String(text ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n')
}

/** 先頭の改行文字数（trim しない） */
export function countLeadingNewlines(text) {
  const unified = unifySnippetLineBreaks(text)
  let count = 0
  while (count < unified.length && unified[count] === '\n') {
    count += 1
  }
  return count
}

/** 先頭改行を除いた本文 */
export function getSnippetBodyAfterLeadingNewlines(label) {
  return unifySnippetLineBreaks(label).replace(/^\n+/, '')
}

/** 2行以上か（改行コード統一のみ、trim しない） */
export function isSnippetMultiline(label) {
  return unifySnippetLineBreaks(label).includes('\n')
}

/** 表示・確認用: 1行目（改行コード統一のみ） */
export function getSnippetFirstLine(label) {
  const unified = unifySnippetLineBreaks(label)
  const idx = unified.indexOf('\n')
  return idx === -1 ? unified : unified.slice(0, idx)
}

/**
 * 保存用正規化
 * - 先頭改行は維持 / 途中改行は維持 / 末尾改行は最大1つ
 * - 非空白文字が無ければ null（保存不可）
 * - 11行以上は null
 * @returns {{ text: string, newline_after: boolean } | null}
 */
export function normalizeSnippetForSave(raw) {
  let text = unifySnippetLineBreaks(raw)
  if (text.includes('\n')) {
    text = text.replace(/\n+$/, '\n')
  }

  if (!text || !/\S/.test(text)) return null

  const lines = text.split('\n')
  if (lines.length > SNIPPET_MAX_LINES) return null

  const bodyLines = getSnippetBodyAfterLeadingNewlines(text).split('\n')

  return {
    text,
    newline_after: bodyLines.length >= 2,
  }
}

/** メニュー表示用（先頭改行は ↲、途中改行あり時は1行目のみ） */
export function formatSnippetMenuLabel(label, newlineAfter, maxLen = 20) {
  const unified = unifySnippetLineBreaks(label)
  const leading = countLeadingNewlines(unified)
  const body = unified.slice(leading)
  const displayBody = newlineAfter ? getSnippetFirstLine(body) : body
  const prefix = leading > 0 ? '↲ '.repeat(leading) : ''
  const full = `${prefix}${displayBody}`

  if (full.length <= maxLen) return full

  const budget = maxLen - prefix.length - 3
  if (budget <= 0) {
    return `${prefix.slice(0, Math.max(0, maxLen - 3))}...`
  }
  return `${prefix}${displayBody.slice(0, budget)}...`
}
