/**
 * マニュアル検索用 multilingual-e5-small ベクトル（384 次元）
 * クエリ側のみ。索引は embed_manual_entries.py（passage:）で生成。
 */

export const TEXT_EMBEDDING_MODEL_VERSION = 'multilingual-e5-small@v1'

const MODEL_ID = 'Xenova/multilingual-e5-small'
const TRANSFORMERS_PKG_VERSION = '2.17.2'
const EMBEDDING_DIM = 384
const QUERY_PREFIX = 'query: '

/** @type {Promise<import('@xenova/transformers')> | null} */
let transformersModPromise = null

/** @type {Promise<unknown> | null} */
let extractorPromise = null

function loadTransformersModule() {
  if (!transformersModPromise) {
    transformersModPromise = import('@xenova/transformers').then((mod) => {
      const { env } = mod
      env.allowLocalModels = false
      env.allowRemoteModels = true
      if (env.backends?.onnx?.wasm) {
        env.backends.onnx.wasm.wasmPaths = `https://cdn.jsdelivr.net/npm/@xenova/transformers@${TRANSFORMERS_PKG_VERSION}/dist/`
        env.backends.onnx.wasm.numThreads = 1
      }
      return mod
    })
  }
  return transformersModPromise
}

function normalizeSpaces(text) {
  return String(text ?? '').replace(/[\u3000\s]+/g, ' ').trim()
}

export function buildManualQueryInput(text) {
  const normalized = normalizeSpaces(text)
  if (!normalized) return ''
  return `${QUERY_PREFIX}${normalized}`
}

function normalizeL2(arr) {
  let sum = 0
  for (let i = 0; i < arr.length; i++) sum += arr[i] * arr[i]
  const n = Math.sqrt(sum) || 1
  for (let i = 0; i < arr.length; i++) arr[i] /= n
  return arr
}

function toEmbedding384(arr) {
  if (arr.length === EMBEDDING_DIM) {
    return normalizeL2(arr)
  }
  if (arr.length % EMBEDDING_DIM !== 0) {
    throw new Error(`unexpected embedding length ${arr.length}, expected ${EMBEDDING_DIM} or a multiple`)
  }
  const nTok = arr.length / EMBEDDING_DIM
  const out = new Float32Array(EMBEDDING_DIM)
  for (let t = 0; t < nTok; t++) {
    const o = t * EMBEDDING_DIM
    for (let j = 0; j < EMBEDDING_DIM; j++) out[j] += arr[o + j]
  }
  for (let j = 0; j < EMBEDDING_DIM; j++) out[j] /= nTok
  return normalizeL2(out)
}

async function getExtractor() {
  if (!extractorPromise) {
    extractorPromise = (async () => {
      const { pipeline } = await loadTransformersModule()
      const extractor = await pipeline('feature-extraction', MODEL_ID, { revision: 'main' })
      extractor.tokenizer.prepare_model_inputs = (modelInputs) => {
        const tokenTypeIds = modelInputs.attention_mask.clone()
        tokenTypeIds.data.fill(0n)
        return { ...modelInputs, token_type_ids: tokenTypeIds }
      }
      return extractor
    })()
  }
  return extractorPromise
}

/**
 * 検索クエリ文字列から e5 query embedding を取得（Float32Array, 384）
 * @param {string} text
 * @returns {Promise<Float32Array>}
 */
export async function extractManualQueryEmbeddingFloat32(text) {
  const input = buildManualQueryInput(text)
  if (!input) {
    throw new Error('query text is empty')
  }
  const extractor = await getExtractor()
  const output = await extractor(input, { pooling: 'mean', normalize: true })
  const data = output?.data
  if (!data) {
    throw new Error('embedding output is empty')
  }
  const arr = data instanceof Float32Array ? data : new Float32Array(data)
  return toEmbedding384(arr)
}

export function getTextEmbeddingModelVersion() {
  return TEXT_EMBEDDING_MODEL_VERSION
}

export function getTextEmbeddingDim() {
  return EMBEDDING_DIM
}

/**
 * プライスリスト description + note を query 入力に整形
 * @param {{ description?: string, note?: string } | null | undefined} priceListItem
 */
export function formatPriceListTextForManualSearch(priceListItem) {
  const description = normalizeSpaces(priceListItem?.description ?? '')
  const note = normalizeSpaces(priceListItem?.note ?? '')
  if (description && note) return `${description}-${note}`
  return description || note
}

/** マニュアルタブ表示時に embedding モデルをバックグラウンド preload */
export function preloadManualQueryEmbeddingModel() {
  return getExtractor().then(() => undefined).catch(() => undefined)
}
