<template>
  <div class="mobile-room-bucket-panel">
    <div class="mrb-body">
      <div class="mrb-main-col">
        <div class="mrb-header mrb-room-header">
          <span class="mrb-room-label">{{ roomLabel }}</span>
        </div>
        <div ref="scrollRef" class="mrb-matrix-scroll">
        <section
          v-for="col in enabledColumns"
          :key="col.colKey"
          class="mrb-special-block"
        >
          <div class="mrb-special-head">
            {{ col.headerLabel || col.colKey }}
          </div>
          <div
            v-for="rowIndex in rowIndicesForColumn(col)"
            :key="`${col.colKey}-${rowIndex}`"
            class="mrb-cell"
            :data-mrb-cell="`${roomOrder}:${col.colKey}:${rowIndex}`"
            :class="{
              'mrb-cell--selected': isCellSelected(roomOrder, col.colKey, rowIndex),
              'mrb-cell--empty': isEmptyCell(cellAt(col, rowIndex)),
              'mrb-cell--flash': isCellFlashOrange(roomOrder, col.colKey, rowIndex),
              'mrb-cell--flash-red': isCellFlashRed(roomOrder, col.colKey, rowIndex),
              'mrb-cell--flash-blue': isCellFlashBlue(roomOrder, col.colKey, rowIndex),
              'mrb-cell--drop-target': isDropTarget(col.colKey, rowIndex),
            }"
            @click="onCellClick(roomOrder, col.colKey, rowIndex)"
            @dragover.prevent="onCellDragOver($event, col.colKey, rowIndex)"
            @dragleave="onCellDragLeave($event, col.colKey, rowIndex)"
            @drop.prevent="onCellDrop($event, col.colKey, rowIndex)"
          >
            <div class="mrb-cell-inner">
              <button
                type="button"
                class="mrb-room-btn pw-room-btn"
                title="部屋を挿入"
                :disabled="!canUseRoomLabelButton(cellAt(col, rowIndex))"
                @click.stop="toggleRoomLabelMenu($event, col.colKey, rowIndex)"
              >
                <svg viewBox="0 0 24 24" width="14" height="14" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                  <path d="M3 10.5L12 3l9 7.5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  <path d="M5 9.8V21h14V9.8" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  <path d="M9.5 21v-6h5v6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
              </button>
              <div class="mrb-cell-stack">
                <div
                  class="mrb-cell-original"
                  :class="{
                    'mrb-cell-original--draggable': canDragCell(cellAt(col, rowIndex)),
                    'mrb-cell-original--dragging': isDraggingCell(col.colKey, rowIndex),
                    'mrb-cell-original--muted-bg': isOriginalMutedBg(cellAt(col, rowIndex)),
                  }"
                  :title="cellOriginalTitle(cellAt(col, rowIndex))"
                  :draggable="canDragCell(cellAt(col, rowIndex))"
                  @click.stop="onCellClick(roomOrder, col.colKey, rowIndex)"
                  @selectstart.prevent
                  @dragstart="onCellOriginalDragStart($event, col.colKey, rowIndex, cellAt(col, rowIndex))"
                  @dragend="onCellOriginalDragEnd"
                >
                  <span class="mrb-cell-original-text">{{
                    cellAt(col, rowIndex)?.templateInstruction || ''
                  }}</span>
                </div>
                <input
                  type="text"
                  class="mrb-content-input"
                  :class="{ 'mrb-content-input--locked': !canUseRoomLabelButton(cellAt(col, rowIndex)) }"
                  :value="cellAt(col, rowIndex)?.content || ''"
                  :readonly="!canUseRoomLabelButton(cellAt(col, rowIndex))"
                  placeholder="内容"
                  @click.stop="onCellClick(roomOrder, col.colKey, rowIndex)"
                  @focus="onCellClick(roomOrder, col.colKey, rowIndex)"
                  @change="onContentChange(col.colKey, rowIndex, $event.target.value)"
                />
              </div>
              <button
                type="button"
                class="mrb-clear-btn"
                title="セルをクリア"
                :disabled="cellAt(col, rowIndex)?.isDummy"
                @click.stop="onClearCell(col.colKey, rowIndex)"
              >
                ✕
              </button>
            </div>
          </div>
        </section>
        </div>
      </div>
      <div class="mrb-original-col">
        <div class="mrb-header mrb-original-header">原本</div>
        <OriginalInstructionPanel
          hide-header
          class="mrb-original-panel"
          :items="originalItems"
          @apply="(item) => emit('apply-original', item)"
        />
      </div>
    </div>

    <Teleport to="body">
      <div
        v-if="roomLabelMenu.open"
        ref="roomLabelMenuRef"
        class="pw-room-menu pw-room-menu--teleport"
        :style="roomLabelMenuStyle"
        @mousedown.stop
      >
        <div class="pw-room-menu-scroll">
          <button
            v-for="label in roomLabelMenuOptions"
            :key="`mrb-menu-${label}`"
            type="button"
            class="pw-room-menu-item"
            @click="applyRoomLabelToCell(label)"
          >
            {{ label }}
          </button>
        </div>
        <button type="button" class="pw-room-menu-item pw-room-menu-close" @click="closeRoomLabelMenu">
          閉じる
        </button>
      </div>
    </Teleport>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import OriginalInstructionPanel from './OriginalInstructionPanel.vue'
import { ROOM_MATRIX_ROW_COUNT } from '../utils/roomMatrixMapping.js'
import { roomLabelInsertMenuTexts } from '../constants/roomLabelSlots.js'
import { positionTeleportMenuFromAnchor } from '../utils/teleportMenuPosition.js'
import {
  parseRoomMatrixCellMovePayload,
  parseRoomMatrixDropPayload,
  readRoomMatrixDragRaw,
  writeRoomMatrixDragData,
} from '../utils/roomMatrixDragData.js'

const props = defineProps({
  photoPanel: { type: Object, default: null },
  roomOrder: { type: Number, required: true },
  roomLabel: { type: String, default: '' },
  roomLabels: { type: Array, default: () => [] },
  originalItems: { type: Array, default: () => [] },
  selectedCell: { type: Object, default: null },
  draftTick: { type: Number, default: 0 },
})

const emit = defineEmits(['draft-change', 'cell-select', 'apply-original'])

const scrollRef = ref(null)
const roomLabelMenuRef = ref(null)
const matrixFlashTick = ref(0)

const roomLabelMenu = reactive({
  open: false,
  top: 0,
  left: 0,
  colKey: '',
  rowIndex: null,
})

const matrixDragState = reactive({
  from: null,
  dropTargetKey: '',
})

const roomLabelMenuStyle = computed(() => ({
  top: `${roomLabelMenu.top}px`,
  left: `${roomLabelMenu.left}px`,
}))

const roomLabelMenuOptions = computed(() => {
  void props.draftTick
  return roomLabelInsertMenuTexts(props.roomLabels)
})

const matrixView = computed(() => {
  void props.draftTick
  return props.photoPanel?.buildRoomMatrixViewForRoom?.(props.roomOrder) || { columns: [] }
})

const enabledColumns = computed(() =>
  (matrixView.value.columns || []).filter((col) => col.enabled)
)

function cellAt(col, rowIndex) {
  return col.cells?.[rowIndex - 1] || null
}

function isEmptyCell(cell) {
  if (!cell || cell.isDummy) return true
  return !String(cell.externalCode || '').trim() && !String(cell.content || '').trim()
}

function isOriginalMutedBg(cell) {
  const code = String(cell?.externalCode || '').trim()
  if (!code) return false
  const fn = props.photoPanel?.isOriginalContractorMutedForCode
  return typeof fn === 'function' ? Boolean(fn(code)) : false
}

function cellOriginalTitle(cell) {
  return String(cell?.templateInstruction || '').trim()
}

/** 列ごと: 占有行 + 1（最低1、最大 ROOM_MATRIX_ROW_COUNT） */
function rowIndicesForColumn(col) {
  let maxRow = 0
  for (let i = 0; i < ROOM_MATRIX_ROW_COUNT; i++) {
    const cell = col.cells?.[i]
    if (!cell || cell.isDummy) continue
    if (String(cell.externalCode || '').trim() || String(cell.content || '').trim()) {
      maxRow = i + 1
    }
  }
  const count = Math.min(Math.max(maxRow + 1, 1), ROOM_MATRIX_ROW_COUNT)
  return Array.from({ length: count }, (_, i) => i + 1)
}

function isCellSelected(roomOrder, colKey, rowIndex) {
  const sel = props.selectedCell
  if (!sel) return false
  return (
    Number(sel.roomOrder) === Number(roomOrder) &&
    String(sel.colKey) === String(colKey) &&
    Number(sel.rowIndex) === Number(rowIndex)
  )
}

function matrixFlashState() {
  void matrixFlashTick.value
  return props.photoPanel?.getRoomMatrixFlash?.() || null
}

function isCellFlashMatch(roomOrder, colKey, rowIndex, type) {
  const flash = matrixFlashState()
  if (!flash || flash.type !== type) return false
  if (Number(flash.roomOrder) !== Number(roomOrder)) return false
  if (String(flash.colKey) !== String(colKey)) return false
  if (flash.rowIndex != null && Number(flash.rowIndex) !== Number(rowIndex)) return false
  return true
}

function isCellFlashOrange(roomOrder, colKey, rowIndex) {
  return isCellFlashMatch(roomOrder, colKey, rowIndex, 'orange')
}

function isCellFlashRed(roomOrder, colKey, rowIndex) {
  return isCellFlashMatch(roomOrder, colKey, rowIndex, 'red')
}

function isCellFlashBlue(roomOrder, colKey, rowIndex) {
  return isCellFlashMatch(roomOrder, colKey, rowIndex, 'blue')
}

function canUseRoomLabelButton(cell) {
  if (!cell) return false
  return Boolean(String(cell.externalCode || '').trim())
}

function canDragCell(cell) {
  if (!cell || cell.isDummy) return false
  return Boolean(String(cell.externalCode || '').trim()) || Boolean(String(cell.content || '').trim())
}

function cellKey(colKey, rowIndex) {
  return `${props.roomOrder}:${colKey}:${rowIndex}`
}

function isDraggingCell(colKey, rowIndex) {
  const from = matrixDragState.from
  if (!from) return false
  return cellKey(from.colKey, from.rowIndex) === cellKey(colKey, rowIndex)
}

function isDropTarget(colKey, rowIndex) {
  return matrixDragState.dropTargetKey === cellKey(colKey, rowIndex)
}

function clearTextSelection() {
  if (typeof window !== 'undefined' && window.getSelection) {
    const sel = window.getSelection()
    if (sel) sel.removeAllRanges()
  }
}

function onCellOriginalDragStart(event, colKey, rowIndex, cell) {
  if (!canDragCell(cell)) {
    event.preventDefault()
    return
  }
  matrixDragState.from = { roomOrder: props.roomOrder, colKey, rowIndex }
  event.dataTransfer.effectAllowed = 'move'
  writeRoomMatrixDragData(event.dataTransfer, {
    type: 'room-matrix-cell',
    roomOrder: props.roomOrder,
    colKey,
    rowIndex,
    external_code: cell.externalCode,
  })
}

function onCellOriginalDragEnd() {
  matrixDragState.from = null
  matrixDragState.dropTargetKey = ''
  clearTextSelection()
}

function onCellDragOver(event, colKey, rowIndex) {
  if (matrixDragState.from) {
    event.dataTransfer.dropEffect = 'move'
  } else {
    event.dataTransfer.dropEffect = 'copy'
  }
  matrixDragState.dropTargetKey = cellKey(colKey, rowIndex)
}

function onCellDragLeave(event, colKey, rowIndex) {
  const related = event.relatedTarget
  if (related && event.currentTarget?.contains(related)) return
  if (matrixDragState.dropTargetKey === cellKey(colKey, rowIndex)) {
    matrixDragState.dropTargetKey = ''
  }
}

async function onCellDrop(event, colKey, rowIndex) {
  const roomOrder = props.roomOrder
  matrixDragState.dropTargetKey = ''
  const raw = readRoomMatrixDragRaw(event.dataTransfer)
  let matrixMove = parseRoomMatrixCellMovePayload(raw)
  if (!matrixMove && matrixDragState.from) {
    matrixMove = { ...matrixDragState.from }
  }
  if (matrixMove) {
    onCellClick(roomOrder, colKey, rowIndex)
    props.photoPanel?.moveRoomMatrixCell?.({
      from: matrixMove,
      to: { roomOrder, colKey, rowIndex },
    })
    matrixDragState.from = null
    emit('draft-change')
    matrixFlashTick.value++
    return
  }

  const payload = parseRoomMatrixDropPayload(raw)
  if (!payload) return
  onCellClick(roomOrder, colKey, rowIndex)
  await props.photoPanel?.applyDropToRoomMatrixTail?.(payload, { roomOrder, colKey })
  emit('draft-change')
  matrixFlashTick.value++
  clearTextSelection()
}

function scrollMatrixCellIntoView(roomOrder, colKey, rowIndex, options = {}) {
  const bottomGutter = Number(options.bottomGutterPx ?? 140)
  const topGutter = Number(options.topGutterPx ?? 36)
  const showRowBelow = options.showRowBelow !== false

  nextTick(() => {
    nextTick(() => {
      requestAnimationFrame(() => {
        const scrollEl = scrollRef.value
        const rowNum = Number(rowIndex)
        if (!scrollEl || !Number.isFinite(rowNum) || rowNum < 1) return

        const rowsToShow = [rowNum]
        if (showRowBelow) rowsToShow.push(rowNum + 1)
        if (options.ensureRowVisible != null) {
          rowsToShow.push(Number(options.ensureRowVisible))
        }

        const uniqueRows = [...new Set(rowsToShow.filter((r) => r >= 1 && r <= ROOM_MATRIX_ROW_COUNT))]
        let minTop = Infinity
        let maxBottom = -Infinity

        for (const r of uniqueRows) {
          const el = scrollEl.querySelector(`[data-mrb-cell="${roomOrder}:${colKey}:${r}"]`)
          if (!el || typeof el.getBoundingClientRect !== 'function') continue
          const rect = el.getBoundingClientRect()
          minTop = Math.min(minTop, rect.top)
          maxBottom = Math.max(maxBottom, rect.bottom)
        }
        if (!Number.isFinite(minTop)) return

        const pr = scrollEl.getBoundingClientRect()
        let delta = 0
        if (maxBottom > pr.bottom - bottomGutter) {
          delta = maxBottom - (pr.bottom - bottomGutter)
        } else if (minTop < pr.top + topGutter) {
          delta = -((pr.top + topGutter) - minTop)
        }
        if (delta !== 0) scrollEl.scrollTop += delta
      })
    })
  })
}

function onCellClick(roomOrder, colKey, rowIndex) {
  props.photoPanel?.selectRoomMatrixCell?.({ roomOrder, colKey, rowIndex })
  emit('cell-select', { roomOrder, colKey, rowIndex })
}

function onContentChange(colKey, rowIndex, content) {
  const ok = props.photoPanel?.updateRoomMatrixCellContent?.({
    roomOrder: props.roomOrder,
    colKey,
    rowIndex,
    content,
  })
  if (ok) emit('draft-change')
}

function onClearCell(colKey, rowIndex) {
  props.photoPanel?.clearRoomMatrixCell?.({
    roomOrder: props.roomOrder,
    colKey,
    rowIndex,
  })
  emit('draft-change')
}

async function positionRoomLabelMenu(event, rect) {
  const anchorLeft = rect ? Math.round(rect.left + 2) : Math.round(event.clientX)
  const anchorBottomY = rect ? Math.round(rect.bottom - 2) : Math.round(event.clientY)
  roomLabelMenu.top = anchorBottomY
  roomLabelMenu.left = anchorLeft
  await nextTick()
  const pos = positionTeleportMenuFromAnchor(roomLabelMenuRef.value, anchorLeft, anchorBottomY)
  if (pos) {
    roomLabelMenu.top = pos.top
    roomLabelMenu.left = pos.left
  }
}

async function toggleRoomLabelMenu(event, colKey, rowIndex) {
  const col = enabledColumns.value.find((c) => c.colKey === colKey)
  const cell = col ? cellAt(col, rowIndex) : null
  if (!canUseRoomLabelButton(cell)) return
  const sameCell =
    roomLabelMenu.open &&
    String(roomLabelMenu.colKey) === String(colKey) &&
    Number(roomLabelMenu.rowIndex) === Number(rowIndex)
  if (sameCell) {
    closeRoomLabelMenu()
    return
  }
  onCellClick(props.roomOrder, colKey, rowIndex)
  const rect = event.currentTarget?.getBoundingClientRect?.()
  roomLabelMenu.open = true
  roomLabelMenu.colKey = colKey
  roomLabelMenu.rowIndex = rowIndex
  await positionRoomLabelMenu(event, rect)
}

function closeRoomLabelMenu() {
  roomLabelMenu.open = false
}

function applyRoomLabelToCell(label) {
  const text = String(label ?? '').trim()
  if (!text) return
  const { colKey, rowIndex } = roomLabelMenu
  if (!colKey || rowIndex == null) return
  props.photoPanel?.updateRoomMatrixCellContent?.({
    roomOrder: props.roomOrder,
    colKey,
    rowIndex,
    content: text,
  })
  closeRoomLabelMenu()
  emit('draft-change')
}

function onDocumentPointerDown(event) {
  if (!roomLabelMenu.open) return
  if (event.target?.closest?.('.pw-room-menu') || event.target?.closest?.('.pw-room-btn')) return
  closeRoomLabelMenu()
}

onMounted(() => {
  document.addEventListener('mousedown', onDocumentPointerDown)
})

onBeforeUnmount(() => {
  document.removeEventListener('mousedown', onDocumentPointerDown)
  props.photoPanel?.unregisterRoomMatrixScroll?.()
})

watch(
  () => props.draftTick,
  () => {
    matrixFlashTick.value++
  }
)

watch(
  () => props.photoPanel,
  (panel, prev) => {
    prev?.unregisterRoomMatrixScroll?.()
    panel?.registerRoomMatrixScroll?.(scrollMatrixCellIntoView)
  },
  { immediate: true }
)
</script>

<style scoped>
.mobile-room-bucket-panel {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
  background: #fff;
  --mrb-original-flex: 0 0 42%;
  --mrb-original-width: 42%;
  --mrb-original-max-width: 13rem;
  --mrb-original-min-width: 9.5rem;
}
.mrb-header {
  flex-shrink: 0;
  padding: 0.5rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 700;
  color: #475569;
  border-bottom: 1px solid #e5e7eb;
  background: #f1f5f9;
  line-height: 1.3;
}
.mrb-room-header {
  border-right: 1px solid #e5e7eb;
}
.mrb-original-header {
  text-align: left;
}
.mrb-room-label {
  font-size: 0.95rem;
  font-weight: 700;
  color: #1e293b;
  word-break: break-word;
}
.mrb-body {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: row;
  overflow: hidden;
}
.mrb-main-col {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.mrb-original-col {
  flex: var(--mrb-original-flex);
  width: var(--mrb-original-width);
  max-width: var(--mrb-original-max-width);
  min-width: var(--mrb-original-min-width);
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-left: 1px solid #e5e7eb;
}
.mrb-matrix-scroll {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  padding: 0.35rem 0.45rem;
  /* 下部フロートタブに被らないよう、セル半分（≈2rem）の余白 */
  padding-bottom: calc(0.35rem + 2rem);
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}
.mrb-special-block {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.mrb-special-head {
  font-size: 0.88rem;
