  color: #334155;
  padding: 0.35rem 0.45rem;
  background: #f1f5f9;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  line-height: 1.3;
  word-break: break-word;
}
.mrb-cell {
  padding: 0;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  background: #fff;
  overflow: hidden;
}
.mrb-cell--empty {
  background: #fafafa;
}
.mrb-cell--selected {
  outline: 2px solid #60a5fa;
  outline-offset: -2px;
  background: #eff6ff;
}
.mrb-cell--drop-target {
  outline: 2px dashed #60a5fa;
  outline-offset: -2px;
  background: #f0f9ff;
}
.mrb-cell--flash .mrb-cell-original,
.mrb-cell--flash .mrb-content-input {
  animation: mrb-flash-orange 1.2s ease-out;
}
.mrb-cell--flash-blue .mrb-cell-original,
.mrb-cell--flash-blue .mrb-content-input {
  animation: mrb-flash-blue 1.2s ease-out;
}
.mrb-cell--flash-red .mrb-cell-original,
.mrb-cell--flash-red .mrb-content-input {
  animation: mrb-flash-red 1.2s ease-out;
}
@keyframes mrb-flash-orange {
  0% { background-color: rgba(255, 247, 237, 0.96); box-shadow: inset 0 0 0 1px rgba(249, 115, 22, 0.62); }
  100% { background-color: #fff; box-shadow: none; }
}
@keyframes mrb-flash-blue {
  0% { background-color: rgba(239, 246, 255, 0.96); box-shadow: inset 0 0 0 1px rgba(59, 130, 246, 0.62); }
  100% { background-color: #fff; box-shadow: none; }
}
@keyframes mrb-flash-red {
  0% { background-color: rgba(254, 226, 226, 0.96); box-shadow: inset 0 0 0 1px rgba(239, 68, 68, 0.62); }
