  background: #f9fafb;
  border-color: #e5e7eb;
  color: #cbd5e1;
  opacity: 0.55;
  cursor: default;
}
.mrb-cell-original {
  display: flex;
  align-items: center;
  min-height: 1.925rem;
  max-height: 1.925rem;
  font-size: 0.85rem;
  line-height: 1.2;
  overflow: hidden;
  background: #f9fafb;
  border: 1px dashed #e5e7eb;
  border-radius: 4px 4px 0 0;
  padding: 0.15rem 0.25rem;
  box-sizing: border-box;
}
.mrb-cell-original--muted-bg {
  background: var(--original-contractor-muted-bg, #e8eaed);
}
.mrb-cell-original--draggable {
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}
.mrb-cell-original--draggable:active,
.mrb-cell-original--dragging {
