  outline: 2px solid #93c5fd;
  outline-offset: -2px;
}
.mrb-content-input--locked {
  background: #f3f4f6;
  border-color: #e5e7eb;
  color: #9ca3af;
  cursor: default;
  opacity: 0.85;
