/**
 * Teleport メニュー配置。
 * 下方向を優先し、画面下端で切れる場合はアンカー点をメニュー左下にして上方向へ展開。
 */
export function computeTeleportMenuPosition({
  anchorLeft,
  anchorBottomY,
  menuWidth,
  menuHeight,
  margin = 8,
} = {}) {
  const vw = typeof window !== 'undefined' ? window.innerWidth : 0
  const vh = typeof window !== 'undefined' ? window.innerHeight : 0
  const w = Math.max(0, Number(menuWidth) || 0)
  const h = Math.max(0, Number(menuHeight) || 0)
  const m = Number(margin) || 8

  let left = Number(anchorLeft) || 0
  let top = Number(anchorBottomY) || 0

  if (left + w > vw - m) {
    left = Math.max(m, vw - w - m)
  }
  if (left < m) left = m

  const overflowsBottom = top + h > vh - m
  if (overflowsBottom) {
    top = Number(anchorBottomY) - h
    if (top < m) top = m
  }

  return {
    top: Math.round(top),
    left: Math.round(left),
    flipUp: overflowsBottom,
  }
}

/** nextTick 後に menu 要素を測って配置座標を返す */
export function positionTeleportMenuFromAnchor(menuEl, anchorLeft, anchorBottomY, margin = 8) {
  if (!menuEl) return null
  return computeTeleportMenuPosition({
    anchorLeft,
    anchorBottomY,
    menuWidth: menuEl.offsetWidth,
    menuHeight: menuEl.offsetHeight,
    margin,
  })
}
