/** 案件・テンプレのルームラベル枠数（sort_order 0 ～ ROOM_LABEL_COUNT - 1） */
export const ROOM_LABEL_COUNT = 20

/** 写真タブのルーム別サムネ・photo_work_links 保存対象の最大 sort_order */
export const PHOTO_TAB_ROOM_ORDER_MAX = 9

export function isPhotoTabRoomOrder(ord) {
  const n = Number(ord)
  return Number.isFinite(n) && n >= 0 && n <= PHOTO_TAB_ROOM_ORDER_MAX
}

/** 部屋挿入メニュー用 sort_order（0〜9 は部屋枠のため除外、10〜19 を表示） */
export const ROOM_LABEL_INSERT_MENU_ORDER_MIN = 10

export function isRoomLabelInsertMenuOrder(ord) {
  const n = Number(ord)
  return Number.isFinite(n) && n >= ROOM_LABEL_INSERT_MENU_ORDER_MIN && n < ROOM_LABEL_COUNT
}

function roomLabelMenuTexts(labels, orderFilter) {
  return [...(labels || [])]
    .filter((r) => orderFilter(Number(r?.sort_order)))
    .sort((a, b) => (Number(a?.sort_order) || 0) - (Number(b?.sort_order) || 0))
    .map((r) => String(r?.label ?? '').trim())
    .filter((t) => t.length > 0)
}

/** 部屋挿入ドロップダウン用ラベル文字列（sort_order 昇順） */
export function roomLabelInsertMenuTexts(labels) {
  return roomLabelMenuTexts(labels, isRoomLabelInsertMenuOrder)
}

/** pw-room-btn 用: sort_order 0〜19 のラベルをすべて表示 */
export function roomLabelPwMenuTexts(labels) {
  return roomLabelMenuTexts(
    labels,
    (ord) => Number.isFinite(ord) && ord >= 0 && ord < ROOM_LABEL_COUNT
  )
}

/** sort_order ごとに id / label を揃えた ROOM_LABEL_COUNT 件の配列 */
export function padRoomLabelSlots(rows) {
  const byOrder = new Map()
  for (const r of rows || []) {
    const o = Number(r?.sort_order)
    if (!Number.isFinite(o) || o < 0 || o >= ROOM_LABEL_COUNT) continue
    byOrder.set(o, {
      sort_order: o,
      id: r?.id ?? null,
      label: String(r?.label ?? '')
    })
  }
  return Array.from({ length: ROOM_LABEL_COUNT }, (_, i) => ({
    sort_order: i,
    id: byOrder.get(i)?.id ?? null,
    label: byOrder.get(i)?.label ?? ''
  }))
}

export function emptyRoomLabelSlots() {
  return padRoomLabelSlots([])
}

/** 部屋タブ: ルームラベルが DB 保存済みかつ当該 sort_order の label が空 */
export function isRoomLabelSavedButBlank(roomOrder, labels, { persisted = false } = {}) {
  const ord = Number(roomOrder)
  if (!persisted || !Number.isFinite(ord) || !isPhotoTabRoomOrder(ord)) return false
  const hit = (labels || []).find((r) => Number(r?.sort_order) === ord)
  if (!hit) return false
  return !String(hit?.label ?? '').trim()
}
