<template>
  <div class="schedule-label-template-editor">
    <div class="editor-header">
      <div class="editor-header-left">
        <button
          class="refresh-btn"
          @click="refreshTemplates"
          :disabled="refreshing"
          title="サーバーから最新のスケジュールテンプレを取得してIndexedDBを更新"
        >
          {{ refreshing ? '反映中' : '反映' }}
        </button>
        <label class="mc-select-label">
          MC
          <select
            v-model="selectedMcId"
            class="mc-select"
            :disabled="loading || refreshing || mcs.length === 0"
            @change="loadTemplatesForSelectedMc"
          >
            <option v-for="mc in mcs" :key="mc.id" :value="String(mc.id)">
              {{ mc.label }}
            </option>
          </select>
        </label>
        <h3>スケジュールテンプレ</h3>
      </div>
    </div>

    <div v-if="loading" class="loading-state">
      <span>読み込み中</span>
    </div>

    <div v-else-if="error" class="error-state">
      <span>{{ error }}</span>
      <button type="button" class="retry-btn" @click="loadTemplates">再読み込み</button>
    </div>

    <div v-else class="template-list">
      <div
        v-for="(item, index) in items"
        :key="item.id"
        class="template-item"
        :class="{
          'is-dragging': draggingId === item.id,
          'drag-over': dragOverId === item.id,
        }"
        @dragover.prevent="handleDragOver($event, item)"
        @dragleave="handleDragLeave($event, item)"
        @drop.prevent="handleDrop($event, item)"
      >
        <div
          class="template-drag-handle"
          draggable="true"
          title="ドラッグして並べ替え"
          @dragstart.stop="handleDragStart($event, item)"
          @dragend.stop="handleDragEnd"
        >
          <span class="drag-icon">≡</span>
        </div>

        <div
          class="template-sort-order"
          :class="{ 'template-sort-order--overflow': index >= 14 }"
          title="sort_order"
        >
          {{ index }}
        </div>

        <input
          type="text"
          class="template-category-input"
          :value="item.category ?? ''"
          placeholder="カテゴリー"
          @blur="handleCategoryChange(item, $event)"
          @keydown.enter="$event.target.blur()"
        />

        <div class="template-column-group">
          <div
            class="template-column-label"
            :class="{ 'template-column-label--hidden': index !== 0 }"
            :aria-hidden="index !== 0"
          >
            <span>スケジュール表</span>
            <span>INDEX番号</span>
          </div>
          <select
            class="template-column-select"
            :value="columnSelectValue(item.schedule_column_index)"
            @change="handleColumnIndexChange(item, $event)"
          >
            <option value="">-</option>
            <option
              v-for="col in columnOptions"
              :key="col"
              :value="String(col)"
            >
              {{ col }}
            </option>
          </select>
        </div>

        <button
          type="button"
          class="delete-btn"
          title="削除"
          @click="deleteItem(item)"
        >
          ✕
        </button>
      </div>

      <div v-if="items.length === 0" class="empty-state">
        <p>スケジュールテンプレがありません</p>
      </div>

      <div class="template-item add-new">
        <div class="template-drag-handle placeholder">
          <span class="drag-icon">≡</span>
        </div>
        <div class="template-sort-order placeholder">-</div>
        <input
          v-model="newCategory"
          type="text"
          class="template-category-input"
          placeholder="カテゴリーを入力..."
          @keydown.enter="addNewItem"
        />
        <div class="template-column-group">
          <div class="template-column-label template-column-label--hidden" aria-hidden="true">
            <span>スケジュール表</span>
            <span>INDEX番号</span>
          </div>
          <select
            v-model="newColumnIndex"
            class="template-column-select"
          >
            <option value="">-</option>
            <option
              v-for="col in columnOptions"
              :key="`new-${col}`"
              :value="String(col)"
            >
              {{ col }}
            </option>
          </select>
        </div>
        <button
          type="button"
          class="add-btn"
          title="追加"
          @click="addNewItem"
        >
          ＋
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { supabaseService } from '../services/supabase'
import { indexedDBService } from '../utils/indexedDB'
import { useDialog } from '../composables/useDialog'
import { WORK_LARGE_SCHEDULE_ORDER_MAX } from '../constants/workLargeSchedule.js'

const emit = defineEmits(['refresh'])

const dialog = useDialog()

const items = ref([])
const mcs = ref([])
const selectedMcId = ref('')
const loading = ref(true)
const error = ref(null)
const refreshing = ref(false)
const newCategory = ref('')
const newColumnIndex = ref('')
const draggingId = ref(null)
const dragOverId = ref(null)

const columnOptions = Array.from(
  { length: WORK_LARGE_SCHEDULE_ORDER_MAX + 1 },
  (_, i) => i,
)

function columnSelectValue(value) {
  if (value == null || value === '') return ''
  return String(value)
}

function parseColumnIndexFromSelect(raw) {
  if (raw == null || raw === '') return null
  const n = Number(raw)
  return Number.isInteger(n) ? n : null
}

function isDuplicateColumnIndex(columnIndex, excludeId = null) {
  if (columnIndex == null) return false
  return items.value.some(
    (row) =>
      row.id !== excludeId &&
      row.schedule_column_index != null &&
      Number(row.schedule_column_index) === Number(columnIndex),
  )
}

async function syncCache() {
  if (!selectedMcId.value) return
  await supabaseService.mergeScheduleLabelTemplatesForMc(Number(selectedMcId.value), items.value)
}

async function loadMcOptions() {
  const rows = await indexedDBService.getMasterData('master_mc')
  mcs.value = (rows || []).filter((row) => row.is_active !== false)
  if (!selectedMcId.value && mcs.value.length > 0) {
    selectedMcId.value = String(mcs.value[0].id)
  }
}

onMounted(async () => {
  await loadMcOptions()
  await loadTemplates()
})

async function loadTemplatesForSelectedMc() {
  await loadTemplates()
}

async function loadTemplates() {
  loading.value = true
  error.value = null
  try {
    if (!selectedMcId.value) {
      items.value = []
      return
    }
    const cached = await supabaseService.getScheduleLabelTemplates()
    const filtered = cached.filter((row) => Number(row.mc_id) === Number(selectedMcId.value))
    if (filtered.length > 0) {
      items.value = filtered
      return
    }
    items.value = await supabaseService.listScheduleLabelTemplates(Number(selectedMcId.value))
    await syncCache()
  } catch (err) {
    console.error('Failed to load schedule label templates:', err)
    error.value = 'スケジュールテンプレの読み込みに失敗しました'
  } finally {
    loading.value = false
  }
}

async function refreshTemplates() {
  refreshing.value = true
  try {
    const all = await supabaseService.refreshScheduleLabelTemplates()
    items.value = (all || []).filter((row) => Number(row.mc_id) === Number(selectedMcId.value))
    emit('refresh')
  } catch (err) {
    console.error('Failed to refresh schedule label templates:', err)
    await dialog.alert(`反映に失敗しました: ${err.message}`, { title: 'エラー' })
  } finally {
    refreshing.value = false
  }
}

async function handleCategoryChange(item, event) {
  const nextCategory = event.target.value.trim()
  const prevCategory = item.category ?? ''
  if (nextCategory === prevCategory) return

  item.category = nextCategory || null
  try {
    const updated = await supabaseService.updateScheduleLabelTemplate(item.id, {
      category: item.category,
    })
    Object.assign(item, updated)
    await syncCache()
    emit('refresh')
  } catch (err) {
    console.error('Failed to update category:', err)
    item.category = prevCategory || null
    event.target.value = prevCategory
    await dialog.alert(err.message || '更新に失敗しました', { title: 'エラー' })
  }
}

async function handleColumnIndexChange(item, event) {
  const nextIndex = parseColumnIndexFromSelect(event.target.value)
  const prevIndex = item.schedule_column_index ?? null
  if (nextIndex === prevIndex) return

  if (isDuplicateColumnIndex(nextIndex, item.id)) {
    event.target.value = columnSelectValue(prevIndex)
    await dialog.alert('同じスケジュール列は既に使用されています', { title: 'エラー' })
    return
  }

  item.schedule_column_index = nextIndex
  try {
    const updated = await supabaseService.updateScheduleLabelTemplate(item.id, {
      schedule_column_index: nextIndex,
    })
    Object.assign(item, updated)
    await syncCache()
    emit('refresh')
  } catch (err) {
    console.error('Failed to update schedule_column_index:', err)
    item.schedule_column_index = prevIndex
    event.target.value = columnSelectValue(prevIndex)
    await dialog.alert(err.message || '更新に失敗しました', { title: 'エラー' })
  }
}

async function deleteItem(item) {
  const label = item.category || '(カテゴリーなし)'
  const ok = await dialog.confirm(`「${label}」を削除しますか？`, { title: '確認' })
  if (!ok) return

  const index = items.value.findIndex((row) => row.id === item.id)
  const removed = items.value.splice(index, 1)[0]
  try {
    await supabaseService.deleteScheduleLabelTemplate(item.id)
    await syncCache()
    emit('refresh')
  } catch (err) {
    console.error('Failed to delete schedule label template:', err)
    items.value.splice(index, 0, removed)
    await dialog.alert(err.message || '削除に失敗しました', { title: 'エラー' })
  }
}

async function addNewItem() {
  const category = newCategory.value.trim() || null
  const schedule_column_index = parseColumnIndexFromSelect(newColumnIndex.value)

  if (isDuplicateColumnIndex(schedule_column_index)) {
    await dialog.alert('同じスケジュール列は既に使用されています', { title: 'エラー' })
    return
  }

  try {
    const created = await supabaseService.insertScheduleLabelTemplate({
      mc_id: Number(selectedMcId.value),
      category,
      schedule_column_index,
    })
    items.value.push(created)
    newCategory.value = ''
    newColumnIndex.value = ''
    await syncCache()
    emit('refresh')
  } catch (err) {
    console.error('Failed to add schedule label template:', err)
    await dialog.alert(err.message || '追加に失敗しました', { title: 'エラー' })
  }
}

function handleDragStart(event, item) {
  draggingId.value = item.id
  event.dataTransfer.effectAllowed = 'move'
  event.dataTransfer.setData('text/plain', item.id)
}

function handleDragEnd() {
  draggingId.value = null
  dragOverId.value = null
}

function handleDragOver(event, item) {
  if (draggingId.value && draggingId.value !== item.id) {
    dragOverId.value = item.id
  }
}

function handleDragLeave(event, item) {
  const related = event.relatedTarget
  if (related instanceof Node && event.currentTarget.contains(related)) return
  if (dragOverId.value === item.id) {
    dragOverId.value = null
  }
}

async function handleDrop(event, targetItem) {
  const draggedId = draggingId.value
  if (!draggedId || draggedId === targetItem.id) {
    dragOverId.value = null
    return
  }

  const draggedIndex = items.value.findIndex((row) => row.id === draggedId)
  const targetIndex = items.value.findIndex((row) => row.id === targetItem.id)
  if (draggedIndex === -1 || targetIndex === -1) {
    dragOverId.value = null
    return
  }

  const snapshot = items.value.map((row) => ({ ...row }))
  const [removed] = items.value.splice(draggedIndex, 1)
  items.value.splice(targetIndex, 0, removed)
  dragOverId.value = null

  const payload = items.value.map((row, index) => ({
    id: row.id,
    sort_order: index,
  }))

  try {
    const refreshed = await supabaseService.reorderScheduleLabelTemplates(payload)
    items.value = refreshed
    await syncCache()
    emit('refresh')
  } catch (err) {
    console.error('Failed to reorder schedule label templates:', err)
    items.value = snapshot
    await dialog.alert(err.message || '並べ替えに失敗しました', { title: 'エラー' })
  }
}

defineExpose({
  loadTemplates,
  reload: loadTemplates,
  loading,
})
</script>

