<template>
  <aside class="original-instruction-panel">
    <div v-if="!hideHeader" class="oip-header">原本</div>
    <div v-if="items.length === 0" class="oip-empty">原本データがありません</div>
    <div v-else class="oip-list">
      <div
        v-for="item in items"
        :key="item.code"
        class="oip-item"
        :class="{
          'oip-item--selected': selectedCode === String(item.code || ''),
          'oip-item--muted-bg': item.mutedBg,
        }"
        draggable="true"
        role="button"
        tabindex="0"
        @mousedown="onItemMouseDown"
        @click="onItemClick($event, item)"
        @selectstart.prevent="onItemSelectStart"
        @dragstart="onDragStart($event, item)"
        @dragend="onDragEnd"
        @dblclick="onItemDblClick($event, item)"
      >
        <div class="oip-code">{{ item.code }}</div>
        <div class="oip-text">{{ item.instruction }}</div>
      </div>
    </div>
  </aside>
</template>

<script setup>
import { ref, watch } from 'vue'
import { writeRoomMatrixDragData } from '../utils/roomMatrixDragData.js'

const props = defineProps({
  items: { type: Array, default: () => [] },
  hideHeader: { type: Boolean, default: false },
})

const emit = defineEmits(['apply'])

const selectedCode = ref(null)
let dragActive = false

watch(
  () => props.items,
  () => {
    selectedCode.value = null
  }
)

function clearTextSelection() {
  if (typeof window !== 'undefined' && window.getSelection) {
    const sel = window.getSelection()
    if (sel) sel.removeAllRanges()
  }
}

function onItemMouseDown(event) {
  if (event?.detail > 1) event.preventDefault()
}

function onItemClick(event, item) {
  if (dragActive) return
  if (event?.type === 'click' && Number(event?.detail) >= 2) return
  const key = String(item?.code || '').trim()
  if (!key) return
  if (selectedCode.value !== key) {
    selectedCode.value = key
    return
  }
  selectedCode.value = null
  emit('apply', item)
}

function onItemDblClick(event, item) {
  if (event) {
    event.preventDefault()
    clearTextSelection()
  }
  selectedCode.value = null
  emit('apply', item)
}

function onItemSelectStart(event) {
  event.preventDefault()
}

function onDragStart(event, item) {
  if (!item?.code) {
    event.preventDefault()
    return
  }
  dragActive = true
  clearTextSelection()
  event.dataTransfer.effectAllowed = 'copy'
  writeRoomMatrixDragData(event.dataTransfer, {
    type: 'original-instruction',
    source: 'original-instruction',
    external_code: item.code,
    instruction: item.instruction || '',
  })
}

function onDragEnd() {
  clearTextSelection()
  requestAnimationFrame(() => {
    dragActive = false
  })
}
</script>

