/**
 * 備考編集モーダル保存用: 先頭・途中の改行は維持、末尾改行は最大1つ。全行空白なら空文字。
 * @param {string[]} lineTexts
 */
export function formatNoteLinesForSave(lineTexts) {
  const texts = (lineTexts || []).map((t) => String(t ?? ''))
  if (texts.every((t) => t.trim() === '')) return ''
  return texts.join('\n').replace(/\n+$/, '\n')
}

/** PDF/UI 上の見かけ行番号（break_before 区切りページ内） */
export function computeVisualRowNumber(slotNumberInPage) {
  const n = Number(slotNumberInPage) || 1
  return ((n - 1) % 3) + 1 + 3 * Math.floor((n - 1) / 6)
}

/** Unicode 丸数字 1–50（51+ は (n) 形式） */
export function formatCircledNumber(n) {
  const v = Number(n)
  if (!Number.isFinite(v) || v < 1) return ''
  if (v <= 20) {
    return String.fromCharCode(0x245f + v)
  }
  if (v <= 35) {
    return String.fromCharCode(0x3251 + (v - 21))
  }
  if (v <= 50) {
    return String.fromCharCode(0x32b1 + (v - 36))
  }
  return `(${v})`
}

/** 見かけ行番号を表示文字に変換（1-50: 丸数字、51+: (51)） */
export function formatVisualRowDisplay(visualRow) {
  return formatCircledNumber(visualRow)
}

/**
 * 備考内 ${code} / ${N} を変換（${N} のみ完全一致、表記ゆれは無視）
 * @param {string} note
 * @param {{ billingItems?: Array, instructionType?: string, slotNumberInPage?: number|null }} options
 */
export function convertNotePlaceholders(note, options = {}) {
  if (!note) return ''

  const {
    billingItems = [],
    instructionType = 'number',
    slotNumberInPage = null
  } = options

  const codePattern = /\$\{([^}]+)\}/g

  return note.replace(codePattern, (match, code) => {
    if (code === 'N') {
      if (slotNumberInPage == null) return match
      const visualRow = computeVisualRowNumber(slotNumberInPage)
      return formatVisualRowDisplay(visualRow)
    }

    const item = billingItems.find((bi) => bi.external_code === code)
    if (!item) {
      return '※※※※※該当無し※※※※※'
    }

    if (instructionType === 'number') {
      const sortOrder = (item.sort_order || 0) + 1
      return `(${sortOrder})`
    }
    return item.description || '※※※※※該当無し※※※※※'
  })
}
