export const CLIENT_UPDATE_MESSAGE =
  'アプリの更新が必要です。\n作業を保存してから再読込(Shift＋F5)をしてください。'

/** YYYYMMDDHHmm 等の固定長文字列を想定した辞書順比較 */
export function isClientUpdateRequired(clientBuildId, minBuildId) {
  if (!minBuildId) return false
  const client = String(clientBuildId || '').trim()
  const min = String(minBuildId).trim()
  // ローカル開発 (npm run dev) は通知対象外
  if (!client || client === 'dev') return false
  return client < min
}

export function getClientUpdateDismissKey(minBuildId) {
  return `client_update_ack_${minBuildId || 'unknown'}`
}

export function isClientUpdateDismissed(minBuildId) {
  if (typeof sessionStorage === 'undefined') return false
  return sessionStorage.getItem(getClientUpdateDismissKey(minBuildId)) === '1'
}

export function markClientUpdateDismissed(minBuildId) {
  if (typeof sessionStorage === 'undefined') return
  sessionStorage.setItem(getClientUpdateDismissKey(minBuildId), '1')
}

export function parseClientUpdateFromResponse(result) {
  if (import.meta.env.DEV) return null
  const update = result?.client_update
  if (!update?.required) return null
  const minBuildId = update.min_build_id ?? null
  if (isClientUpdateDismissed(minBuildId)) return null
  return {
    required: true,
    minBuildId,
    message: update.message || CLIENT_UPDATE_MESSAGE,
  }
}
